  FIELD_OPTIONALLY_ENCLOSED_BY = '"'
  SKIP_HEADER = 1
  NULL_IF = ('', 'NULL', 'null')
  EMPTY_FIELD_AS_NULL = TRUE;

  
  CREATE OR REPLACE STAGE RAW.AZURE_BLOB_STAGE
  URL = 'azure://samplemarutidemo.blob.core.windows.net/marutisuzuki'
  STORAGE_INTEGRATION = AZURE_BLOB_INT
  FILE_FORMAT = RAW.CSV_FF;

  LIST @RAW.AZURE_BLOB_STAGE;


  CREATE OR REPLACE NOTIFICATION INTEGRATION AZURE_BLOB_Q_INT
  ENABLED = TRUE
  TYPE = QUEUE
  NOTIFICATION_PROVIDER = AZURE_STORAGE_QUEUE
  AZURE_STORAGE_QUEUE_PRIMARY_URI = 'https://samplemarutidemo.queue.core.windows.net/testqueue'
  AZURE_TENANT_ID = 'f031fa1a-7a7f-4523-97e4-e3053ecf3690';

DESC INTEGRATION AZURE_BLOB_Q_INT;
  --TRUNCATE TABLE RAW.ERP_PLANT

