    PIN_CODE               VARCHAR,
    REGION                 VARCHAR,
    START_DATE             VARCHAR,
    END_DATE               VARCHAR,
    ACTIVE_FLAG            VARCHAR,
    DEFAULT_SHIFT_PATTERN  VARCHAR,
    -- Audit
    DW_CREATED_TS          TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
