-- 8. RAW – Planning / Forecast / Backlog (ERP/Planning App)


CREATE OR REPLACE TABLE RAW.ERP_DEMAND_FORECAST (
    FORECAST_RUN_ID          VARCHAR,
    FORECAST_SOURCE          VARCHAR,
    FORECAST_DATE            VARCHAR,
    DEALER_ID                VARCHAR,
    VARIANT_ID               VARCHAR,
    FORECAST_DEMAND_UNITS    VARCHAR,
    FORECAST_GENERATED_DATE  VARCHAR,
    SEASONAL_PEAK_FLAG       VARCHAR,
    -- Audit
    DW_CREATED_TS            TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
    DW_LAST_UPDATED_TS       TIMESTAMP_LTZ,
    DW_BATCH_ID              VARCHAR(50),
    DW_SOURCE_FILE_NAME      VARCHAR(500)
);

CREATE OR REPLACE TABLE RAW.ERP_BACKLOG_SNAPSHOT (
    BACKLOG_RUN_ID                   VARCHAR,
    AS_OF_DATE                       VARCHAR,
    PLANT_ID                         VARCHAR,
    VARIANT_ID                       VARCHAR,
    TOTAL_OPEN_BOOKINGS_UNITS        VARCHAR,
    NEAR_TERM_FORECAST_30D_UNITS     VARCHAR,
    PLANT_FINISHED_STOCK_UNITS       VARCHAR,
    DEALER_STOCK_UNITS               VARCHAR,
    IN_TRANSIT_VEHICLE_UNITS         VARCHAR,
    AVAILABLE_VEHICLE_SUPPLY_UNITS   VARCHAR,
    PLANNED_PRODUCTION_30D_UNITS     VARCHAR,
    EXPECTED_VENDOR_SUPPLY_30D_UOM   VARCHAR,
    BACKLOG_UNITS                    VARCHAR,
    EXPECTED_AVG_DELAY_DAYS          VARCHAR,
    RECOMMENDED_EXTRA_PRODUCTION_UNITS VARCHAR,
    RECOMMENDED_EXTRA_PROCUREMENT_UOM VARCHAR,
    SEASONAL_PEAK_FLAG               VARCHAR,
    -- Audit
    DW_CREATED_TS                    TIMESTAMP_LTZ DEFAULT CURRENT_TIMESTAMP(),
    DW_LAST_UPDATED_TS               TIMESTAMP_LTZ,
    DW_BATCH_ID                      VARCHAR(50),
    DW_SOURCE_FILE_NAME              VARCHAR(500)
);
