UNION ALL SELECT 'RAW.ERP_VENDOR',                 COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_VENDOR
UNION ALL SELECT 'RAW.ERP_MATERIAL',               COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_MATERIAL
UNION ALL SELECT 'RAW.ERP_BRAND',                  COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_BRAND
UNION ALL SELECT 'RAW.ERP_MODEL',                  COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_MODEL
UNION ALL SELECT 'RAW.ERP_VARIANT',                COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_VARIANT
UNION ALL SELECT 'RAW.ERP_DEALER',                 COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_DEALER
UNION ALL SELECT 'RAW.ERP_SHOWROOM',               COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_SHOWROOM
UNION ALL SELECT 'RAW.ERP_SERVICE_CENTER',         COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_SERVICE_CENTER
UNION ALL SELECT 'RAW.ERP_CUSTOMER',               COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_CUSTOMER
UNION ALL SELECT 'RAW.ERP_SALESPERSON',            COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_SALESPERSON
