UNION ALL SELECT 'RAW.ERP_PURCHASE_CONTRACT_LINE', COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_PURCHASE_CONTRACT_LINE
UNION ALL SELECT 'RAW.ERP_PO_HEADER',              COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_PO_HEADER
UNION ALL SELECT 'RAW.ERP_PO_LINE',                COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_PO_LINE
UNION ALL SELECT 'RAW.ERP_GRN',                    COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_GRN
UNION ALL SELECT 'RAW.ERP_PRODUCTION_DAILY',       COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_PRODUCTION_DAILY
UNION ALL SELECT 'RAW.ERP_PLANT_INVENTORY_SNAP',   COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_PLANT_INVENTORY_SNAP
