UNION ALL SELECT 'RAW.ERP_DEALER_STOCK_SNAP',      COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_DEALER_STOCK_SNAP
UNION ALL SELECT 'RAW.ERP_BOOKING',                COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_BOOKING
UNION ALL SELECT 'RAW.ERP_SALES_INVOICE_HDR',      COUNT(*) FROM MARUTI_AUTO_DWH.RAW.ERP_SALES_INVOICE_HDR
