USE DATABASE MARUTI_AUTO_DWH;
CREATE SCHEMA IF NOT EXISTS STG;
USE SCHEMA STG;

-- 1. Master data STG views
--# 1.1 PLANT
--SELECT * FROM STG.VW_ERP_PLANT;
CREATE OR REPLACE VIEW STG.VW_ERP_PLANT AS
SELECT
  TRIM(PLANT_ID)               AS PLANT_ID,
  TRIM(PLANT_CODE)             AS PLANT_CODE,
  TRIM(PLANT_NAME)             AS PLANT_NAME,
  TRIM(PLANT_TYPE)             AS PLANT_TYPE,
  TRIM(COMPANY_CODE)           AS COMPANY_CODE,
  TRIM(ADDRESS_LINE1)          AS ADDRESS_LINE1,
  TRIM(ADDRESS_LINE2)          AS ADDRESS_LINE2,
  TRIM(CITY)                   AS CITY,
  TRIM(DISTRICT)               AS DISTRICT,
  TRIM(STATE)                  AS STATE,
  TRIM(COUNTRY)                AS COUNTRY,
  TRIM(PIN_CODE)               AS PIN_CODE,
  TRIM(REGION)                 AS REGION,
  TRY_TO_DATE(START_DATE, 'YYYY-MM-DD') AS START_DATE,
  TRY_TO_DATE(END_DATE,   'YYYY-MM-DD') AS END_DATE,
  IFF(UPPER(NVL(ACTIVE_FLAG, 'N')) IN ('Y','1','TRUE'), 'Y', 'N') AS ACTIVE_FLAG,
  TRY_TO_NUMBER(NULLIF(DEFAULT_SHIFT_PATTERN, '')) AS DEFAULT_SHIFT_PATTERN,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_PLANT;


--# 1.2 VENDOR


CREATE OR REPLACE VIEW STG.VW_ERP_VENDOR AS
SELECT
  TRIM(VENDOR_ID)                  AS VENDOR_ID,
  TRIM(VENDOR_CODE)                AS VENDOR_CODE,
  TRIM(VENDOR_NAME)                AS VENDOR_NAME,
  TRIM(VENDOR_TYPE)                AS VENDOR_TYPE,
  TRIM(ADDRESS_LINE1)              AS ADDRESS_LINE1,
  TRIM(ADDRESS_LINE2)              AS ADDRESS_LINE2,
  TRIM(CITY)                       AS CITY,
  TRIM(DISTRICT)                   AS DISTRICT,
  TRIM(STATE)                      AS STATE,
  TRIM(COUNTRY)                    AS COUNTRY,
  TRIM(PIN_CODE)                   AS PIN_CODE,
  TRIM(REGION)                     AS REGION,
  TRIM(CONTACT_PERSON)             AS CONTACT_PERSON,
  TRIM(CONTACT_EMAIL)              AS CONTACT_EMAIL,
  TRIM(CONTACT_PHONE)              AS CONTACT_PHONE,
  TRIM(DEFAULT_CURRENCY)           AS DEFAULT_CURRENCY,
  TRIM(PAYMENT_TERMS_CODE)         AS PAYMENT_TERMS_CODE,
  IFF(UPPER(NVL(PREFERRED_FLAG, 'N')) IN ('Y','1','TRUE'), 'Y', 'N') AS PREFERRED_FLAG,
  NVL(TRY_TO_NUMBER(NULLIF(AVG_HIST_LEAD_TIME_DAYS,'')), 0)    AS AVG_HIST_LEAD_TIME_DAYS,
  NVL(TRY_TO_NUMBER(NULLIF(LEAD_TIME_VARIABILITY_DAYS,'')), 0) AS LEAD_TIME_VARIABILITY_DAYS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()              AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_VENDOR;


--# 1.3 MATERIAL


CREATE OR REPLACE VIEW STG.VW_ERP_MATERIAL AS
SELECT
  TRIM(MATERIAL_ID)          AS MATERIAL_ID,
  TRIM(MATERIAL_CODE)        AS MATERIAL_CODE,
  TRIM(MATERIAL_NAME)        AS MATERIAL_NAME,
  TRIM(MATERIAL_CATEGORY)    AS MATERIAL_CATEGORY,
  TRIM(MATERIAL_GROUP)       AS MATERIAL_GROUP,
  TRIM(BASE_UOM)             AS BASE_UOM,
  TRIM(PURCHASE_UOM)         AS PURCHASE_UOM,
  TRIM(CRITICALITY_LEVEL)    AS CRITICALITY_LEVEL,
  IFF(UPPER(NVL(HAZARDOUS_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N') AS HAZARDOUS_FLAG,
  IFF(UPPER(NVL(USED_IN_BOM_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N') AS USED_IN_BOM_FLAG,
  TRIM(STATUS)               AS STATUS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_MATERIAL;


--# 1.4 BRAND / MODEL / VARIANT


CREATE OR REPLACE VIEW STG.VW_ERP_BRAND AS
SELECT
  TRIM(BRAND_ID)             AS BRAND_ID,
  TRIM(BRAND_CODE)           AS BRAND_CODE,
  TRIM(BRAND_NAME)           AS BRAND_NAME,
  IFF(UPPER(NVL(ACTIVE_FLAG,'N')) IN ('Y','1','TRUE'), 'Y', 'N') AS ACTIVE_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_BRAND;

--SELECT * FROM STG.VW_ERP_MODEL;
--SELECT * FROM RAW.ERP_MODEL;
CREATE OR REPLACE VIEW STG.VW_ERP_MODEL AS
SELECT
  TRIM(MODEL_ID)             AS MODEL_ID,
  TRIM(BRAND_ID)             AS BRAND_ID,
  TRIM(MODEL_CODE)           AS MODEL_CODE,
  TRIM(MODEL_NAME)           AS MODEL_NAME,
  TRIM(BODY_TYPE)            AS BODY_TYPE,
  to_date(TRY_TO_TIMESTAMP(LAUNCH_DATE)) AS LAUNCH_DATE,
  to_date(TRY_TO_TIMESTAMP(DISCONTINUED_DATE)) AS DISCONTINUED_DATE,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_MODEL;

CREATE OR REPLACE VIEW STG.VW_ERP_VARIANT AS
SELECT
  TRIM(VARIANT_ID)           AS VARIANT_ID,
  TRIM(MODEL_ID)             AS MODEL_ID,
  TRIM(VARIANT_CODE)         AS VARIANT_CODE,
  TRIM(VARIANT_NAME)         AS VARIANT_NAME,
  TRIM(FUEL_TYPE)            AS FUEL_TYPE,
  TRIM(TRANSMISSION_TYPE)    AS TRANSMISSION_TYPE,
  TRY_TO_NUMBER(NULLIF(ENGINE_CC,'')) AS ENGINE_CC,
  TRIM(TRIM_LEVEL)           AS TRIM_LEVEL,
  IFF(UPPER(NVL(ACTIVE_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N') AS ACTIVE_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_VARIANT;


--# 1.5 DEALER / SHOWROOM / SERVICE CENTER

--SELECT * FROM RAW.ERP_DEALER;
CREATE OR REPLACE VIEW STG.VW_ERP_DEALER AS
SELECT
  TRIM(DEALER_ID)            AS DEALER_ID,
  TRIM(DEALER_CODE)          AS DEALER_CODE,
  TRIM(DEALER_GROUP_NAME)    AS DEALER_GROUP_NAME,
  TRIM(GSTIN)                AS GSTIN,
  TRIM(PAN_NO)               AS PAN_NO,
  TRIM(ADDRESS_LINE1)        AS ADDRESS_LINE1,
  TRIM(ADDRESS_LINE2)        AS ADDRESS_LINE2,
  TRIM(CITY)                 AS CITY,
  TRIM(DISTRICT)             AS DISTRICT,
  TRIM(STATE)                AS STATE,
  TRIM(COUNTRY)              AS COUNTRY,
  TRIM(PIN_CODE)             AS PIN_CODE,
  TRIM(REGION)               AS REGION,
  TRIM(CHANNEL)              AS CHANNEL,
  TRY_TO_DATE(OPENING_DATE, 'YYYY-MM-DD') AS OPENING_DATE,
  TRY_TO_DATE(CLOSING_DATE, 'YYYY-MM-DD') AS CLOSING_DATE,
  IFF(UPPER(NVL(ACTIVE_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N') AS ACTIVE_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_DEALER;

--SELECT * FROM RAW.ERP_SHOWROOM;
CREATE OR REPLACE VIEW STG.VW_ERP_SHOWROOM AS
SELECT
  TRIM(SHOWROOM_ID)          AS SHOWROOM_ID,
  TRIM(DEALER_ID)            AS DEALER_ID,
  TRIM(SHOWROOM_CODE)        AS SHOWROOM_CODE,
  TRIM(SHOWROOM_NAME)        AS SHOWROOM_NAME,
  TRIM(SHOWROOM_TYPE)        AS SHOWROOM_TYPE,
  TRIM(ADDRESS_LINE1)        AS ADDRESS_LINE1,
  TRIM(ADDRESS_LINE2)        AS ADDRESS_LINE2,
  TRIM(CITY)                 AS CITY,
  TRIM(DISTRICT)             AS DISTRICT,
  TRIM(STATE)                AS STATE,
  TRIM(COUNTRY)              AS COUNTRY,
  TRIM(PIN_CODE)             AS PIN_CODE,
  TRIM(CHANNEL)              AS CHANNEL,
  TRY_TO_DATE(OPENING_DATE,'YYYY-MM-DD') AS OPENING_DATE,
  TRY_TO_DATE(CLOSING_DATE,'YYYY-MM-DD') AS CLOSING_DATE,
  IFF(UPPER(NVL(ACTIVE_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N') AS ACTIVE_FLAG,
  IFF(UPPER(NVL(HAS_SERVICE_CENTER_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N')
                                AS HAS_SERVICE_CENTER_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_SHOWROOM;

CREATE OR REPLACE VIEW STG.VW_ERP_SERVICE_CENTER AS
SELECT
  TRIM(SERVICE_CENTER_ID)    AS SERVICE_CENTER_ID,
  TRIM(DEALER_ID)            AS DEALER_ID,
  TRIM(SERVICE_CENTER_CODE)  AS SERVICE_CENTER_CODE,
  TRIM(SERVICE_CENTER_NAME)  AS SERVICE_CENTER_NAME,
  TRIM(ADDRESS_LINE1)        AS ADDRESS_LINE1,
  TRIM(ADDRESS_LINE2)        AS ADDRESS_LINE2,
  TRIM(CITY)                 AS CITY,
  TRIM(DISTRICT)             AS DISTRICT,
  TRIM(STATE)                AS STATE,
  TRIM(COUNTRY)              AS COUNTRY,
  TRIM(PIN_CODE)             AS PIN_CODE,
  IFF(UPPER(NVL(IS_AUTHORIZED_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N')
                                AS IS_AUTHORIZED_FLAG,
  TRY_TO_DATE(OPENING_DATE,'YYYY-MM-DD') AS OPENING_DATE,
  IFF(UPPER(NVL(ACTIVE_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N') AS ACTIVE_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_SERVICE_CENTER;
SELECT * FROM RAW.ERP_SERVICE_CENTER;

--# 1.6 CUSTOMER / SALESPERSON


CREATE OR REPLACE VIEW STG.VW_ERP_CUSTOMER AS
SELECT
  TRIM(CUSTOMER_ID)          AS CUSTOMER_ID,
  TRIM(CUSTOMER_EXTERNAL_ID) AS CUSTOMER_EXTERNAL_ID,
  TRIM(CUSTOMER_NAME)        AS CUSTOMER_NAME,
  TRIM(GENDER)               AS GENDER,
  to_date(TRY_TO_TIMESTAMP(DOB)) AS DOB,
  TRIM(MOBILE_NUMBER)        AS MOBILE_NUMBER,
  TRIM(EMAIL_ID)             AS EMAIL_ID,
  TRIM(ADDRESS_LINE1)        AS ADDRESS_LINE1,
  TRIM(ADDRESS_LINE2)        AS ADDRESS_LINE2,
  TRIM(CITY)                 AS CITY,
  TRIM(DISTRICT)             AS DISTRICT,
  TRIM(STATE)                AS STATE,
  TRIM(COUNTRY)              AS COUNTRY,
  TRIM(PIN_CODE)             AS PIN_CODE,
  TRIM(CUSTOMER_SEGMENT)     AS CUSTOMER_SEGMENT,
  TRIM(LOYALTY_TIER)         AS LOYALTY_TIER,
  to_date(TRY_TO_TIMESTAMP(FIRST_PURCHASE_DATE)) AS FIRST_PURCHASE_DATE,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_CUSTOMER;
SELECT * FROM RAW.ERP_CUSTOMER;

CREATE OR REPLACE VIEW STG.VW_ERP_SALESPERSON AS
SELECT
  TRIM(SALESPERSON_ID)       AS SALESPERSON_ID,
  TRIM(DEALER_ID)            AS DEALER_ID,
  TRIM(EMPLOYEE_NO)          AS EMPLOYEE_NO,
  TRIM(FULL_NAME)            AS FULL_NAME,
  TRIM(DESIGNATION)          AS DESIGNATION,
  TRIM(DEPARTMENT)           AS DEPARTMENT,
  TRY_TO_DATE(JOIN_DATE,'YYYY-MM-DD') AS JOIN_DATE,
  TRY_TO_DATE(EXIT_DATE,'YYYY-MM-DD') AS EXIT_DATE,
  IFF(UPPER(NVL(ACTIVE_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N') AS ACTIVE_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()        AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_SALESPERSON;
SELECT * FROM RAW.ERP_SALESPERSON;

---

-- 2. Procurement & Supply STG views

--# 2.1 Purchase contracts


CREATE OR REPLACE VIEW STG.VW_ERP_PURCHASE_CONTRACT AS
SELECT
  TRIM(CONTRACT_ID)            AS CONTRACT_ID,
  TRIM(CONTRACT_NO)            AS CONTRACT_NO,
  TRIM(VENDOR_ID)              AS VENDOR_ID,
  TRIM(PLANT_ID)               AS PLANT_ID,
  to_date(TRY_TO_TIMESTAMP(VALID_FROM_DATE)) AS VALID_FROM_DATE,
  to_date(TRY_TO_TIMESTAMP(VALID_TO_DATE))   AS VALID_TO_DATE,
  TRIM(PAYMENT_TERMS_CODE)     AS PAYMENT_TERMS_CODE,
  NVL(TRY_TO_NUMBER(NULLIF(STANDARD_LEAD_TIME_DAYS,'')), 0) AS STANDARD_LEAD_TIME_DAYS,
  NVL(TRY_TO_NUMBER(NULLIF(LEAD_TIME_BUFFER_DAYS,'')), 0)   AS LEAD_TIME_BUFFER_DAYS,
  TRIM(CONTRACT_STATUS)        AS CONTRACT_STATUS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_PURCHASE_CONTRACT;
SELECT * FROM RAW.ERP_PURCHASE_CONTRACT;

CREATE OR REPLACE VIEW STG.VW_ERP_PURCHASE_CONTRACT_LINE AS
SELECT
  TRIM(CONTRACT_LINE_ID)       AS CONTRACT_LINE_ID,
  TRIM(CONTRACT_ID)            AS CONTRACT_ID,
  TRIM(MATERIAL_ID)            AS MATERIAL_ID,
  NVL(TRY_TO_NUMBER(NULLIF(MIN_ORDER_QTY,'')), 0)      AS MIN_ORDER_QTY,
  NVL(TRY_TO_NUMBER(NULLIF(PRICE_PER_UOM,'')), 0)      AS PRICE_PER_UOM,
  TRIM(PRICE_CURRENCY)         AS PRICE_CURRENCY,
  IFF(UPPER(NVL(PENALTY_LATE_DELIVERY_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N')
                                AS PENALTY_LATE_DELIVERY_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_PURCHASE_CONTRACT_LINE;


--# 2.2 Purchase orders & GRN


CREATE OR REPLACE VIEW STG.VW_ERP_PO_HEADER AS
SELECT
  TRIM(PO_ID)                  AS PO_ID,
  TRIM(PO_NO)                  AS PO_NO,
  TO_DATE(TRY_TO_TIMESTAMP(PO_DATE)) AS PO_DATE,
  TRIM(VENDOR_ID)              AS VENDOR_ID,
  TRIM(PLANT_ID)               AS PLANT_ID,
  TRIM(CONTRACT_ID)            AS CONTRACT_ID,
  TRIM(CURRENCY_CODE)          AS CURRENCY_CODE,
  TRIM(PAYMENT_TERMS_CODE)     AS PAYMENT_TERMS_CODE,
  TRIM(PO_STATUS)              AS PO_STATUS,
  TRIM(CREATED_BY)             AS CREATED_BY,
  TRY_TO_TIMESTAMP_NTZ(CREATED_TS) AS CREATED_TS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_PO_HEADER;
SELECT * FROM RAW.ERP_PO_HEADER;

CREATE OR REPLACE VIEW STG.VW_ERP_PO_LINE AS
SELECT
  TRIM(PO_LINE_ID)             AS PO_LINE_ID,
  TRIM(PO_ID)                  AS PO_ID,
  TRY_TO_NUMBER(NULLIF(LINE_NO,''))     AS LINE_NO,
  TRIM(MATERIAL_ID)            AS MATERIAL_ID,
  NVL(TRY_TO_NUMBER(NULLIF(ORDER_QTY,'')), 0)   AS ORDER_QTY,
  TRIM(ORDER_UOM)              AS ORDER_UOM,
  NVL(TRY_TO_NUMBER(NULLIF(UNIT_PRICE,'')), 0)  AS UNIT_PRICE,
  NVL(TRY_TO_NUMBER(NULLIF(LINE_AMOUNT,'')), 0) AS LINE_AMOUNT,
  TO_DATE(TRY_TO_TIMESTAMP(PROMISED_DELIVERY_DATE)) AS PROMISED_DELIVERY_DATE,
  TO_DATE(TRY_TO_TIMESTAMP(EXPECTED_ARRIVAL_DATE))  AS EXPECTED_ARRIVAL_DATE,
  IFF(UPPER(NVL(SEASONAL_PEAK_FLAG,'N')) IN ('Y','1','TRUE'), 'Y','N') AS SEASONAL_PEAK_FLAG,
  TRIM(LINE_STATUS)            AS LINE_STATUS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_PO_LINE;
SELECT * FROM  RAW.ERP_PO_LINE;

CREATE OR REPLACE VIEW STG.VW_ERP_GRN AS
SELECT
  TRIM(GRN_ID)                 AS GRN_ID,
  TRIM(GRN_NO)                 AS GRN_NO,
  TO_DATE(TRY_TO_TIMESTAMP(GRN_DATE)) AS GRN_DATE,
  TRIM(PO_LINE_ID)             AS PO_LINE_ID,
  TRIM(VENDOR_ID)              AS VENDOR_ID,
  TRIM(MATERIAL_ID)            AS MATERIAL_ID,
  TRIM(PLANT_ID)               AS PLANT_ID,
  NVL(TRY_TO_NUMBER(NULLIF(RECEIVED_QTY,'')), 0) AS RECEIVED_QTY,
  NVL(TRY_TO_NUMBER(NULLIF(REJECTED_QTY,'')), 0) AS REJECTED_QTY,
  NVL(TRY_TO_NUMBER(NULLIF(ACCEPTED_QTY,'')), 0) AS ACCEPTED_QTY,
  TO_DATE(TRY_TO_TIMESTAMP(EXPECTED_ARRIVAL_DATE)) AS EXPECTED_ARRIVAL_DATE,
  TO_DATE(TRY_TO_TIMESTAMP(ACTUAL_ARRIVAL_DATE))   AS ACTUAL_ARRIVAL_DATE,
  NVL(TRY_TO_NUMBER(NULLIF(DELIVERY_DELAY_DAYS,'')), 0) AS DELIVERY_DELAY_DAYS,
  NVL(TRY_TO_NUMBER(NULLIF(LEAD_TIME_DAYS,'')), 0)      AS LEAD_TIME_DAYS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_GRN;
SELECT * FROM RAW.ERP_GRN;

---

-- 3. Production & Inventory STG views


CREATE OR REPLACE VIEW STG.VW_ERP_VEHICLE_PRODUCTION AS
SELECT
  TRIM(VEHICLE_ID)             AS VEHICLE_ID,
  TRIM(VIN)                    AS VIN,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  TRIM(PLANT_ID)               AS PLANT_ID,
  TO_DATE(TRY_TO_TIMESTAMP(PRODUCTION_DATE)) AS PRODUCTION_DATE,
  TRIM(PRODUCTION_BATCH_NO)    AS PRODUCTION_BATCH_NO,
  TRIM(ENGINE_NO)              AS ENGINE_NO,
  TRIM(CHASSIS_NO)             AS CHASSIS_NO,
  TO_DATE(TRY_TO_TIMESTAMP(WARRANTY_START_DATE)) AS WARRANTY_START_DATE,
  NVL(TRY_TO_NUMBER(NULLIF(WARRANTY_DURATION_MONTHS,'')),0)
                                AS WARRANTY_DURATION_MONTHS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_VEHICLE_PRODUCTION;

CREATE OR REPLACE VIEW STG.VW_ERP_PRODUCTION_DAILY AS
SELECT
  TRIM(PROD_RECORD_ID)         AS PROD_RECORD_ID,
  to_date(TRY_TO_TIMESTAMP(PROD_DATE)) AS PROD_DATE,
  TRIM(PLANT_ID)               AS PLANT_ID,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  TRIM(SHIFT_CODE)             AS SHIFT_CODE,
  NVL(TRY_TO_NUMBER(NULLIF(UNITS_PRODUCED,'')), 0)  AS UNITS_PRODUCED,
  NVL(TRY_TO_NUMBER(NULLIF(UNITS_REJECTED,'')), 0)  AS UNITS_REJECTED,
  NVL(TRY_TO_NUMBER(NULLIF(UNITS_REWORKED,'')), 0)  AS UNITS_REWORKED,
  NVL(TRY_TO_NUMBER(NULLIF(TOTAL_PRODUCTION_HRS,'')), 0) AS TOTAL_PRODUCTION_HRS,
  NVL(TRY_TO_NUMBER(NULLIF(OEE_PERCENT,'')),0)      AS OEE_PERCENT,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_PRODUCTION_DAILY;

CREATE OR REPLACE VIEW STG.VW_ERP_PLANT_INVENTORY_SNAP AS
SELECT
  TRIM(SNAPSHOT_ID)            AS SNAPSHOT_ID,
  TO_DATE(TRY_TO_TIMESTAMP(SNAPSHOT_DATE)) AS SNAPSHOT_DATE,
  TRIM(PLANT_ID)               AS PLANT_ID,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  NVL(TRY_TO_NUMBER(NULLIF(OPENING_STOCK_UNITS,'')), 0)  AS OPENING_STOCK_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(UNITS_PRODUCED,'')), 0)       AS UNITS_PRODUCED,
  NVL(TRY_TO_NUMBER(NULLIF(UNITS_DISPATCHED,'')), 0)     AS UNITS_DISPATCHED,
  NVL(TRY_TO_NUMBER(NULLIF(CLOSING_STOCK_UNITS,'')), 0)  AS CLOSING_STOCK_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(AGEING_30_PLUS_UNITS,'')), 0) AS AGEING_30_PLUS_UNITS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_PLANT_INVENTORY_SNAP;

CREATE OR REPLACE VIEW STG.VW_ERP_VEHICLE_DISPATCH AS
SELECT
  TRIM(DISPATCH_ID)            AS DISPATCH_ID,
  TRIM(DISPATCH_DOC_NO)        AS DISPATCH_DOC_NO,
  TO_DATE(TRY_TO_TIMESTAMP(DISPATCH_DATE)) AS DISPATCH_DATE,
  TRIM(PLANT_ID)               AS PLANT_ID,
  TRIM(DEALER_ID)              AS DEALER_ID,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  NVL(TRY_TO_NUMBER(NULLIF(DISPATCH_QTY,'')),0) AS DISPATCH_QTY,
  NVL(TRY_TO_NUMBER(NULLIF(FREIGHT_COST,'')),0) AS FREIGHT_COST,
  TO_DATE(TRY_TO_TIMESTAMP(EXPECTED_ARRIVAL_DATE)) AS EXPECTED_ARRIVAL_DATE,
  TO_DATE(TRY_TO_TIMESTAMP(ACTUAL_ARRIVAL_DATE))   AS ACTUAL_ARRIVAL_DATE,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_VEHICLE_DISPATCH;


---

-- 4. Sales & Dealer Operations STG views


CREATE OR REPLACE VIEW STG.VW_ERP_DEALER_STOCK_SNAP AS
SELECT
  TRIM(SNAPSHOT_ID)            AS SNAPSHOT_ID,
  TO_DATE(TRY_TO_TIMESTAMP(SNAPSHOT_DATE)) AS SNAPSHOT_DATE,
  TRIM(DEALER_ID)              AS DEALER_ID,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  NVL(TRY_TO_NUMBER(NULLIF(OPENING_STOCK_UNITS,'')), 0)   AS OPENING_STOCK_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(UNITS_RECEIVED,'')), 0)        AS UNITS_RECEIVED,
  NVL(TRY_TO_NUMBER(NULLIF(UNITS_SOLD,'')), 0)            AS UNITS_SOLD,
  NVL(TRY_TO_NUMBER(NULLIF(UNITS_TRANSFERRED_OUT,'')), 0) AS UNITS_TRANSFERRED_OUT,
  NVL(TRY_TO_NUMBER(NULLIF(CLOSING_STOCK_UNITS,'')), 0)   AS CLOSING_STOCK_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(TEST_DRIVE_VEHICLES,'')), 0)   AS TEST_DRIVE_VEHICLES,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_DEALER_STOCK_SNAP;

CREATE OR REPLACE VIEW STG.VW_ERP_BOOKING AS
SELECT
  TRIM(BOOKING_ID)             AS BOOKING_ID,
  TRIM(BOOKING_NO)             AS BOOKING_NO,
  TO_DATE(TRY_TO_TIMESTAMP(BOOKING_DATE)) AS BOOKING_DATE,
  TRIM(DEALER_ID)              AS DEALER_ID,
  TRIM(SHOWROOM_ID)            AS SHOWROOM_ID,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  TRIM(CUSTOMER_ID)            AS CUSTOMER_ID,
  TRIM(SALESPERSON_ID)         AS SALESPERSON_ID,
  NVL(TRY_TO_NUMBER(NULLIF(BOOKING_AMOUNT,'')),0) AS BOOKING_AMOUNT,
  TRIM(BOOKING_STATUS)         AS BOOKING_STATUS,
  TO_DATE(TRY_TO_TIMESTAMP(EXPECTED_DELIVERY_DATE)) AS EXPECTED_DELIVERY_DATE,
  TO_DATE(TRY_TO_TIMESTAMP(CANCEL_DATE))            AS CANCEL_DATE,
  TRIM(CANCEL_REASON)           AS CANCEL_REASON,
  NVL(TRY_TO_NUMBER(NULLIF(PREDICTED_CONVERSION_PROB,'')),0) AS PREDICTED_CONVERSION_PROB,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_BOOKING;

CREATE OR REPLACE VIEW STG.VW_ERP_SALES_INVOICE_HDR AS
SELECT
  TRIM(INVOICE_ID)             AS INVOICE_ID,
  TRIM(INVOICE_NO)             AS INVOICE_NO,
  TO_DATE(TRY_TO_TIMESTAMP(INVOICE_DATE)) AS INVOICE_DATE,
  TO_DATE(TRY_TO_TIMESTAMP(DELIVERY_DATE)) AS DELIVERY_DATE,
  TRIM(DEALER_ID)              AS DEALER_ID,
  TRIM(CUSTOMER_ID)            AS CUSTOMER_ID,
  TRIM(SALESPERSON_ID)         AS SALESPERSON_ID,
  TRIM(PAYMENT_MODE)           AS PAYMENT_MODE,
  TRIM(PAYMENT_STATUS)         AS PAYMENT_STATUS,
  NVL(TRY_TO_NUMBER(NULLIF(DOWN_PAYMENT_AMOUNT,'')),0) AS DOWN_PAYMENT_AMOUNT,
  NVL(TRY_TO_NUMBER(NULLIF(LOAN_AMOUNT,'')),0)         AS LOAN_AMOUNT,
  NVL(TRY_TO_NUMBER(NULLIF(TOTAL_EXSHOWROOM_PRICE,'')),0) AS TOTAL_EXSHOWROOM_PRICE,
  NVL(TRY_TO_NUMBER(NULLIF(TOTAL_DISCOUNT_AMOUNT,'')),0)  AS TOTAL_DISCOUNT_AMOUNT,
  NVL(TRY_TO_NUMBER(NULLIF(TOTAL_ONROAD_PRICE,'')),0)     AS TOTAL_ONROAD_PRICE,
  TRIM(BOOKING_ID)             AS BOOKING_ID,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_SALES_INVOICE_HDR;

CREATE OR REPLACE VIEW STG.VW_ERP_SALES_INVOICE_LINE AS
SELECT
  TRIM(INVOICE_LINE_ID)        AS INVOICE_LINE_ID,
  TRIM(INVOICE_ID)             AS INVOICE_ID,
  TRIM(VEHICLE_ID)             AS VEHICLE_ID,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  NVL(TRY_TO_NUMBER(NULLIF(EXSHOWROOM_PRICE,'')),0) AS EXSHOWROOM_PRICE,
  NVL(TRY_TO_NUMBER(NULLIF(DISCOUNT_AMOUNT,'')),0)  AS DISCOUNT_AMOUNT,
  NVL(TRY_TO_NUMBER(NULLIF(ONROAD_PRICE,'')),0)     AS ONROAD_PRICE,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_SALES_INVOICE_LINE;


