-- 5. Service, Warranty & Feedback STG views


CREATE OR REPLACE VIEW STG.VW_ERP_FAULT_CODE AS
SELECT
  TRIM(FAULT_CODE_ID)          AS FAULT_CODE_ID,
  TRIM(FAULT_CODE)             AS FAULT_CODE,
  TRIM(FAULT_DESCRIPTION)      AS FAULT_DESCRIPTION,
  TRIM(SEVERITY_LEVEL)         AS SEVERITY_LEVEL,
  TRIM(SYSTEM_AREA)            AS SYSTEM_AREA,
  IFF(UPPER(NVL(IS_MANUFACTURING_DEFECT_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N')
                                AS IS_MANUFACTURING_DEFECT_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_FAULT_CODE;

CREATE OR REPLACE VIEW STG.VW_ERP_SERVICE_JOB_TYPE AS
SELECT
  TRIM(SERVICE_JOB_TYPE_ID)    AS SERVICE_JOB_TYPE_ID,
  TRIM(JOB_TYPE_CODE)          AS JOB_TYPE_CODE,
  TRIM(JOB_TYPE_NAME)          AS JOB_TYPE_NAME,
  TRIM(JOB_CATEGORY)           AS JOB_CATEGORY,
  IFF(UPPER(NVL(IS_WARRANTY_ELIGIBLE_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N')
                                AS IS_WARRANTY_ELIGIBLE_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_SERVICE_JOB_TYPE;

CREATE OR REPLACE VIEW STG.VW_ERP_SERVICE_ORDER_HDR AS
SELECT
  TRIM(SERVICE_ORDER_ID)       AS SERVICE_ORDER_ID,
  TRIM(SERVICE_ORDER_NO)       AS SERVICE_ORDER_NO,
  TO_DATE(TRY_TO_TIMESTAMP(SERVICE_DATE)) AS SERVICE_DATE,
  TRIM(SERVICE_CENTER_ID)      AS SERVICE_CENTER_ID,
  TRIM(DEALER_ID)              AS DEALER_ID,
  TRIM(VEHICLE_ID)             AS VEHICLE_ID,
  TRIM(CUSTOMER_ID)            AS CUSTOMER_ID,
  NVL(TRY_TO_NUMBER(NULLIF(KM_ODOMETER_READING,'')),0) AS KM_ODOMETER_READING,
  NVL(TRY_TO_NUMBER(NULLIF(LABOUR_AMOUNT,'')),0)       AS LABOUR_AMOUNT,
  NVL(TRY_TO_NUMBER(NULLIF(PARTS_AMOUNT,'')),0)        AS PARTS_AMOUNT,
  NVL(TRY_TO_NUMBER(NULLIF(TOTAL_BILL_AMOUNT,'')),0)   AS TOTAL_BILL_AMOUNT,
  IFF(UPPER(NVL(IS_WARRANTY_COVERED_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N')
                                AS IS_WARRANTY_COVERED_FLAG,
  NVL(TRY_TO_NUMBER(NULLIF(CUSTOMER_SATISFACTION_SCORE,'')),0)
                                AS CUSTOMER_SATISFACTION_SCORE,
  NVL(TRY_TO_NUMBER(NULLIF(NPS_SCORE,'')),0)           AS NPS_SCORE,
  TO_DATE(TRY_TO_TIMESTAMP(NEXT_SERVICE_DUE_DATE)) AS NEXT_SERVICE_DUE_DATE,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_SERVICE_ORDER_HDR;

CREATE OR REPLACE VIEW STG.VW_ERP_SERVICE_ORDER_LINE AS
SELECT
  TRIM(SERVICE_ORDER_LINE_ID)  AS SERVICE_ORDER_LINE_ID,
  TRIM(SERVICE_ORDER_ID)       AS SERVICE_ORDER_ID,
  TRY_TO_NUMBER(NULLIF(LINE_NO,'')) AS LINE_NO,
  TRIM(FAULT_CODE_ID)          AS FAULT_CODE_ID,
  TRIM(REPLACED_MATERIAL_ID)   AS REPLACED_MATERIAL_ID,
  IFF(UPPER(NVL(IS_MANUFACTURING_DEFECT_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N')
                                AS IS_MANUFACTURING_DEFECT_FLAG,
  IFF(UPPER(NVL(WARRANTY_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N') AS WARRANTY_FLAG,
  NVL(TRY_TO_NUMBER(NULLIF(REPAIR_HOURS,'')),0) AS REPAIR_HOURS,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_SERVICE_ORDER_LINE;

CREATE OR REPLACE VIEW STG.VW_ERP_WARRANTY_CLAIM AS
SELECT
  TRIM(CLAIM_ID)               AS CLAIM_ID,
  TRIM(CLAIM_NO)               AS CLAIM_NO,
  TO_DATE(TRY_TO_TIMESTAMP(CLAIM_DATE)) AS CLAIM_DATE,
  TRIM(SERVICE_ORDER_ID)       AS SERVICE_ORDER_ID,
  TRIM(VEHICLE_ID)             AS VEHICLE_ID,
  TRIM(DEALER_ID)              AS DEALER_ID,
  TRIM(FAULT_CODE_ID)          AS FAULT_CODE_ID,
  NVL(TRY_TO_NUMBER(NULLIF(CLAIM_AMOUNT,'')),0)    AS CLAIM_AMOUNT,
  NVL(TRY_TO_NUMBER(NULLIF(APPROVED_AMOUNT,'')),0) AS APPROVED_AMOUNT,
  TRIM(CLAIM_STATUS)           AS CLAIM_STATUS,
  TRIM(REJECTION_REASON)       AS REJECTION_REASON,
  IFF(UPPER(NVL(MANUFACTURING_DEFECT_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N')
                                AS MANUFACTURING_DEFECT_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_WARRANTY_CLAIM;

CREATE OR REPLACE VIEW STG.VW_ERP_CUSTOMER_FEEDBACK AS
SELECT
  TRIM(FEEDBACK_ID)            AS FEEDBACK_ID,
  TO_DATE(TRY_TO_TIMESTAMP(FEEDBACK_DATE)) AS FEEDBACK_DATE,
  TRIM(CUSTOMER_ID)            AS CUSTOMER_ID,
  TRIM(VEHICLE_ID)             AS VEHICLE_ID,
  TRIM(DEALER_ID)              AS DEALER_ID,
  NVL(TRY_TO_NUMBER(NULLIF(OVERALL_SATISFACTION_SCORE,'')),0)
                                AS OVERALL_SATISFACTION_SCORE,
  NVL(TRY_TO_NUMBER(NULLIF(RECOMMEND_SCORE,'')),0) AS RECOMMEND_SCORE,
  TRIM(FEATURE_REQUEST_CATEGORY) AS FEATURE_REQUEST_CATEGORY,
  TRIM(FEATURE_REQUEST_TEXT)   AS FEATURE_REQUEST_TEXT,
  IFF(UPPER(NVL(COMPLAINT_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N') AS COMPLAINT_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_CUSTOMER_FEEDBACK;


---

-- 6. Forecast & Backlog STG views


CREATE OR REPLACE VIEW STG.VW_ERP_DEMAND_FORECAST AS
SELECT
  TRIM(FORECAST_RUN_ID)        AS FORECAST_RUN_ID,
  TRIM(FORECAST_SOURCE)        AS FORECAST_SOURCE,
  TO_DATE(TRY_TO_TIMESTAMP(FORECAST_DATE)) AS FORECAST_DATE,
  TRIM(DEALER_ID)              AS DEALER_ID,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  NVL(TRY_TO_NUMBER(NULLIF(FORECAST_DEMAND_UNITS,'')),0) AS FORECAST_DEMAND_UNITS,
  TO_DATE(TRY_TO_TIMESTAMP(FORECAST_GENERATED_DATE)) AS FORECAST_GENERATED_DATE,
  IFF(UPPER(NVL(SEASONAL_PEAK_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N') AS SEASONAL_PEAK_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_DEMAND_FORECAST;

CREATE OR REPLACE VIEW STG.VW_ERP_BACKLOG_SNAPSHOT AS
SELECT
  TRIM(BACKLOG_RUN_ID)         AS BACKLOG_RUN_ID,
  TO_DATE(TRY_TO_TIMESTAMP(AS_OF_DATE)) AS AS_OF_DATE,
  TRIM(PLANT_ID)               AS PLANT_ID,
  TRIM(VARIANT_ID)             AS VARIANT_ID,
  NVL(TRY_TO_NUMBER(NULLIF(TOTAL_OPEN_BOOKINGS_UNITS,'')),0)          AS TOTAL_OPEN_BOOKINGS_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(NEAR_TERM_FORECAST_30D_UNITS,'')),0)       AS NEAR_TERM_FORECAST_30D_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(PLANT_FINISHED_STOCK_UNITS,'')),0)         AS PLANT_FINISHED_STOCK_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(DEALER_STOCK_UNITS,'')),0)                 AS DEALER_STOCK_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(IN_TRANSIT_VEHICLE_UNITS,'')),0)           AS IN_TRANSIT_VEHICLE_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(AVAILABLE_VEHICLE_SUPPLY_UNITS,'')),0)     AS AVAILABLE_VEHICLE_SUPPLY_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(PLANNED_PRODUCTION_30D_UNITS,'')),0)       AS PLANNED_PRODUCTION_30D_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(EXPECTED_VENDOR_SUPPLY_30D_UOM,'')),0)     AS EXPECTED_VENDOR_SUPPLY_30D_UOM,
  NVL(TRY_TO_NUMBER(NULLIF(BACKLOG_UNITS,'')),0)                      AS BACKLOG_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(EXPECTED_AVG_DELAY_DAYS,'')),0)            AS EXPECTED_AVG_DELAY_DAYS,
  NVL(TRY_TO_NUMBER(NULLIF(RECOMMENDED_EXTRA_PRODUCTION_UNITS,'')),0) AS RECOMMENDED_EXTRA_PRODUCTION_UNITS,
  NVL(TRY_TO_NUMBER(NULLIF(RECOMMENDED_EXTRA_PROCUREMENT_UOM,'')),0)  AS RECOMMENDED_EXTRA_PROCUREMENT_UOM,
  IFF(UPPER(NVL(SEASONAL_PEAK_FLAG,'N')) IN ('Y','1','TRUE'),'Y','N')  AS SEASONAL_PEAK_FLAG,
  DW_CREATED_TS,
  CURRENT_TIMESTAMP()          AS DW_LAST_UPDATED_TS,
  DW_BATCH_ID,
  DW_SOURCE_FILE_NAME
FROM RAW.ERP_BACKLOG_SNAPSHOT;
--------------------------------------------------------
-- Counts for STG views
SELECT 'STG.VW_ERP_PLANT'                    AS view_name, COUNT(*) AS row_count FROM MARUTI_AUTO_DWH.STG.VW_ERP_PLANT
UNION ALL SELECT 'STG.VW_ERP_VENDOR',                 COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_VENDOR
UNION ALL SELECT 'STG.VW_ERP_MATERIAL',               COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_MATERIAL
UNION ALL SELECT 'STG.VW_ERP_BRAND',                  COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_BRAND
UNION ALL SELECT 'STG.VW_ERP_MODEL',                  COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_MODEL
UNION ALL SELECT 'STG.VW_ERP_VARIANT',                COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_VARIANT
UNION ALL SELECT 'STG.VW_ERP_DEALER',                 COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_DEALER
UNION ALL SELECT 'STG.VW_ERP_SHOWROOM',               COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_SHOWROOM
UNION ALL SELECT 'STG.VW_ERP_SERVICE_CENTER',         COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_SERVICE_CENTER
