UNION ALL SELECT 'STG.VW_ERP_PURCHASE_CONTRACT',      COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_PURCHASE_CONTRACT
UNION ALL SELECT 'STG.VW_ERP_PURCHASE_CONTRACT_LINE', COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_PURCHASE_CONTRACT_LINE
UNION ALL SELECT 'STG.VW_ERP_PO_HEADER',              COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_PO_HEADER
UNION ALL SELECT 'STG.VW_ERP_PO_LINE',                COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_PO_LINE
UNION ALL SELECT 'STG.VW_ERP_GRN',                    COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_GRN
UNION ALL SELECT 'STG.VW_ERP_PRODUCTION_DAILY',       COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_PRODUCTION_DAILY
UNION ALL SELECT 'STG.VW_ERP_PLANT_INVENTORY_SNAP',   COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_PLANT_INVENTORY_SNAP
UNION ALL SELECT 'STG.VW_ERP_VEHICLE_DISPATCH',       COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_VEHICLE_DISPATCH
UNION ALL SELECT 'STG.VW_ERP_DEALER_STOCK_SNAP',      COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_DEALER_STOCK_SNAP
UNION ALL SELECT 'STG.VW_ERP_BOOKING',                COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_BOOKING
UNION ALL SELECT 'STG.VW_ERP_SALES_INVOICE_HDR',      COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_SALES_INVOICE_HDR
UNION ALL SELECT 'STG.VW_ERP_SALES_INVOICE_LINE',     COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_SALES_INVOICE_LINE
UNION ALL SELECT 'STG.VW_ERP_DEMAND_FORECAST',        COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_DEMAND_FORECAST
UNION ALL SELECT 'STG.VW_ERP_BACKLOG_SNAPSHOT',       COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_BACKLOG_SNAPSHOT
UNION ALL SELECT 'STG.VW_ERP_SERVICE_ORDER_HDR',      COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_SERVICE_ORDER_HDR
UNION ALL SELECT 'STG.VW_ERP_SERVICE_ORDER_LINE',     COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_SERVICE_ORDER_LINE
UNION ALL SELECT 'STG.VW_ERP_WARRANTY_CLAIM',         COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_WARRANTY_CLAIM
UNION ALL SELECT 'STG.VW_ERP_CUSTOMER_FEEDBACK',      COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_CUSTOMER_FEEDBACK
