ORDER BY view_name;

---------------------------------------------------------
USE DATABASE MARUTI_AUTO_DWH;
CREATE SCHEMA IF NOT EXISTS INT;
USE SCHEMA INT;

-------------------------------------------------------------------------------
-- DIMENSION TABLES
-------------------------------------------------------------------------------

-- 1. DIM_DATE
CREATE OR REPLACE TABLE DIM_DATE (
    DATE_KEY               NUMBER(8,0)      NOT NULL,
    CALENDAR_DATE          DATE             NOT NULL,
    DAY_NAME               VARCHAR(20),
    DAY_OF_WEEK            NUMBER(2,0),
    WEEK_OF_YEAR           NUMBER(2,0),
    MONTH                  NUMBER(2,0),
    MONTH_NAME             VARCHAR(20),
    QUARTER                NUMBER(1,0),
    YEAR                   NUMBER(4,0),
    IS_MONTH_END           BOOLEAN,
    IS_HOLIDAY_FLAG        BOOLEAN,
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_DATE PRIMARY KEY (DATE_KEY)
);

-- 2. DIM_GEOGRAPHY
CREATE OR REPLACE TABLE DIM_GEOGRAPHY (
    GEO_KEY                NUMBER(38,0)     NOT NULL,
    COUNTRY                VARCHAR(100),
    STATE                  VARCHAR(100),
    DISTRICT               VARCHAR(100),
    CITY                   VARCHAR(100),
    PIN_CODE               VARCHAR(20),
    REGION                 VARCHAR(50),
    URBAN_RURAL_FLAG       VARCHAR(10),
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_GEOGRAPHY PRIMARY KEY (GEO_KEY)
);

-- 3. DIM_BRAND_MODEL_VARIANT
CREATE OR REPLACE TABLE DIM_BRAND_MODEL_VARIANT (
    BMV_KEY                NUMBER(38,0)     NOT NULL,
    BRAND_CODE             VARCHAR(50),
    BRAND_NAME             VARCHAR(100),
    MODEL_CODE             VARCHAR(50),
    MODEL_NAME             VARCHAR(100),
    VARIANT_CODE           VARCHAR(50),
    VARIANT_NAME           VARCHAR(150),
    FUEL_TYPE              VARCHAR(50),
    TRANSMISSION_TYPE      VARCHAR(50),
    ENGINE_CC              NUMBER(6,0),
    BODY_TYPE              VARCHAR(50),
    LAUNCH_DATE_KEY        NUMBER(8,0),
    DISCONTINUED_FLAG      BOOLEAN,
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_BMV PRIMARY KEY (BMV_KEY)
);

-- 4. DIM_PLANT
CREATE OR REPLACE TABLE DIM_PLANT (
    PLANT_KEY              NUMBER(38,0)     NOT NULL,
    PLANT_CODE             VARCHAR(50),
    PLANT_NAME             VARCHAR(150),
    PLANT_TYPE             VARCHAR(50),
    GEO_KEY                NUMBER(38,0),
    START_DATE_KEY         NUMBER(8,0),
    END_DATE_KEY           NUMBER(8,0),
    ACTIVE_FLAG            BOOLEAN,
    DEFAULT_SHIFT_PATTERN  NUMBER(3,0),
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_PLANT PRIMARY KEY (PLANT_KEY)
);

-- 5. DIM_VENDOR
CREATE OR REPLACE TABLE DIM_VENDOR (
    VENDOR_KEY                 NUMBER(38,0) NOT NULL,
    VENDOR_CODE                VARCHAR(50),
    VENDOR_NAME                VARCHAR(200),
    VENDOR_TYPE                VARCHAR(50),
    GEO_KEY                    NUMBER(38,0),
    CONTACT_PERSON             VARCHAR(150),
    CONTACT_EMAIL              VARCHAR(150),
    CONTACT_PHONE              VARCHAR(50),
    DEFAULT_CURRENCY           VARCHAR(10),
    PREFERRED_FLAG             BOOLEAN,
    AVG_HIST_LEAD_TIME_DAYS    NUMBER(5,2),
    LEAD_TIME_VARIABILITY_DAYS NUMBER(5,2),
    -- AUDIT
    DW_CREATED_TS              TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS         TIMESTAMP_LTZ,
    DW_BATCH_ID                VARCHAR(50),
    DW_SOURCE_FILE_NAME        VARCHAR(500),
    CONSTRAINT PK_DIM_VENDOR PRIMARY KEY (VENDOR_KEY)
);

-- 6. DIM_RAW_MATERIAL
CREATE OR REPLACE TABLE DIM_RAW_MATERIAL (
    MATERIAL_KEY           NUMBER(38,0)     NOT NULL,
    MATERIAL_CODE          VARCHAR(50),
    MATERIAL_NAME          VARCHAR(200),
    MATERIAL_CATEGORY      VARCHAR(100),
    UOM                    VARCHAR(20),
    CRITICALITY_LEVEL      VARCHAR(20),
    USED_IN_BOM_FLAG       BOOLEAN,
    HAZARDOUS_FLAG         BOOLEAN,
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_RAW_MATERIAL PRIMARY KEY (MATERIAL_KEY)
);

-- 7. DIM_SUPPLY_CONTRACT
CREATE OR REPLACE TABLE DIM_SUPPLY_CONTRACT (
    CONTRACT_KEY               NUMBER(38,0) NOT NULL,
    VENDOR_KEY                 NUMBER(38,0),
    MATERIAL_KEY               NUMBER(38,0),
    PLANT_KEY                  NUMBER(38,0),
    CONTRACT_NO                VARCHAR(100),
    VALID_FROM_DATE_KEY        NUMBER(8,0),
    VALID_TO_DATE_KEY          NUMBER(8,0),
    STANDARD_LEAD_TIME_DAYS    NUMBER(5,2),
    LEAD_TIME_BUFFER_DAYS      NUMBER(5,2),
    MIN_ORDER_QTY              NUMBER(18,3),
    PRICE_PER_UOM              NUMBER(18,4),
    PENALTY_LATE_DELIVERY_FLAG BOOLEAN,
    -- AUDIT
    DW_CREATED_TS              TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS         TIMESTAMP_LTZ,
    DW_BATCH_ID                VARCHAR(50),
    DW_SOURCE_FILE_NAME        VARCHAR(500),
    CONSTRAINT PK_DIM_SUPPLY_CONTRACT PRIMARY KEY (CONTRACT_KEY)
);

-- 8. DIM_DEALER
CREATE OR REPLACE TABLE DIM_DEALER (
    DEALER_KEY             NUMBER(38,0)     NOT NULL,
    DEALER_CODE            VARCHAR(50),
    DEALER_GROUP_NAME      VARCHAR(200),
    SHOWROOM_NAME          VARCHAR(200),
    SHOWROOM_TYPE          VARCHAR(50),
    CHANNEL                VARCHAR(50),
    GEO_KEY                NUMBER(38,0),
    OPENING_DATE_KEY       NUMBER(8,0),
    CLOSING_DATE_KEY       NUMBER(8,0),
    ACTIVE_FLAG            BOOLEAN,
    HAS_SERVICE_CENTER_FLAG BOOLEAN,
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_DEALER PRIMARY KEY (DEALER_KEY)
);

-- 9. DIM_SERVICE_CENTER
CREATE OR REPLACE TABLE DIM_SERVICE_CENTER (
    SERVICE_CENTER_KEY     NUMBER(38,0)     NOT NULL,
    DEALER_KEY             NUMBER(38,0),
    SERVICE_CENTER_CODE    VARCHAR(50),
    SERVICE_CENTER_NAME    VARCHAR(200),
    GEO_KEY                NUMBER(38,0),
    OPENING_DATE_KEY       NUMBER(8,0),
    ACTIVE_FLAG            BOOLEAN,
    IS_AUTHORIZED_FLAG     BOOLEAN,
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_SERVICE_CENTER PRIMARY KEY (SERVICE_CENTER_KEY)
);

-- 10. DIM_CUSTOMER
CREATE OR REPLACE TABLE DIM_CUSTOMER (
    CUSTOMER_KEY           NUMBER(38,0)     NOT NULL,
    CUSTOMER_ID            VARCHAR(100),
    CUSTOMER_NAME          VARCHAR(200),
    GENDER                 VARCHAR(20),
    DOB                    DATE,
    GEO_KEY                NUMBER(38,0),
    MOBILE_NUMBER          VARCHAR(50),
    EMAIL_ID               VARCHAR(150),
    CUSTOMER_SEGMENT       VARCHAR(50),
    LOYALTY_TIER           VARCHAR(50),
    FIRST_PURCHASE_DATE_KEY NUMBER(8,0),
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_CUSTOMER PRIMARY KEY (CUSTOMER_KEY)
);

-- 11. DIM_SALESPERSON
CREATE OR REPLACE TABLE DIM_SALESPERSON (
    SALESPERSON_KEY        NUMBER(38,0)     NOT NULL,
    SALESPERSON_ID         VARCHAR(50),
    FULL_NAME              VARCHAR(200),
    DEALER_KEY             NUMBER(38,0),
    DESIGNATION            VARCHAR(100),
    JOIN_DATE_KEY          NUMBER(8,0),
    EXIT_DATE_KEY          NUMBER(8,0),
    ACTIVE_FLAG            BOOLEAN,
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_SALESPERSON PRIMARY KEY (SALESPERSON_KEY)
);

-- 12. DIM_VEHICLE
CREATE OR REPLACE TABLE DIM_VEHICLE (
    VEHICLE_KEY            NUMBER(38,0)     NOT NULL,
    VIN                    VARCHAR(50),
    BMV_KEY                NUMBER(38,0),
    PLANT_KEY              NUMBER(38,0),
    PRODUCTION_DATE_KEY    NUMBER(8,0),
    PRODUCTION_BATCH_NO    VARCHAR(100),
    ENGINE_NO              VARCHAR(100),
    CHASSIS_NO             VARCHAR(100),
    WARRANTY_START_DATE_KEY NUMBER(8,0),
    WARRANTY_DURATION_MONTHS NUMBER(4,0),
    -- AUDIT
    DW_CREATED_TS          TIMESTAMP_LTZ,
    DW_LAST_UPDATED_TS     TIMESTAMP_LTZ,
    DW_BATCH_ID            VARCHAR(50),
    DW_SOURCE_FILE_NAME    VARCHAR(500),
    CONSTRAINT PK_DIM_VEHICLE PRIMARY KEY (VEHICLE_KEY)
);

-- 13. DIM_SERVICE_JOB_TYPE
CREATE OR REPLACE TABLE DIM_SERVICE_JOB_TYPE (
    SERVICE_JOB_TYPE_KEY   NUMBER(38,0)     NOT NULL,
    JOB_TYPE_CODE          VARCHAR(50),
