-- Counts for STG streams (view-wrappers over streams)
SELECT 'STG.VW_ERP_PLANT_STREAM'                    AS stream_name, COUNT(*) AS row_count FROM MARUTI_AUTO_DWH.STG.VW_ERP_PLANT_STREAM
UNION ALL SELECT 'STG.VW_ERP_VENDOR_STREAM',                 COUNT(*) FROM MARUTI_AUTO_DWH.STG.VW_ERP_VENDOR_STREAM
