USE DATABASE MARUTI_AUTO_DWH;
USE SCHEMA INT;

/* -------------------------------------------------------------------------------
   2.1 DIM_DATE  (JS version with params)
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE INT.SP_LOAD_DIM_DATE_JS(start_date DATE, end_date DATE)
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS CALLER
AS
$$
const vStart = (new Date(START_DATE)).toISOString().slice(0,10); // 'YYYY-MM-DD'
const vEnd   = (new Date(END_DATE)).toISOString().slice(0,10);
if (vEnd < vStart) return 'No rows: end_date before start_date';

const sql = `
MERGE INTO INT.DIM_DATE t
USING (
  WITH RECURSIVE d AS (
    SELECT TO_DATE('${vStart}') AS d
    UNION ALL
    SELECT DATEADD('day', 1, d) FROM d WHERE d < TO_DATE('${vEnd}')
  )
  SELECT
    TO_NUMBER(TO_CHAR(d,'YYYYMMDD')) AS DATE_KEY,
    d AS CALENDAR_DATE,
    TO_CHAR(d,'DY') AS DAY_NAME,
    EXTRACT(DAYOFWEEK FROM d) AS DAY_OF_WEEK,
    EXTRACT(WEEK FROM d) AS WEEK_OF_YEAR,
    EXTRACT(MONTH FROM d) AS MONTH,
    TO_CHAR(d,'MON') AS MONTH_NAME,
    EXTRACT(QUARTER FROM d) AS QUARTER,
    EXTRACT(YEAR FROM d) AS YEAR,
    IFF(LAST_DAY(d)=d, TRUE, FALSE) AS IS_MONTH_END,
    FALSE AS IS_HOLIDAY_FLAG,
    CURRENT_TIMESTAMP() AS DW_CREATED_TS,
    CURRENT_TIMESTAMP() AS DW_LAST_UPDATED_TS,
    'SP_LOAD_DIM_DATE_JS' AS DW_BATCH_ID,
    'generated' AS DW_SOURCE_FILE_NAME
  FROM d
) s
ON t.DATE_KEY = s.DATE_KEY
WHEN MATCHED THEN UPDATE SET
  CALENDAR_DATE = s.CALENDAR_DATE,
  DAY_NAME = s.DAY_NAME,
  DAY_OF_WEEK = s.DAY_OF_WEEK,
  WEEK_OF_YEAR = s.WEEK_OF_YEAR,
  MONTH = s.MONTH,
  MONTH_NAME = s.MONTH_NAME,
  QUARTER = s.QUARTER,
  YEAR = s.YEAR,
  IS_MONTH_END = s.IS_MONTH_END,
  DW_LAST_UPDATED_TS = CURRENT_TIMESTAMP(),
  DW_BATCH_ID = 'SP_LOAD_DIM_DATE_JS'
WHEN NOT MATCHED THEN INSERT (
  DATE_KEY, CALENDAR_DATE, DAY_NAME, DAY_OF_WEEK, WEEK_OF_YEAR,
  MONTH, MONTH_NAME, QUARTER, YEAR, IS_MONTH_END, IS_HOLIDAY_FLAG,
  DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
) VALUES (
  s.DATE_KEY, s.CALENDAR_DATE, s.DAY_NAME, s.DAY_OF_WEEK, s.WEEK_OF_YEAR,
  s.MONTH, s.MONTH_NAME, s.QUARTER, s.YEAR, s.IS_MONTH_END, s.IS_HOLIDAY_FLAG,
  s.DW_CREATED_TS, s.DW_LAST_UPDATED_TS, s.DW_BATCH_ID, s.DW_SOURCE_FILE_NAME
)`;

snowflake.execute({sqlText: sql});
return `DIM_DATE upserted for range ${vStart} .. ${vEnd}`;
$$;

CALL INT.SP_LOAD_DIM_DATE_JS('2020-01-01'::DATE, '2026-12-31'::DATE);
SELECT COUNT(*) FROM INT.DIM_DATE;

/* -------------------------------------------------------------------------------
   2.2 DIM_GEOGRAPHY
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_GEOGRAPHY()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_GEOGRAPHY tgt
  USING (
    SELECT DISTINCT
      UPPER(NVL(STATE,'UNKNOWN'))    AS STATE,
      UPPER(NVL(DISTRICT,'UNKNOWN')) AS DISTRICT,
      UPPER(NVL(CITY,'UNKNOWN'))     AS CITY,
      NVL(PIN_CODE,'UNKNOWN')        AS PIN_CODE,
      UPPER(NVL(COUNTRY,'INDIA'))    AS COUNTRY,
      UPPER(NVL(REGION,'UNKNOWN'))   AS REGION,
      'URBAN'                        AS URBAN_RURAL_FLAG
    FROM STG.VW_ERP_DEALER
    UNION
    SELECT DISTINCT
      UPPER(NVL(STATE,'UNKNOWN'))    AS STATE,
      UPPER(NVL(DISTRICT,'UNKNOWN')) AS DISTRICT,
      UPPER(NVL(CITY,'UNKNOWN'))     AS CITY,
      NVL(PIN_CODE,'UNKNOWN')        AS PIN_CODE,
      UPPER(NVL(COUNTRY,'INDIA'))    AS COUNTRY,
      UPPER(NVL(REGION,'UNKNOWN'))   AS REGION,
      'URBAN'                        AS URBAN_RURAL_FLAG
    FROM STG.VW_ERP_PLANT
  ) src
  ON  NVL(tgt.STATE,'X')    = src.STATE
  AND NVL(tgt.DISTRICT,'X') = src.DISTRICT
  AND NVL(tgt.CITY,'X')     = src.CITY
  AND NVL(tgt.PIN_CODE,'X') = src.PIN_CODE
  AND NVL(tgt.COUNTRY,'X')  = src.COUNTRY
  WHEN MATCHED THEN UPDATE SET
    tgt.REGION             = src.REGION,
    tgt.URBAN_RURAL_FLAG   = src.URBAN_RURAL_FLAG,
    tgt.DW_LAST_UPDATED_TS = CURRENT_TIMESTAMP()
  WHEN NOT MATCHED THEN INSERT (
    GEO_KEY, COUNTRY, STATE, DISTRICT, CITY, PIN_CODE, REGION,
    URBAN_RURAL_FLAG, DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.COUNTRY || '|' || src.STATE || '|' || src.DISTRICT
                || '|' || src.CITY || '|' || src.PIN_CODE), 1000000000)),
    src.COUNTRY, src.STATE, src.DISTRICT, src.CITY, src.PIN_CODE, src.REGION,
    src.URBAN_RURAL_FLAG,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), 'DIM_GEO_AUTO','MULTI_SRC'
  )
`});
return 'DIM_GEOGRAPHY loaded';
$$;

CALL INT.SP_LOAD_DIM_GEOGRAPHY();
SELECT COUNT(*) FROM INT.DIM_GEOGRAPHY;

/* -------------------------------------------------------------------------------
   2.3 DIM_VENDOR   (calls GEO)
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_VENDOR()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `CALL INT.SP_LOAD_DIM_GEOGRAPHY()`});
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_VENDOR tgt
  USING (
    SELECT
      v.VENDOR_ID,
      v.VENDOR_CODE,
      v.VENDOR_NAME,
      v.VENDOR_TYPE,
      g.GEO_KEY,
      v.CONTACT_PERSON,
      v.CONTACT_EMAIL,
      v.CONTACT_PHONE,
      v.DEFAULT_CURRENCY,
      v.PREFERRED_FLAG,
      v.AVG_HIST_LEAD_TIME_DAYS,
      v.LEAD_TIME_VARIABILITY_DAYS,
      v.DW_BATCH_ID,
      v.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_VENDOR_STREAM s
    JOIN STG.VW_ERP_VENDOR v
      ON s.VENDOR_ID = v.VENDOR_ID
    LEFT JOIN INT.DIM_GEOGRAPHY g
      ON UPPER(NVL(g.STATE,'X'))    = UPPER(NVL(v.STATE,'X'))
     AND UPPER(NVL(g.DISTRICT,'X')) = UPPER(NVL(v.DISTRICT,'X'))
     AND UPPER(NVL(g.CITY,'X'))     = UPPER(NVL(v.CITY,'X'))
     AND NVL(g.PIN_CODE,'X')        = NVL(v.PIN_CODE,'X')
     AND UPPER(NVL(g.COUNTRY,'X'))  = UPPER(NVL(v.COUNTRY,'X'))
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.VENDOR_CODE = src.VENDOR_CODE
  WHEN MATCHED THEN UPDATE SET
    tgt.VENDOR_NAME                 = src.VENDOR_NAME,
    tgt.VENDOR_TYPE                 = src.VENDOR_TYPE,
    tgt.GEO_KEY                     = src.GEO_KEY,
    tgt.CONTACT_PERSON              = src.CONTACT_PERSON,
    tgt.CONTACT_EMAIL               = src.CONTACT_EMAIL,
    tgt.CONTACT_PHONE               = src.CONTACT_PHONE,
    tgt.DEFAULT_CURRENCY            = src.DEFAULT_CURRENCY,
    tgt.PREFERRED_FLAG              = IFF(src.PREFERRED_FLAG='Y',TRUE,FALSE),
    tgt.AVG_HIST_LEAD_TIME_DAYS     = src.AVG_HIST_LEAD_TIME_DAYS,
    tgt.LEAD_TIME_VARIABILITY_DAYS  = src.LEAD_TIME_VARIABILITY_DAYS,
    tgt.DW_LAST_UPDATED_TS          = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID                 = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME         = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    VENDOR_KEY, VENDOR_CODE, VENDOR_NAME, VENDOR_TYPE, GEO_KEY,
    CONTACT_PERSON, CONTACT_EMAIL, CONTACT_PHONE, DEFAULT_CURRENCY,
    PREFERRED_FLAG, AVG_HIST_LEAD_TIME_DAYS, LEAD_TIME_VARIABILITY_DAYS,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.VENDOR_CODE), 1000000000)),
    src.VENDOR_CODE, src.VENDOR_NAME, src.VENDOR_TYPE, src.GEO_KEY,
    src.CONTACT_PERSON, src.CONTACT_EMAIL, src.CONTACT_PHONE, src.DEFAULT_CURRENCY,
    IFF(src.PREFERRED_FLAG='Y',TRUE,FALSE),
    src.AVG_HIST_LEAD_TIME_DAYS, src.LEAD_TIME_VARIABILITY_DAYS,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_VENDOR loaded from STG view-stream';
$$;
CALL INT.SP_LOAD_DIM_VENDOR(); 
SELECT COUNT(*) FROM INT.DIM_VENDOR;

/* -------------------------------------------------------------------------------
   2.4 DIM_RAW_MATERIAL
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_RAW_MATERIAL()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_RAW_MATERIAL tgt
  USING (
    SELECT
      m.MATERIAL_ID,
      m.MATERIAL_CODE,
      m.MATERIAL_NAME,
      m.MATERIAL_CATEGORY,
      m.BASE_UOM     AS UOM,
      m.CRITICALITY_LEVEL,
      IFF(m.USED_IN_BOM_FLAG='Y',TRUE,FALSE) AS USED_IN_BOM_FLAG,
      IFF(m.HAZARDOUS_FLAG='Y',TRUE,FALSE)   AS HAZARDOUS_FLAG,
      m.DW_BATCH_ID,
      m.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_MATERIAL_STREAM s
    JOIN STG.VW_ERP_MATERIAL m
      ON s.MATERIAL_ID = m.MATERIAL_ID
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.MATERIAL_CODE = src.MATERIAL_CODE
  WHEN MATCHED THEN UPDATE SET
    tgt.MATERIAL_NAME       = src.MATERIAL_NAME,
    tgt.MATERIAL_CATEGORY   = src.MATERIAL_CATEGORY,
    tgt.UOM                 = src.UOM,
    tgt.CRITICALITY_LEVEL   = src.CRITICALITY_LEVEL,
    tgt.USED_IN_BOM_FLAG    = src.USED_IN_BOM_FLAG,
    tgt.HAZARDOUS_FLAG      = src.HAZARDOUS_FLAG,
    tgt.DW_LAST_UPDATED_TS  = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID         = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    MATERIAL_KEY, MATERIAL_CODE, MATERIAL_NAME, MATERIAL_CATEGORY,
    UOM, CRITICALITY_LEVEL, USED_IN_BOM_FLAG, HAZARDOUS_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.MATERIAL_CODE), 1000000000)),
    src.MATERIAL_CODE, src.MATERIAL_NAME, src.MATERIAL_CATEGORY,
    src.UOM, src.CRITICALITY_LEVEL, src.USED_IN_BOM_FLAG, src.HAZARDOUS_FLAG,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_RAW_MATERIAL loaded';
$$;

CALL INT.SP_LOAD_DIM_RAW_MATERIAL();
SELECT COUNT(*) FROM INT.DIM_RAW_MATERIAL;

/* -------------------------------------------------------------------------------
   2.5 DIM_BRAND_MODEL_VARIANT
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_BRAND_MODEL_VARIANT()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_BRAND_MODEL_VARIANT tgt
  USING (
    SELECT
      v.VARIANT_ID,
      b.BRAND_CODE,
      b.BRAND_NAME,
      m.MODEL_CODE,
      m.MODEL_NAME,
      v.VARIANT_CODE,
      v.VARIANT_NAME,
      v.FUEL_TYPE,
      v.TRANSMISSION_TYPE,
      v.ENGINE_CC,
      m.BODY_TYPE,
      IFF(m.LAUNCH_DATE IS NULL, NULL,
          TO_NUMBER(TO_CHAR(m.LAUNCH_DATE,'YYYYMMDD'))) AS LAUNCH_DATE_KEY,
      IFF( (v.ACTIVE_FLAG <> 'Y') OR (m.DISCONTINUED_DATE IS NOT NULL), TRUE, FALSE)
          AS DISCONTINUED_FLAG,
      v.DW_BATCH_ID,
      v.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_VARIANT_STREAM s
    JOIN STG.VW_ERP_VARIANT v
      ON s.VARIANT_ID = v.VARIANT_ID
    JOIN STG.VW_ERP_MODEL  m
      ON v.MODEL_ID   = m.MODEL_ID
    JOIN STG.VW_ERP_BRAND  b
      ON m.BRAND_ID   = b.BRAND_ID
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.VARIANT_CODE = src.VARIANT_CODE
  WHEN MATCHED THEN UPDATE SET
    tgt.BRAND_CODE          = src.BRAND_CODE,
    tgt.BRAND_NAME          = src.BRAND_NAME,
    tgt.MODEL_CODE          = src.MODEL_CODE,
    tgt.MODEL_NAME          = src.MODEL_NAME,
    tgt.VARIANT_NAME        = src.VARIANT_NAME,
    tgt.FUEL_TYPE           = src.FUEL_TYPE,
    tgt.TRANSMISSION_TYPE   = src.TRANSMISSION_TYPE,
    tgt.ENGINE_CC           = src.ENGINE_CC,
    tgt.BODY_TYPE           = src.BODY_TYPE,
    tgt.LAUNCH_DATE_KEY     = src.LAUNCH_DATE_KEY,
    tgt.DISCONTINUED_FLAG   = src.DISCONTINUED_FLAG,
    tgt.DW_LAST_UPDATED_TS  = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID         = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    BMV_KEY, BRAND_CODE, BRAND_NAME, MODEL_CODE, MODEL_NAME, VARIANT_CODE,
    VARIANT_NAME, FUEL_TYPE, TRANSMISSION_TYPE, ENGINE_CC, BODY_TYPE,
    LAUNCH_DATE_KEY, DISCONTINUED_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.VARIANT_CODE), 1000000000)),
    src.BRAND_CODE, src.BRAND_NAME, src.MODEL_CODE, src.MODEL_NAME,
    src.VARIANT_CODE, src.VARIANT_NAME, src.FUEL_TYPE, src.TRANSMISSION_TYPE,
    src.ENGINE_CC, src.BODY_TYPE, src.LAUNCH_DATE_KEY, src.DISCONTINUED_FLAG,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_BRAND_MODEL_VARIANT loaded';
$$;

CALL INT.SP_LOAD_DIM_BRAND_MODEL_VARIANT();
SELECT COUNT(*) FROM INT.DIM_BRAND_MODEL_VARIANT;

/* -------------------------------------------------------------------------------
   2.6 DIM_PLANT   (calls GEO)
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_PLANT()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `CALL INT.SP_LOAD_DIM_GEOGRAPHY()`});
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_PLANT tgt
  USING (
    SELECT
      p.PLANT_ID,
      p.PLANT_CODE,
      p.PLANT_NAME,
      p.PLANT_TYPE,
      g.GEO_KEY,
      d_start.DATE_KEY AS START_DATE_KEY,
      d_end.DATE_KEY   AS END_DATE_KEY,
      IFF(p.ACTIVE_FLAG='Y',TRUE,FALSE) AS ACTIVE_FLAG,
      p.DEFAULT_SHIFT_PATTERN,
      p.DW_BATCH_ID,
      p.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_PLANT_STREAM s
    JOIN STG.VW_ERP_PLANT p
      ON s.PLANT_ID = p.PLANT_ID
    LEFT JOIN INT.DIM_GEOGRAPHY g
      ON UPPER(NVL(g.STATE,'X'))    = UPPER(NVL(p.STATE,'X'))
     AND UPPER(NVL(g.DISTRICT,'X')) = UPPER(NVL(p.DISTRICT,'X'))
     AND UPPER(NVL(g.CITY,'X'))     = UPPER(NVL(p.CITY,'X'))
     AND NVL(g.PIN_CODE,'X')        = NVL(p.PIN_CODE,'X')
     AND UPPER(NVL(g.COUNTRY,'X'))  = UPPER(NVL(p.COUNTRY,'X'))
    LEFT JOIN INT.DIM_DATE d_start
      ON d_start.CALENDAR_DATE = p.START_DATE
    LEFT JOIN INT.DIM_DATE d_end
      ON d_end.CALENDAR_DATE   = p.END_DATE
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.PLANT_CODE = src.PLANT_CODE
  WHEN MATCHED THEN UPDATE SET
    tgt.PLANT_NAME          = src.PLANT_NAME,
    tgt.PLANT_TYPE          = src.PLANT_TYPE,
    tgt.GEO_KEY             = src.GEO_KEY,
    tgt.START_DATE_KEY      = src.START_DATE_KEY,
    tgt.END_DATE_KEY        = src.END_DATE_KEY,
    tgt.ACTIVE_FLAG         = src.ACTIVE_FLAG,
    tgt.DEFAULT_SHIFT_PATTERN = src.DEFAULT_SHIFT_PATTERN,
    tgt.DW_LAST_UPDATED_TS  = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID         = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    PLANT_KEY, PLANT_CODE, PLANT_NAME, PLANT_TYPE,
    GEO_KEY, START_DATE_KEY, END_DATE_KEY,
    ACTIVE_FLAG, DEFAULT_SHIFT_PATTERN,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.PLANT_CODE), 1000000000)),
    src.PLANT_CODE, src.PLANT_NAME, src.PLANT_TYPE,
    src.GEO_KEY, src.START_DATE_KEY, src.END_DATE_KEY,
    src.ACTIVE_FLAG, src.DEFAULT_SHIFT_PATTERN,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_PLANT loaded';
$$;

CALL INT.SP_LOAD_DIM_PLANT();
SELECT COUNT(*) FROM INT.DIM_PLANT;

/* -------------------------------------------------------------------------------
   2.7 DIM_DEALER   (calls GEO)
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_DEALER()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `CALL INT.SP_LOAD_DIM_GEOGRAPHY()`});
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_DEALER tgt
  USING (
    SELECT
      d.DEALER_ID,
      d.DEALER_CODE,
      d.DEALER_GROUP_NAME,
      MIN(s.SHOWROOM_NAME)       AS SHOWROOM_NAME,
      MIN(s.SHOWROOM_TYPE)       AS SHOWROOM_TYPE,
      d.CHANNEL,
      g.GEO_KEY,
      d_open.DATE_KEY            AS OPENING_DATE_KEY,
      d_close.DATE_KEY           AS CLOSING_DATE_KEY,
      IFF(d.ACTIVE_FLAG='Y',TRUE,FALSE) AS ACTIVE_FLAG,
      IFF(MAX(IFF(s.HAS_SERVICE_CENTER_FLAG='Y',1,0))>0, TRUE, FALSE)
                                    AS HAS_SERVICE_CENTER_FLAG,
      d.DW_BATCH_ID,
      d.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_DEALER_STREAM st
    JOIN STG.VW_ERP_DEALER d
      ON st.DEALER_ID = d.DEALER_ID
    LEFT JOIN STG.VW_ERP_SHOWROOM s
      ON s.DEALER_ID = d.DEALER_ID
    LEFT JOIN INT.DIM_GEOGRAPHY g
      ON UPPER(NVL(g.STATE,'X'))    = UPPER(NVL(d.STATE,'X'))
     AND UPPER(NVL(g.DISTRICT,'X')) = UPPER(NVL(d.DISTRICT,'X'))
     AND UPPER(NVL(g.CITY,'X'))     = UPPER(NVL(d.CITY,'X'))
     AND NVL(g.PIN_CODE,'X')        = NVL(d.PIN_CODE,'X')
     AND UPPER(NVL(g.COUNTRY,'X'))  = UPPER(NVL(d.COUNTRY,'X'))
    LEFT JOIN INT.DIM_DATE d_open
      ON d_open.CALENDAR_DATE = d.OPENING_DATE
    LEFT JOIN INT.DIM_DATE d_close
      ON d_close.CALENDAR_DATE = d.CLOSING_DATE
    WHERE st.METADATA$ACTION IN ('INSERT','UPDATE')
    GROUP BY
      d.DEALER_ID, d.DEALER_CODE, d.DEALER_GROUP_NAME,
      d.CHANNEL, g.GEO_KEY,
      d_open.DATE_KEY, d_close.DATE_KEY,
      d.ACTIVE_FLAG, d.DW_BATCH_ID, d.DW_SOURCE_FILE_NAME
  ) src
  ON tgt.DEALER_CODE = src.DEALER_CODE
  WHEN MATCHED THEN UPDATE SET
    tgt.DEALER_GROUP_NAME     = src.DEALER_GROUP_NAME,
    tgt.SHOWROOM_NAME         = src.SHOWROOM_NAME,
    tgt.SHOWROOM_TYPE         = src.SHOWROOM_TYPE,
    tgt.CHANNEL               = src.CHANNEL,
    tgt.GEO_KEY               = src.GEO_KEY,
    tgt.OPENING_DATE_KEY      = src.OPENING_DATE_KEY,
    tgt.CLOSING_DATE_KEY      = src.CLOSING_DATE_KEY,
    tgt.ACTIVE_FLAG           = src.ACTIVE_FLAG,
    tgt.HAS_SERVICE_CENTER_FLAG = src.HAS_SERVICE_CENTER_FLAG,
    tgt.DW_LAST_UPDATED_TS    = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID           = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME   = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    DEALER_KEY, DEALER_CODE, DEALER_GROUP_NAME, SHOWROOM_NAME, SHOWROOM_TYPE,
    CHANNEL, GEO_KEY, OPENING_DATE_KEY, CLOSING_DATE_KEY,
    ACTIVE_FLAG, HAS_SERVICE_CENTER_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.DEALER_CODE), 1000000000)),
    src.DEALER_CODE, src.DEALER_GROUP_NAME, src.SHOWROOM_NAME, src.SHOWROOM_TYPE,
    src.CHANNEL, src.GEO_KEY, src.OPENING_DATE_KEY, src.CLOSING_DATE_KEY,
    src.ACTIVE_FLAG, src.HAS_SERVICE_CENTER_FLAG,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_DEALER loaded';
$$;

CALL INT.SP_LOAD_DIM_DEALER();
SELECT COUNT(*) FROM INT.DIM_DEALER;

/* -------------------------------------------------------------------------------
   2.8 DIM_SERVICE_CENTER
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_SERVICE_CENTER()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_SERVICE_CENTER tgt
  USING (
    SELECT
      sc.SERVICE_CENTER_ID,
      sc.SERVICE_CENTER_CODE,
      sc.SERVICE_CENTER_NAME,
      dd.DEALER_KEY,
      g.GEO_KEY,
      d_open.DATE_KEY      AS OPENING_DATE_KEY,
      IFF(sc.ACTIVE_FLAG='Y',TRUE,FALSE) AS ACTIVE_FLAG,
      IFF(sc.IS_AUTHORIZED_FLAG='Y',TRUE,FALSE) AS IS_AUTHORIZED_FLAG,
      sc.DW_BATCH_ID,
      sc.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_SERVICE_CENTER_STREAM s
    JOIN STG.VW_ERP_SERVICE_CENTER sc
      ON s.SERVICE_CENTER_ID = sc.SERVICE_CENTER_ID
    LEFT JOIN STG.VW_ERP_DEALER d_raw
      ON d_raw.DEALER_ID = sc.DEALER_ID
    LEFT JOIN INT.DIM_DEALER dd
      ON dd.DEALER_CODE = d_raw.DEALER_CODE
    LEFT JOIN INT.DIM_GEOGRAPHY g
      ON UPPER(NVL(g.STATE,'X'))    = UPPER(NVL(sc.STATE,'X'))
     AND UPPER(NVL(g.DISTRICT,'X')) = UPPER(NVL(sc.DISTRICT,'X'))
     AND UPPER(NVL(g.CITY,'X'))     = UPPER(NVL(sc.CITY,'X'))
     AND NVL(g.PIN_CODE,'X')        = NVL(sc.PIN_CODE,'X')
     AND UPPER(NVL(g.COUNTRY,'X'))  = UPPER(NVL(sc.COUNTRY,'X'))
    LEFT JOIN INT.DIM_DATE d_open
      ON d_open.CALENDAR_DATE = sc.OPENING_DATE
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.SERVICE_CENTER_CODE = src.SERVICE_CENTER_CODE
  WHEN MATCHED THEN UPDATE SET
    tgt.SERVICE_CENTER_NAME   = src.SERVICE_CENTER_NAME,
    tgt.DEALER_KEY            = src.DEALER_KEY,
    tgt.GEO_KEY               = src.GEO_KEY,
    tgt.OPENING_DATE_KEY      = src.OPENING_DATE_KEY,
    tgt.ACTIVE_FLAG           = src.ACTIVE_FLAG,
    tgt.IS_AUTHORIZED_FLAG    = src.IS_AUTHORIZED_FLAG,
    tgt.DW_LAST_UPDATED_TS    = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID           = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME   = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    SERVICE_CENTER_KEY, DEALER_KEY, SERVICE_CENTER_CODE, SERVICE_CENTER_NAME,
    GEO_KEY, OPENING_DATE_KEY, ACTIVE_FLAG, IS_AUTHORIZED_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.SERVICE_CENTER_CODE), 1000000000)),
    src.DEALER_KEY, src.SERVICE_CENTER_CODE, src.SERVICE_CENTER_NAME,
    src.GEO_KEY, src.OPENING_DATE_KEY, src.ACTIVE_FLAG, src.IS_AUTHORIZED_FLAG,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_SERVICE_CENTER loaded';
$$;

CALL INT.SP_LOAD_DIM_SERVICE_CENTER();
SELECT COUNT(*) FROM INT.DIM_SERVICE_CENTER;

/* -------------------------------------------------------------------------------
   2.9 DIM_CUSTOMER  (calls GEO)
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_CUSTOMER()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `CALL INT.SP_LOAD_DIM_GEOGRAPHY()`});
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_CUSTOMER tgt
  USING (
    SELECT
      c.CUSTOMER_ID,
      c.CUSTOMER_NAME,
      c.GENDER,
      c.DOB,
      g.GEO_KEY,
      c.MOBILE_NUMBER,
      c.EMAIL_ID,
      c.CUSTOMER_SEGMENT,
      c.LOYALTY_TIER,
      d_fp.DATE_KEY AS FIRST_PURCHASE_DATE_KEY,
      c.DW_BATCH_ID,
      c.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_CUSTOMER_STREAM s
    JOIN STG.VW_ERP_CUSTOMER c
      ON s.CUSTOMER_ID = c.CUSTOMER_ID
    LEFT JOIN INT.DIM_GEOGRAPHY g
      ON UPPER(NVL(g.STATE,'X'))    = UPPER(NVL(c.STATE,'X'))
     AND UPPER(NVL(g.DISTRICT,'X')) = UPPER(NVL(c.DISTRICT,'X'))
     AND UPPER(NVL(g.CITY,'X'))     = UPPER(NVL(c.CITY,'X'))
     AND NVL(g.PIN_CODE,'X')        = NVL(c.PIN_CODE,'X')
     AND UPPER(NVL(g.COUNTRY,'X'))  = UPPER(NVL(c.COUNTRY,'X'))
    LEFT JOIN INT.DIM_DATE d_fp
      ON d_fp.CALENDAR_DATE = c.FIRST_PURCHASE_DATE
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.CUSTOMER_ID = src.CUSTOMER_ID
  WHEN MATCHED THEN UPDATE SET
    tgt.CUSTOMER_NAME         = src.CUSTOMER_NAME,
    tgt.GENDER                = src.GENDER,
    tgt.DOB                   = src.DOB,
    tgt.GEO_KEY               = src.GEO_KEY,
    tgt.MOBILE_NUMBER         = src.MOBILE_NUMBER,
    tgt.EMAIL_ID              = src.EMAIL_ID,
    tgt.CUSTOMER_SEGMENT      = src.CUSTOMER_SEGMENT,
    tgt.LOYALTY_TIER          = src.LOYALTY_TIER,
    tgt.FIRST_PURCHASE_DATE_KEY = src.FIRST_PURCHASE_DATE_KEY,
    tgt.DW_LAST_UPDATED_TS    = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID           = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME   = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    CUSTOMER_KEY, CUSTOMER_ID, CUSTOMER_NAME, GENDER, DOB, GEO_KEY,
    MOBILE_NUMBER, EMAIL_ID, CUSTOMER_SEGMENT, LOYALTY_TIER,
    FIRST_PURCHASE_DATE_KEY,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.CUSTOMER_ID), 1000000000)),
    src.CUSTOMER_ID, src.CUSTOMER_NAME, src.GENDER, src.DOB, src.GEO_KEY,
    src.MOBILE_NUMBER, src.EMAIL_ID, src.CUSTOMER_SEGMENT, src.LOYALTY_TIER,
    src.FIRST_PURCHASE_DATE_KEY,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_CUSTOMER loaded';
$$;

CALL INT.SP_LOAD_DIM_CUSTOMER();

SELECT COUNT(*) FROM INT.DIM_CUSTOMER;

/* -------------------------------------------------------------------------------
   2.10 DIM_SALESPERSON
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_SALESPERSON()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_SALESPERSON tgt
  USING (
    SELECT
      sp.SALESPERSON_ID,
      sp.FULL_NAME,
      dd.DEALER_KEY,
      sp.DESIGNATION,
      d_join.DATE_KEY AS JOIN_DATE_KEY,
      d_exit.DATE_KEY AS EXIT_DATE_KEY,
      IFF(sp.ACTIVE_FLAG='Y',TRUE,FALSE) AS ACTIVE_FLAG,
      sp.DW_BATCH_ID,
      sp.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_SALESPERSON_STREAM s
    JOIN STG.VW_ERP_SALESPERSON sp
      ON s.SALESPERSON_ID = sp.SALESPERSON_ID
    LEFT JOIN STG.VW_ERP_DEALER d_raw
      ON d_raw.DEALER_ID = sp.DEALER_ID
    LEFT JOIN INT.DIM_DEALER dd
      ON dd.DEALER_CODE = d_raw.DEALER_CODE
    LEFT JOIN INT.DIM_DATE d_join
      ON d_join.CALENDAR_DATE = sp.JOIN_DATE
    LEFT JOIN INT.DIM_DATE d_exit
      ON d_exit.CALENDAR_DATE = sp.EXIT_DATE
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.SALESPERSON_ID = src.SALESPERSON_ID
  WHEN MATCHED THEN UPDATE SET
    tgt.FULL_NAME           = src.FULL_NAME,
    tgt.DEALER_KEY          = src.DEALER_KEY,
    tgt.DESIGNATION         = src.DESIGNATION,
    tgt.JOIN_DATE_KEY       = src.JOIN_DATE_KEY,
    tgt.EXIT_DATE_KEY       = src.EXIT_DATE_KEY,
    tgt.ACTIVE_FLAG         = src.ACTIVE_FLAG,
    tgt.DW_LAST_UPDATED_TS  = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID         = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    SALESPERSON_KEY, SALESPERSON_ID, FULL_NAME, DEALER_KEY, DESIGNATION,
    JOIN_DATE_KEY, EXIT_DATE_KEY, ACTIVE_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.SALESPERSON_ID), 1000000000)),
    src.SALESPERSON_ID, src.FULL_NAME, src.DEALER_KEY, src.DESIGNATION,
    src.JOIN_DATE_KEY, src.EXIT_DATE_KEY, src.ACTIVE_FLAG,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_SALESPERSON loaded';
$$;

CALL INT.SP_LOAD_DIM_SALESPERSON();

SELECT COUNT(*) FROM INT.DIM_SALESPERSON;

/* -------------------------------------------------------------------------------
   2.11 DIM_VEHICLE
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_VEHICLE()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_VEHICLE tgt
  USING (
    SELECT
      vp.VEHICLE_ID,
      vp.VIN,
      bmv.BMV_KEY,
      dp.PLANT_KEY,
      d_prod.DATE_KEY    AS PRODUCTION_DATE_KEY,
      vp.PRODUCTION_BATCH_NO,
      vp.ENGINE_NO,
      vp.CHASSIS_NO,
      d_warr.DATE_KEY    AS WARRANTY_START_DATE_KEY,
      vp.WARRANTY_DURATION_MONTHS,
      vp.DW_BATCH_ID,
      vp.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_VEHICLE_PRODUCTION_STREAM s
    JOIN STG.VW_ERP_VEHICLE_PRODUCTION vp
      ON s.VEHICLE_ID = vp.VEHICLE_ID
    LEFT JOIN STG.VW_ERP_VARIANT var_raw
      ON var_raw.VARIANT_ID = vp.VARIANT_ID
    LEFT JOIN STG.VW_ERP_PLANT p_raw
      ON p_raw.PLANT_ID = vp.PLANT_ID
    LEFT JOIN INT.DIM_BRAND_MODEL_VARIANT bmv
      ON bmv.VARIANT_CODE = var_raw.VARIANT_CODE
    LEFT JOIN INT.DIM_PLANT dp
      ON dp.PLANT_CODE = p_raw.PLANT_CODE
    LEFT JOIN INT.DIM_DATE d_prod
      ON d_prod.CALENDAR_DATE = vp.PRODUCTION_DATE
    LEFT JOIN INT.DIM_DATE d_warr
      ON d_warr.CALENDAR_DATE = vp.WARRANTY_START_DATE
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.VIN = src.VIN
  WHEN MATCHED THEN UPDATE SET
    tgt.BMV_KEY                 = src.BMV_KEY,
    tgt.PLANT_KEY               = src.PLANT_KEY,
    tgt.PRODUCTION_DATE_KEY     = src.PRODUCTION_DATE_KEY,
    tgt.PRODUCTION_BATCH_NO     = src.PRODUCTION_BATCH_NO,
    tgt.ENGINE_NO               = src.ENGINE_NO,
    tgt.CHASSIS_NO              = src.CHASSIS_NO,
    tgt.WARRANTY_START_DATE_KEY = src.WARRANTY_START_DATE_KEY,
    tgt.WARRANTY_DURATION_MONTHS = src.WARRANTY_DURATION_MONTHS,
    tgt.DW_LAST_UPDATED_TS      = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID             = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME     = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    VEHICLE_KEY, VIN, BMV_KEY, PLANT_KEY, PRODUCTION_DATE_KEY,
    PRODUCTION_BATCH_NO, ENGINE_NO, CHASSIS_NO,
    WARRANTY_START_DATE_KEY, WARRANTY_DURATION_MONTHS,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.VIN), 1000000000)),
    src.VIN, src.BMV_KEY, src.PLANT_KEY, src.PRODUCTION_DATE_KEY,
    src.PRODUCTION_BATCH_NO, src.ENGINE_NO, src.CHASSIS_NO,
    src.WARRANTY_START_DATE_KEY, src.WARRANTY_DURATION_MONTHS,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_VEHICLE loaded';
$$;

CALL INT.SP_LOAD_DIM_VEHICLE(); 

SELECT COUNT(*) FROM INT.DIM_VEHICLE;

/* -------------------------------------------------------------------------------
   2.12 DIM_SUPPLY_CONTRACT
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_SUPPLY_CONTRACT()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_SUPPLY_CONTRACT tgt
  USING (
    SELECT
      cl.CONTRACT_LINE_ID,
      pc.CONTRACT_NO,
      dv.VENDOR_KEY,
      dm.MATERIAL_KEY,
      dp.PLANT_KEY,
      d_from.DATE_KEY AS VALID_FROM_DATE_KEY,
      d_to.DATE_KEY   AS VALID_TO_DATE_KEY,
      pc.STANDARD_LEAD_TIME_DAYS,
      pc.LEAD_TIME_BUFFER_DAYS,
      cl.MIN_ORDER_QTY,
      cl.PRICE_PER_UOM,
      IFF(cl.PENALTY_LATE_DELIVERY_FLAG='Y',TRUE,FALSE) AS PENALTY_LATE_DELIVERY_FLAG,
      pc.DW_BATCH_ID,
      pc.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_PURCHASE_CONTRACT_LINE_STREAM s
    JOIN STG.VW_ERP_PURCHASE_CONTRACT_LINE cl
      ON s.CONTRACT_LINE_ID = cl.CONTRACT_LINE_ID
    JOIN STG.VW_ERP_PURCHASE_CONTRACT pc
      ON pc.CONTRACT_ID = cl.CONTRACT_ID
    LEFT JOIN STG.VW_ERP_VENDOR v_raw
      ON v_raw.VENDOR_ID = pc.VENDOR_ID
    LEFT JOIN STG.VW_ERP_PLANT p_raw
      ON p_raw.PLANT_ID = pc.PLANT_ID
    LEFT JOIN STG.VW_ERP_MATERIAL m_raw
      ON m_raw.MATERIAL_ID = cl.MATERIAL_ID
    LEFT JOIN INT.DIM_VENDOR dv
      ON dv.VENDOR_CODE = v_raw.VENDOR_CODE
    LEFT JOIN INT.DIM_PLANT dp
      ON dp.PLANT_CODE = p_raw.PLANT_CODE
    LEFT JOIN INT.DIM_RAW_MATERIAL dm
      ON dm.MATERIAL_CODE = m_raw.MATERIAL_CODE
    LEFT JOIN INT.DIM_DATE d_from
      ON d_from.CALENDAR_DATE = pc.VALID_FROM_DATE
    LEFT JOIN INT.DIM_DATE d_to
      ON d_to.CALENDAR_DATE   = pc.VALID_TO_DATE
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.CONTRACT_NO = src.CONTRACT_NO
 AND tgt.MATERIAL_KEY = src.MATERIAL_KEY
 AND tgt.PLANT_KEY    = src.PLANT_KEY
  WHEN MATCHED THEN UPDATE SET
    tgt.VENDOR_KEY                 = src.VENDOR_KEY,
    tgt.VALID_FROM_DATE_KEY        = src.VALID_FROM_DATE_KEY,
    tgt.VALID_TO_DATE_KEY          = src.VALID_TO_DATE_KEY,
    tgt.STANDARD_LEAD_TIME_DAYS    = src.STANDARD_LEAD_TIME_DAYS,
    tgt.LEAD_TIME_BUFFER_DAYS      = src.LEAD_TIME_BUFFER_DAYS,
    tgt.MIN_ORDER_QTY              = src.MIN_ORDER_QTY,
    tgt.PRICE_PER_UOM              = src.PRICE_PER_UOM,
    tgt.PENALTY_LATE_DELIVERY_FLAG = src.PENALTY_LATE_DELIVERY_FLAG,
    tgt.DW_LAST_UPDATED_TS         = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID                = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME        = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    CONTRACT_KEY, VENDOR_KEY, MATERIAL_KEY, PLANT_KEY,
    CONTRACT_NO, VALID_FROM_DATE_KEY, VALID_TO_DATE_KEY,
    STANDARD_LEAD_TIME_DAYS, LEAD_TIME_BUFFER_DAYS,
    MIN_ORDER_QTY, PRICE_PER_UOM, PENALTY_LATE_DELIVERY_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.CONTRACT_NO || '|' || src.MATERIAL_KEY || '|' || src.PLANT_KEY), 1000000000)),
    src.VENDOR_KEY, src.MATERIAL_KEY, src.PLANT_KEY,
    src.CONTRACT_NO, src.VALID_FROM_DATE_KEY, src.VALID_TO_DATE_KEY,
    src.STANDARD_LEAD_TIME_DAYS, src.LEAD_TIME_BUFFER_DAYS,
    src.MIN_ORDER_QTY, src.PRICE_PER_UOM, src.PENALTY_LATE_DELIVERY_FLAG,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_SUPPLY_CONTRACT loaded';
$$;

CALL INT.SP_LOAD_DIM_SUPPLY_CONTRACT();

SELECT COUNT(*) FROM INT.DIM_SUPPLY_CONTRACT;

/* -------------------------------------------------------------------------------
   2.13 DIM_SERVICE_JOB_TYPE
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE INT.SP_LOAD_DIM_SERVICE_JOB_TYPE()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({
  sqlText: `
    MERGE INTO INT.DIM_SERVICE_JOB_TYPE tgt
    USING (
      SELECT
        j.SERVICE_JOB_TYPE_ID,
        j.JOB_TYPE_CODE,
        j.JOB_TYPE_NAME,
        j.JOB_CATEGORY,
        IFF(j.IS_WARRANTY_ELIGIBLE_FLAG='Y', TRUE, FALSE) AS IS_WARRANTY_ELIGIBLE_FLAG,
        j.DW_BATCH_ID,
        j.DW_SOURCE_FILE_NAME
      FROM STG.VW_ERP_SERVICE_JOB_TYPE_STREAM s
      JOIN STG.VW_ERP_SERVICE_JOB_TYPE j
        ON s.SERVICE_JOB_TYPE_ID = j.SERVICE_JOB_TYPE_ID
      WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
    ) src
    ON tgt.JOB_TYPE_CODE = src.JOB_TYPE_CODE
    WHEN MATCHED THEN UPDATE SET
      tgt.JOB_TYPE_NAME             = src.JOB_TYPE_NAME,
      tgt.JOB_CATEGORY              = src.JOB_CATEGORY,
      tgt.IS_WARRANTY_ELIGIBLE_FLAG = src.IS_WARRANTY_ELIGIBLE_FLAG,
      tgt.DW_LAST_UPDATED_TS        = CURRENT_TIMESTAMP(),
      tgt.DW_BATCH_ID               = src.DW_BATCH_ID,
      tgt.DW_SOURCE_FILE_NAME       = src.DW_SOURCE_FILE_NAME
    WHEN NOT MATCHED THEN INSERT (
      SERVICE_JOB_TYPE_KEY, JOB_TYPE_CODE, JOB_TYPE_NAME, JOB_CATEGORY,
      IS_WARRANTY_ELIGIBLE_FLAG,
      DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
    ) VALUES (
      ABS(MOD(HASH(src.JOB_TYPE_CODE), 1000000000)),
      src.JOB_TYPE_CODE, src.JOB_TYPE_NAME, src.JOB_CATEGORY,
      src.IS_WARRANTY_ELIGIBLE_FLAG,
      CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
    )
  `
});
return 'DIM_SERVICE_JOB_TYPE loaded';
$$;

CALL INT.SP_LOAD_DIM_SERVICE_JOB_TYPE();
SELECT COUNT(*) FROM INT.DIM_SERVICE_JOB_TYPE;

/* -------------------------------------------------------------------------------
   2.14 DIM_FAULT_CODE
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_DIM_FAULT_CODE()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.DIM_FAULT_CODE tgt
  USING (
    SELECT
      f.FAULT_CODE_ID,
      f.FAULT_CODE,
      f.FAULT_DESCRIPTION,
      f.SEVERITY_LEVEL,
      f.SYSTEM_AREA,
      IFF(f.IS_MANUFACTURING_DEFECT_FLAG='Y',TRUE,FALSE)
          AS IS_MANUFACTURING_DEFECT_FLAG,
      f.DW_BATCH_ID,
      f.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_FAULT_CODE_STREAM s
    JOIN STG.VW_ERP_FAULT_CODE f
      ON s.FAULT_CODE_ID = f.FAULT_CODE_ID
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON tgt.FAULT_CODE = src.FAULT_CODE
  WHEN MATCHED THEN UPDATE SET
    tgt.FAULT_DESCRIPTION         = src.FAULT_DESCRIPTION,
    tgt.SEVERITY_LEVEL            = src.SEVERITY_LEVEL,
    tgt.SYSTEM_AREA               = src.SYSTEM_AREA,
    tgt.IS_MANUFACTURING_DEFECT_FLAG = src.IS_MANUFACTURING_DEFECT_FLAG,
    tgt.DW_LAST_UPDATED_TS        = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID               = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME       = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    FAULT_CODE_KEY, FAULT_CODE, FAULT_DESCRIPTION, SEVERITY_LEVEL,
    SYSTEM_AREA, IS_MANUFACTURING_DEFECT_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    ABS(MOD(HASH(src.FAULT_CODE), 1000000000)),
    src.FAULT_CODE, src.FAULT_DESCRIPTION, src.SEVERITY_LEVEL,
    src.SYSTEM_AREA, src.IS_MANUFACTURING_DEFECT_FLAG,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'DIM_FAULT_CODE loaded';
$$;

CALL INT.SP_LOAD_DIM_FAULT_CODE();

SELECT COUNT(*) FROM INT.DIM_FAULT_CODE;

