/* -------------------------------------------------------------------------------
   3.1 FCT_PRODUCTION_DAILY
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_PRODUCTION_DAILY()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  INSERT INTO INT.FCT_PRODUCTION_DAILY (
    DATE_KEY, PLANT_KEY, BMV_KEY, SHIFT,
    UNITS_PRODUCED, UNITS_REJECTED, UNITS_REWORKED,
    TOTAL_PRODUCTION_HRS, OEE_PERCENT,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  )
  SELECT
    d_prod.DATE_KEY,
    dp.PLANT_KEY,
    bmv.BMV_KEY,
    pd.SHIFT_CODE            AS SHIFT,
    pd.UNITS_PRODUCED,
    pd.UNITS_REJECTED,
    pd.UNITS_REWORKED,
    pd.TOTAL_PRODUCTION_HRS,
    pd.OEE_PERCENT,
    CURRENT_TIMESTAMP(),
    CURRENT_TIMESTAMP(),
    pd.DW_BATCH_ID,
    pd.DW_SOURCE_FILE_NAME
  FROM STG.VW_ERP_PRODUCTION_DAILY_STREAM s
  JOIN STG.VW_ERP_PRODUCTION_DAILY pd
    ON s.PROD_RECORD_ID = pd.PROD_RECORD_ID
  LEFT JOIN STG.VW_ERP_PLANT p_raw
    ON p_raw.PLANT_ID = pd.PLANT_ID
  LEFT JOIN STG.VW_ERP_VARIANT var_raw
    ON var_raw.VARIANT_ID = pd.VARIANT_ID
  LEFT JOIN INT.DIM_PLANT dp
    ON dp.PLANT_CODE = p_raw.PLANT_CODE
  LEFT JOIN INT.DIM_BRAND_MODEL_VARIANT bmv
    ON bmv.VARIANT_CODE = var_raw.VARIANT_CODE
  LEFT JOIN INT.DIM_DATE d_prod
    ON d_prod.CALENDAR_DATE = pd.PROD_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_PRODUCTION_DAILY loaded';
$$;

CALL INT.SP_LOAD_FCT_PRODUCTION_DAILY();
