  FROM STG.VW_ERP_PLANT_INVENTORY_SNAP_STREAM s
  JOIN STG.VW_ERP_PLANT_INVENTORY_SNAP snap
    ON s.SNAPSHOT_ID = snap.SNAPSHOT_ID
  LEFT JOIN STG.VW_ERP_PLANT p_raw
    ON p_raw.PLANT_ID = snap.PLANT_ID
  LEFT JOIN STG.VW_ERP_VARIANT var_raw
    ON var_raw.VARIANT_ID = snap.VARIANT_ID
  LEFT JOIN INT.DIM_PLANT dp
    ON dp.PLANT_CODE = p_raw.PLANT_CODE
  LEFT JOIN INT.DIM_BRAND_MODEL_VARIANT bmv
    ON bmv.VARIANT_CODE = var_raw.VARIANT_CODE
  LEFT JOIN INT.DIM_DATE d_snap
    ON d_snap.CALENDAR_DATE = snap.SNAPSHOT_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_PLANT_INVENTORY_SNAPSHOT loaded';
