/* -------------------------------------------------------------------------------
   3.3 FCT_VEHICLE_DISPATCH
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_VEHICLE_DISPATCH()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  INSERT INTO INT.FCT_VEHICLE_DISPATCH (
    DISPATCH_DATE_KEY, PLANT_KEY, DEALER_KEY, BMV_KEY,
    DISPATCH_DOC_NO, DISPATCH_QTY, FREIGHT_COST,
    EXPECTED_ARRIVAL_DATE_KEY, ACTUAL_ARRIVAL_DATE_KEY,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  )
  SELECT
    d_disp.DATE_KEY  AS DISPATCH_DATE_KEY,
    dp.PLANT_KEY,
    dd.DEALER_KEY,
    bmv.BMV_KEY,
    vd.DISPATCH_DOC_NO,
    vd.DISPATCH_QTY,
    vd.FREIGHT_COST,
    d_exp.DATE_KEY   AS EXPECTED_ARRIVAL_DATE_KEY,
    d_act.DATE_KEY   AS ACTUAL_ARRIVAL_DATE_KEY,
    CURRENT_TIMESTAMP(),
    CURRENT_TIMESTAMP(),
    vd.DW_BATCH_ID,
    vd.DW_SOURCE_FILE_NAME
  FROM STG.VW_ERP_VEHICLE_DISPATCH_STREAM s
  JOIN STG.VW_ERP_VEHICLE_DISPATCH vd
    ON s.DISPATCH_ID = vd.DISPATCH_ID
  LEFT JOIN STG.VW_ERP_PLANT p_raw
    ON p_raw.PLANT_ID = vd.PLANT_ID
  LEFT JOIN STG.VW_ERP_DEALER d_raw
    ON d_raw.DEALER_ID = vd.DEALER_ID
  LEFT JOIN STG.VW_ERP_VARIANT var_raw
    ON var_raw.VARIANT_ID = vd.VARIANT_ID
  LEFT JOIN INT.DIM_PLANT dp
    ON dp.PLANT_CODE = p_raw.PLANT_CODE
  LEFT JOIN INT.DIM_DEALER dd
    ON dd.DEALER_CODE = d_raw.DEALER_CODE
  LEFT JOIN INT.DIM_BRAND_MODEL_VARIANT bmv
    ON bmv.VARIANT_CODE = var_raw.VARIANT_CODE
  LEFT JOIN INT.DIM_DATE d_disp
    ON d_disp.CALENDAR_DATE = vd.DISPATCH_DATE
  LEFT JOIN INT.DIM_DATE d_exp
    ON d_exp.CALENDAR_DATE = vd.EXPECTED_ARRIVAL_DATE
  LEFT JOIN INT.DIM_DATE d_act
    ON d_act.CALENDAR_DATE = vd.ACTUAL_ARRIVAL_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_VEHICLE_DISPATCH loaded';
$$;

CALL INT.SP_LOAD_FCT_VEHICLE_DISPATCH();
SELECT * FROM INT.FCT_VEHICLE_DISPATCH;

