/* -------------------------------------------------------------------------------
   3.5 FCT_BOOKING
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_BOOKING()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  INSERT INTO INT.FCT_BOOKING (
    BOOKING_ID, BOOKING_DATE_KEY, DEALER_KEY, BMV_KEY,
    CUSTOMER_KEY, SALESPERSON_KEY,
    BOOKING_AMOUNT, BOOKING_STATUS,
    EXPECTED_DELIVERY_DATE_KEY, CANCEL_REASON,
    PREDICTED_CONVERSION_PROB,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  )
  SELECT
    b.BOOKING_ID,
    d_book.DATE_KEY AS BOOKING_DATE_KEY,
    dd.DEALER_KEY,
    bmv.BMV_KEY,
    dc.CUSTOMER_KEY,
    ds.SALESPERSON_KEY,
    b.BOOKING_AMOUNT,
    b.BOOKING_STATUS,
    d_exp.DATE_KEY  AS EXPECTED_DELIVERY_DATE_KEY,
    b.CANCEL_REASON,
    b.PREDICTED_CONVERSION_PROB,
    CURRENT_TIMESTAMP(),
    CURRENT_TIMESTAMP(),
    b.DW_BATCH_ID,
    b.DW_SOURCE_FILE_NAME
  FROM STG.VW_ERP_BOOKING_STREAM s
  JOIN STG.VW_ERP_BOOKING b
    ON s.BOOKING_ID = b.BOOKING_ID
  LEFT JOIN STG.VW_ERP_DEALER d_raw
    ON d_raw.DEALER_ID = b.DEALER_ID
  LEFT JOIN STG.VW_ERP_CUSTOMER c_raw
    ON c_raw.CUSTOMER_ID = b.CUSTOMER_ID
  LEFT JOIN STG.VW_ERP_SALESPERSON sp_raw
    ON sp_raw.SALESPERSON_ID = b.SALESPERSON_ID
  LEFT JOIN STG.VW_ERP_VARIANT var_raw
    ON var_raw.VARIANT_ID = b.VARIANT_ID
  LEFT JOIN INT.DIM_DEALER dd
    ON dd.DEALER_CODE = d_raw.DEALER_CODE
  LEFT JOIN INT.DIM_CUSTOMER dc
    ON dc.CUSTOMER_ID = c_raw.CUSTOMER_ID
  LEFT JOIN INT.DIM_SALESPERSON ds
    ON ds.SALESPERSON_ID = sp_raw.SALESPERSON_ID
  LEFT JOIN INT.DIM_BRAND_MODEL_VARIANT bmv
    ON bmv.VARIANT_CODE = var_raw.VARIANT_CODE
  LEFT JOIN INT.DIM_DATE d_book
    ON d_book.CALENDAR_DATE = b.BOOKING_DATE
  LEFT JOIN INT.DIM_DATE d_exp
    ON d_exp.CALENDAR_DATE = b.EXPECTED_DELIVERY_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_BOOKING loaded';
$$;

CALL INT.SP_LOAD_FCT_BOOKING();
SELECT * FROM INT.FCT_BOOKING;

/* -------------------------------------------------------------------------------
   3.6 FCT_RETAIL_SALES
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_RETAIL_SALES()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  INSERT INTO INT.FCT_RETAIL_SALES (
    INVOICE_NO, INVOICE_DATE_KEY, DELIVERY_DATE_KEY,
    DEALER_KEY, BMV_KEY, CUSTOMER_KEY, SALESPERSON_KEY, VEHICLE_KEY,
    EXSHOWROOM_PRICE, DISCOUNT_AMOUNT, ONROAD_PRICE,
    PAYMENT_MODE, DOWN_PAYMENT_AMOUNT, LOAN_AMOUNT,
    PAYMENT_STATUS, BOOKING_ID,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  )
  SELECT
    h.INVOICE_NO,
    d_inv.DATE_KEY AS INVOICE_DATE_KEY,
    d_del.DATE_KEY AS DELIVERY_DATE_KEY,
    dd.DEALER_KEY,
    bmv.BMV_KEY,
    dc.CUSTOMER_KEY,
    ds.SALESPERSON_KEY,
    dvh.VEHICLE_KEY,
    l.EXSHOWROOM_PRICE,
    l.DISCOUNT_AMOUNT,
    COALESCE(
      l.ONROAD_PRICE,
      l.EXSHOWROOM_PRICE - l.DISCOUNT_AMOUNT
      + NVL(h.DOWN_PAYMENT_AMOUNT,0) + NVL(h.LOAN_AMOUNT,0)
    ) AS ONROAD_PRICE,
    h.PAYMENT_MODE,
    h.DOWN_PAYMENT_AMOUNT,
    h.LOAN_AMOUNT,
    h.PAYMENT_STATUS,
    h.BOOKING_ID,
    CURRENT_TIMESTAMP(),
    CURRENT_TIMESTAMP(),
    h.DW_BATCH_ID,
    h.DW_SOURCE_FILE_NAME
  FROM STG.VW_ERP_SALES_INVOICE_HDR_STREAM s
  JOIN STG.VW_ERP_SALES_INVOICE_HDR h
    ON s.INVOICE_ID = h.INVOICE_ID
  JOIN STG.VW_ERP_SALES_INVOICE_LINE l
    ON l.INVOICE_ID = h.INVOICE_ID
  LEFT JOIN STG.VW_ERP_DEALER d_raw
    ON d_raw.DEALER_ID = h.DEALER_ID
  LEFT JOIN STG.VW_ERP_CUSTOMER c_raw
    ON c_raw.CUSTOMER_ID = h.CUSTOMER_ID
  LEFT JOIN STG.VW_ERP_SALESPERSON sp_raw
    ON sp_raw.SALESPERSON_ID = h.SALESPERSON_ID
  LEFT JOIN STG.VW_ERP_VEHICLE_PRODUCTION vp_raw
    ON vp_raw.VEHICLE_ID = l.VEHICLE_ID
  LEFT JOIN STG.VW_ERP_VARIANT var_raw
    ON var_raw.VARIANT_ID = l.VARIANT_ID
  LEFT JOIN INT.DIM_DEALER dd
    ON dd.DEALER_CODE = d_raw.DEALER_CODE
  LEFT JOIN INT.DIM_CUSTOMER dc
    ON dc.CUSTOMER_ID = c_raw.CUSTOMER_ID
  LEFT JOIN INT.DIM_SALESPERSON ds
    ON ds.SALESPERSON_ID = sp_raw.SALESPERSON_ID
  LEFT JOIN INT.DIM_VEHICLE dvh
    ON dvh.VIN = vp_raw.VIN
  LEFT JOIN INT.DIM_BRAND_MODEL_VARIANT bmv
    ON bmv.VARIANT_CODE = var_raw.VARIANT_CODE
  LEFT JOIN INT.DIM_DATE d_inv
    ON d_inv.CALENDAR_DATE = h.INVOICE_DATE
  LEFT JOIN INT.DIM_DATE d_del
    ON d_del.CALENDAR_DATE = h.DELIVERY_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_RETAIL_SALES loaded';
$$;
CALL INT.SP_LOAD_FCT_RETAIL_SALES();
SELECT * FROM FCT_RETAIL_SALES;

/* -------------------------------------------------------------------------------
   3.7 FCT_PURCHASE_ORDER (MERGE)
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_PURCHASE_ORDER()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  MERGE INTO INT.FCT_PURCHASE_ORDER tgt
  USING (
    SELECT
      h.PO_NO,
      l.LINE_NO::NUMBER AS PO_LINE_NO,
      d_po.DATE_KEY     AS PO_DATE_KEY,
      dv.VENDOR_KEY,
      dm.MATERIAL_KEY,
      dc.CONTRACT_KEY,
      dp.PLANT_KEY,
      l.ORDER_QTY,
      l.ORDER_UOM       AS UOM,
      d_prom.DATE_KEY   AS PROMISED_DELIVERY_DATE_KEY,
      d_exp.DATE_KEY    AS EXPECTED_ARRIVAL_DATE_KEY,
      IFF(l.SEASONAL_PEAK_FLAG='Y',TRUE,FALSE) AS SEASONAL_PEAK_FLAG,
      CASE UPPER(l.LINE_STATUS)
        WHEN 'OPEN'    THEN 'OPEN'
        WHEN 'PARTIAL' THEN 'PARTIALLY_DELIVERED'
        WHEN 'CLOSED'  THEN 'CLOSED'
        ELSE 'OTHER'
      END AS PO_STATUS,
      l.DW_BATCH_ID,
      l.DW_SOURCE_FILE_NAME
    FROM STG.VW_ERP_PO_LINE_STREAM s
    JOIN STG.VW_ERP_PO_LINE l
      ON s.PO_LINE_ID = l.PO_LINE_ID
    JOIN STG.VW_ERP_PO_HEADER h
      ON h.PO_ID = l.PO_ID
    LEFT JOIN STG.VW_ERP_PURCHASE_CONTRACT pc
      ON pc.CONTRACT_ID = h.CONTRACT_ID
    LEFT JOIN STG.VW_ERP_VENDOR v_raw
      ON v_raw.VENDOR_ID = h.VENDOR_ID
    LEFT JOIN STG.VW_ERP_PLANT p_raw
      ON p_raw.PLANT_ID = h.PLANT_ID
    LEFT JOIN STG.VW_ERP_MATERIAL m_raw
      ON m_raw.MATERIAL_ID = l.MATERIAL_ID
    LEFT JOIN INT.DIM_VENDOR dv
      ON dv.VENDOR_CODE = v_raw.VENDOR_CODE
    LEFT JOIN INT.DIM_PLANT dp
      ON dp.PLANT_CODE = p_raw.PLANT_CODE
    LEFT JOIN INT.DIM_RAW_MATERIAL dm
      ON dm.MATERIAL_CODE = m_raw.MATERIAL_CODE
    LEFT JOIN INT.DIM_SUPPLY_CONTRACT dc
      ON dc.CONTRACT_NO = pc.CONTRACT_NO
    LEFT JOIN INT.DIM_DATE d_po
      ON d_po.CALENDAR_DATE = h.PO_DATE
    LEFT JOIN INT.DIM_DATE d_prom
      ON d_prom.CALENDAR_DATE = l.PROMISED_DELIVERY_DATE
    LEFT JOIN INT.DIM_DATE d_exp
      ON d_exp.CALENDAR_DATE = l.EXPECTED_ARRIVAL_DATE
    WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
  ) src
  ON  tgt.PO_NO      = src.PO_NO
  AND tgt.PO_LINE_NO = src.PO_LINE_NO
  WHEN MATCHED THEN UPDATE SET
    tgt.PO_DATE_KEY                = src.PO_DATE_KEY,
    tgt.VENDOR_KEY                 = src.VENDOR_KEY,
    tgt.MATERIAL_KEY               = src.MATERIAL_KEY,
    tgt.CONTRACT_KEY               = src.CONTRACT_KEY,
    tgt.PLANT_KEY                  = src.PLANT_KEY,
    tgt.ORDER_QTY                  = src.ORDER_QTY,
    tgt.UOM                        = src.UOM,
    tgt.PROMISED_DELIVERY_DATE_KEY = src.PROMISED_DELIVERY_DATE_KEY,
    tgt.EXPECTED_ARRIVAL_DATE_KEY  = src.EXPECTED_ARRIVAL_DATE_KEY,
    tgt.SEASONAL_PEAK_FLAG         = src.SEASONAL_PEAK_FLAG,
    tgt.PO_STATUS                  = src.PO_STATUS,
    tgt.DW_LAST_UPDATED_TS         = CURRENT_TIMESTAMP(),
    tgt.DW_BATCH_ID                = src.DW_BATCH_ID,
    tgt.DW_SOURCE_FILE_NAME        = src.DW_SOURCE_FILE_NAME
  WHEN NOT MATCHED THEN INSERT (
    PO_NO, PO_LINE_NO, PO_DATE_KEY,
    VENDOR_KEY, MATERIAL_KEY, CONTRACT_KEY, PLANT_KEY,
    ORDER_QTY, UOM,
    PROMISED_DELIVERY_DATE_KEY, EXPECTED_ARRIVAL_DATE_KEY,
    SEASONAL_PEAK_FLAG, PO_STATUS,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  ) VALUES (
    src.PO_NO, src.PO_LINE_NO, src.PO_DATE_KEY,
    src.VENDOR_KEY, src.MATERIAL_KEY, src.CONTRACT_KEY, src.PLANT_KEY,
    src.ORDER_QTY, src.UOM,
    src.PROMISED_DELIVERY_DATE_KEY, src.EXPECTED_ARRIVAL_DATE_KEY,
    src.SEASONAL_PEAK_FLAG, src.PO_STATUS,
    CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), src.DW_BATCH_ID, src.DW_SOURCE_FILE_NAME
  )
`});
return 'FCT_PURCHASE_ORDER loaded';
$$;
CALL INT.SP_LOAD_FCT_PURCHASE_ORDER();
SELECT * FROM FCT_PURCHASE_ORDER;

/* -------------------------------------------------------------------------------
   3.8 FCT_INBOUND_SHIPMENT
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_INBOUND_SHIPMENT()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  INSERT INTO INT.FCT_INBOUND_SHIPMENT (
    GRN_NO, GRN_DATE_KEY,
    PO_NO, PO_LINE_NO,
    VENDOR_KEY, MATERIAL_KEY, PLANT_KEY,
    RECEIVED_QTY, REJECTED_QTY, ACCEPTED_QTY,
    EXPECTED_ARRIVAL_DATE_KEY, ACTUAL_ARRIVAL_DATE_KEY,
    DELIVERY_DELAY_DAYS, LEAD_TIME_DAYS,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  )
  SELECT
    g.GRN_NO,
    d_grn.DATE_KEY AS GRN_DATE_KEY,
    h.PO_NO,
    l.LINE_NO::NUMBER AS PO_LINE_NO,
    dv.VENDOR_KEY,
    dm.MATERIAL_KEY,
    dp.PLANT_KEY,
    g.RECEIVED_QTY,
    g.REJECTED_QTY,
    g.ACCEPTED_QTY,
    d_exp.DATE_KEY AS EXPECTED_ARRIVAL_DATE_KEY,
    d_act.DATE_KEY AS ACTUAL_ARRIVAL_DATE_KEY,
    DATEDIFF('day', g.EXPECTED_ARRIVAL_DATE, g.ACTUAL_ARRIVAL_DATE) AS DELIVERY_DELAY_DAYS,
    DATEDIFF('day', h.PO_DATE, g.ACTUAL_ARRIVAL_DATE)                AS LEAD_TIME_DAYS,
    CURRENT_TIMESTAMP(),
    CURRENT_TIMESTAMP(),
    g.DW_BATCH_ID,
    g.DW_SOURCE_FILE_NAME
  FROM STG.VW_ERP_GRN_STREAM s
  JOIN STG.VW_ERP_GRN g
    ON s.GRN_ID = g.GRN_ID
  LEFT JOIN STG.VW_ERP_PO_LINE l
    ON l.PO_LINE_ID = g.PO_LINE_ID
  LEFT JOIN STG.VW_ERP_PO_HEADER h
    ON h.PO_ID = l.PO_ID
  LEFT JOIN STG.VW_ERP_VENDOR v_raw
    ON v_raw.VENDOR_ID = g.VENDOR_ID
  LEFT JOIN STG.VW_ERP_PLANT p_raw
    ON p_raw.PLANT_ID = g.PLANT_ID
  LEFT JOIN STG.VW_ERP_MATERIAL m_raw
    ON m_raw.MATERIAL_ID = g.MATERIAL_ID
  LEFT JOIN INT.DIM_VENDOR dv
    ON dv.VENDOR_CODE = v_raw.VENDOR_CODE
  LEFT JOIN INT.DIM_PLANT dp
    ON dp.PLANT_CODE = p_raw.PLANT_CODE
  LEFT JOIN INT.DIM_RAW_MATERIAL dm
    ON dm.MATERIAL_CODE = m_raw.MATERIAL_CODE
  LEFT JOIN INT.DIM_DATE d_grn
    ON d_grn.CALENDAR_DATE = g.GRN_DATE
  LEFT JOIN INT.DIM_DATE d_exp
    ON d_exp.CALENDAR_DATE = g.EXPECTED_ARRIVAL_DATE
  LEFT JOIN INT.DIM_DATE d_act
    ON d_act.CALENDAR_DATE = g.ACTUAL_ARRIVAL_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_INBOUND_SHIPMENT loaded';
$$;
CALL INT.SP_LOAD_FCT_INBOUND_SHIPMENT();
SELECT * FROM INT.FCT_INBOUND_SHIPMENT;

/* -------------------------------------------------------------------------------
   3.9 FCT_DEMAND_FORECAST_DAILY
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_DEMAND_FORECAST_DAILY()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  INSERT INTO INT.FCT_DEMAND_FORECAST_DAILY (
    FORECAST_RUN_ID, DATE_KEY, DEALER_KEY, BMV_KEY,
    FORECAST_SOURCE, FORECAST_DEMAND_UNITS, FORECAST_GENERATED_DATE_KEY,
    SEASONAL_PEAK_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  )
  SELECT
    f.FORECAST_RUN_ID,
    d_for.DATE_KEY AS DATE_KEY,
    dd.DEALER_KEY,
    bmv.BMV_KEY,
    f.FORECAST_SOURCE,
    f.FORECAST_DEMAND_UNITS,
    d_gen.DATE_KEY AS FORECAST_GENERATED_DATE_KEY,
    IFF(f.SEASONAL_PEAK_FLAG='Y',TRUE,FALSE) AS SEASONAL_PEAK_FLAG,
    CURRENT_TIMESTAMP(),
    CURRENT_TIMESTAMP(),
    f.DW_BATCH_ID,
    f.DW_SOURCE_FILE_NAME
  FROM STG.VW_ERP_DEMAND_FORECAST_STREAM s
  JOIN STG.VW_ERP_DEMAND_FORECAST f
    ON s.FORECAST_RUN_ID = f.FORECAST_RUN_ID
  LEFT JOIN STG.VW_ERP_DEALER d_raw
    ON d_raw.DEALER_ID = f.DEALER_ID
  LEFT JOIN STG.VW_ERP_VARIANT var_raw
    ON var_raw.VARIANT_ID = f.VARIANT_ID
  LEFT JOIN INT.DIM_DEALER dd
    ON dd.DEALER_CODE = d_raw.DEALER_CODE
  LEFT JOIN INT.DIM_BRAND_MODEL_VARIANT bmv
    ON bmv.VARIANT_CODE = var_raw.VARIANT_CODE
  LEFT JOIN INT.DIM_DATE d_for
    ON d_for.CALENDAR_DATE = f.FORECAST_DATE
  LEFT JOIN INT.DIM_DATE d_gen
    ON d_gen.CALENDAR_DATE = f.FORECAST_GENERATED_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_DEMAND_FORECAST_DAILY loaded';
$$;
CALL INT.SP_LOAD_FCT_DEMAND_FORECAST_DAILY();
SELECT COUNT(*) FROM INT.FCT_DEMAND_FORECAST_DAILY;

/* -------------------------------------------------------------------------------
   3.10 FCT_ORDER_BACKLOG_DAILY
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_ORDER_BACKLOG_DAILY()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  INSERT INTO INT.FCT_ORDER_BACKLOG_DAILY (
    BACKLOG_RUN_ID, AS_OF_DATE_KEY, PLANT_KEY, BMV_KEY,
    TOTAL_OPEN_BOOKINGS_UNITS, NEAR_TERM_FORECAST_30D_UNITS,
    PLANT_FINISHED_STOCK_UNITS, DEALER_STOCK_UNITS,
    IN_TRANSIT_VEHICLE_UNITS, AVAILABLE_VEHICLE_SUPPLY_UNITS,
    PLANNED_PRODUCTION_30D_UNITS, EXPECTED_VENDOR_SUPPLY_30D_UOM,
    BACKLOG_UNITS, EXPECTED_AVG_DELAY_DAYS,
    RECOMMENDED_EXTRA_PRODUCTION_UNITS, RECOMMENDED_EXTRA_PROCUREMENT_UOM,
    SEASONAL_PEAK_FLAG,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  )
  SELECT
    b.BACKLOG_RUN_ID,
    d_asof.DATE_KEY AS AS_OF_DATE_KEY,
    dp.PLANT_KEY,
    bmv.BMV_KEY,
    b.TOTAL_OPEN_BOOKINGS_UNITS,
    b.NEAR_TERM_FORECAST_30D_UNITS,
    b.PLANT_FINISHED_STOCK_UNITS,
    b.DEALER_STOCK_UNITS,
    b.IN_TRANSIT_VEHICLE_UNITS,
    b.AVAILABLE_VEHICLE_SUPPLY_UNITS,
    b.PLANNED_PRODUCTION_30D_UNITS,
    b.EXPECTED_VENDOR_SUPPLY_30D_UOM,
    GREATEST(
      0,
      b.TOTAL_OPEN_BOOKINGS_UNITS + b.NEAR_TERM_FORECAST_30D_UNITS
        - (b.AVAILABLE_VEHICLE_SUPPLY_UNITS + b.PLANNED_PRODUCTION_30D_UNITS)
    ) AS BACKLOG_UNITS,
    CASE
      WHEN (b.AVAILABLE_VEHICLE_SUPPLY_UNITS + b.PLANNED_PRODUCTION_30D_UNITS) <= 0
        THEN NULL
      ELSE
        ROUND(
          GREATEST(
            0,
            b.TOTAL_OPEN_BOOKINGS_UNITS + b.NEAR_TERM_FORECAST_30D_UNITS
              - (b.AVAILABLE_VEHICLE_SUPPLY_UNITS + b.PLANNED_PRODUCTION_30D_UNITS)
          ) / NULLIF( (b.AVAILABLE_VEHICLE_SUPPLY_UNITS + b.PLANNED_PRODUCTION_30D_UNITS)/30, 0),
          1
        )
    END AS EXPECTED_AVG_DELAY_DAYS,
    GREATEST(
      0,
      GREATEST(
        0,
        b.TOTAL_OPEN_BOOKINGS_UNITS + b.NEAR_TERM_FORECAST_30D_UNITS
          - (b.AVAILABLE_VEHICLE_SUPPLY_UNITS + b.PLANNED_PRODUCTION_30D_UNITS)
      ) * 1.1
    )::NUMBER(18,0) AS RECOMMENDED_EXTRA_PRODUCTION_UNITS,
    GREATEST(0, b.EXPECTED_VENDOR_SUPPLY_30D_UOM * 0.1)
      AS RECOMMENDED_EXTRA_PROCUREMENT_UOM,
    IFF(b.SEASONAL_PEAK_FLAG='Y',TRUE,FALSE) AS SEASONAL_PEAK_FLAG,
    CURRENT_TIMESTAMP(),
    CURRENT_TIMESTAMP(),
    b.DW_BATCH_ID,
    b.DW_SOURCE_FILE_NAME
  FROM STG.VW_ERP_BACKLOG_SNAPSHOT_STREAM s
  JOIN STG.VW_ERP_BACKLOG_SNAPSHOT b
    ON s.BACKLOG_RUN_ID = b.BACKLOG_RUN_ID
  LEFT JOIN STG.VW_ERP_PLANT p_raw
    ON p_raw.PLANT_ID = b.PLANT_ID
  LEFT JOIN STG.VW_ERP_VARIANT var_raw
    ON var_raw.VARIANT_ID = b.VARIANT_ID
  LEFT JOIN INT.DIM_PLANT dp
    ON dp.PLANT_CODE = p_raw.PLANT_CODE
  LEFT JOIN INT.DIM_BRAND_MODEL_VARIANT bmv
    ON bmv.VARIANT_CODE = var_raw.VARIANT_CODE
  LEFT JOIN INT.DIM_DATE d_asof
    ON d_asof.CALENDAR_DATE = b.AS_OF_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_ORDER_BACKLOG_DAILY loaded';
$$;
CALL INT.SP_LOAD_FCT_ORDER_BACKLOG_DAILY();
SELECT COUNT(*) FROM INT.FCT_ORDER_BACKLOG_DAILY;

/* -------------------------------------------------------------------------------
   3.11 FCT_SERVICE_VISIT
------------------------------------------------------------------------------- */
CREATE OR REPLACE PROCEDURE SP_LOAD_FCT_SERVICE_VISIT()
RETURNS STRING
LANGUAGE JAVASCRIPT
EXECUTE AS OWNER
AS
$$
snowflake.execute({sqlText: `
  INSERT INTO INT.FCT_SERVICE_VISIT (
    SERVICE_VISIT_ID, SERVICE_DATE_KEY,
    SERVICE_CENTER_KEY, DEALER_KEY, VEHICLE_KEY, CUSTOMER_KEY,
    SERVICE_JOB_TYPE_KEY, ODOMETER_READING_KM,
    LABOUR_AMOUNT, PARTS_AMOUNT, TOTAL_BILL_AMOUNT,
    IS_WARRANTY_COVERED_FLAG,
    CUSTOMER_SATISFACTION_SCORE, NPS_SCORE,
    NEXT_SERVICE_DUE_DATE_KEY,
    DW_CREATED_TS, DW_LAST_UPDATED_TS, DW_BATCH_ID, DW_SOURCE_FILE_NAME
  )
  SELECT
    hdr.SERVICE_ORDER_ID   AS SERVICE_VISIT_ID,
    d_srv.DATE_KEY         AS SERVICE_DATE_KEY,
    sc.SERVICE_CENTER_KEY,
    dd.DEALER_KEY,
    dvh.VEHICLE_KEY,
    dc.CUSTOMER_KEY,
    NULL AS SERVICE_JOB_TYPE_KEY,
    hdr.KM_ODOMETER_READING,
    hdr.LABOUR_AMOUNT,
    hdr.PARTS_AMOUNT,
    hdr.TOTAL_BILL_AMOUNT,
    IFF(hdr.IS_WARRANTY_COVERED_FLAG='Y',TRUE,FALSE),
    hdr.CUSTOMER_SATISFACTION_SCORE,
    hdr.NPS_SCORE,
    d_next.DATE_KEY AS NEXT_SERVICE_DUE_DATE_KEY,
    CURRENT_TIMESTAMP(),
    CURRENT_TIMESTAMP(),
    hdr.DW_BATCH_ID,
    hdr.DW_SOURCE_FILE_NAME
  FROM STG.VW_ERP_SERVICE_ORDER_HDR_STREAM s
  JOIN STG.VW_ERP_SERVICE_ORDER_HDR hdr
    ON s.SERVICE_ORDER_ID = hdr.SERVICE_ORDER_ID
  LEFT JOIN STG.VW_ERP_SERVICE_CENTER sc_raw
    ON sc_raw.SERVICE_CENTER_ID = hdr.SERVICE_CENTER_ID
  LEFT JOIN STG.VW_ERP_DEALER d_raw
    ON d_raw.DEALER_ID = hdr.DEALER_ID
  LEFT JOIN STG.VW_ERP_VEHICLE_PRODUCTION vp_raw
    ON vp_raw.VEHICLE_ID = hdr.VEHICLE_ID
  LEFT JOIN STG.VW_ERP_CUSTOMER c_raw
    ON c_raw.CUSTOMER_ID = hdr.CUSTOMER_ID
  LEFT JOIN INT.DIM_SERVICE_CENTER sc
    ON sc.SERVICE_CENTER_CODE = sc_raw.SERVICE_CENTER_CODE
  LEFT JOIN INT.DIM_DEALER dd
    ON dd.DEALER_CODE = d_raw.DEALER_CODE
  LEFT JOIN INT.DIM_VEHICLE dvh
    ON dvh.VIN = vp_raw.VIN
  LEFT JOIN INT.DIM_CUSTOMER dc
    ON dc.CUSTOMER_ID = c_raw.CUSTOMER_ID
  LEFT JOIN INT.DIM_DATE d_srv
    ON d_srv.CALENDAR_DATE = hdr.SERVICE_DATE
  LEFT JOIN INT.DIM_DATE d_next
    ON d_next.CALENDAR_DATE = hdr.NEXT_SERVICE_DUE_DATE
  WHERE s.METADATA$ACTION IN ('INSERT','UPDATE')
`});
return 'FCT_SERVICE_VISIT loaded';
$$;
CALL INT.SP_LOAD_FCT_SERVICE_VISIT();
SELECT * FROM INT.FCT_SERVICE_VISIT;

