===========================================

/* ============================================================================
   MARUTI_AUTO_DWH — MARTS Layer (Views only)
   Creates KPI-ready views in correct dependency order.
   ============================================================================ */

USE DATABASE MARUTI_AUTO_DWH;
CREATE SCHEMA IF NOT EXISTS MARTS;
USE SCHEMA MARTS;

/* =============== 0) Small dimension helper lookups ========================= */
CREATE OR REPLACE VIEW V_DIM_BMV AS
SELECT
  BMV_KEY, BRAND_CODE, BRAND_NAME, MODEL_CODE, MODEL_NAME, VARIANT_CODE, VARIANT_NAME,
  FUEL_TYPE, TRANSMISSION_TYPE, ENGINE_CC, BODY_TYPE, LAUNCH_DATE_KEY
FROM INT.DIM_BRAND_MODEL_VARIANT;

CREATE OR REPLACE VIEW V_DIM_DEALER_BASE AS
SELECT
  d.DEALER_KEY, d.DEALER_CODE, d.DEALER_GROUP_NAME, d.SHOWROOM_NAME, d.SHOWROOM_TYPE,
  d.CHANNEL, g.REGION, g.STATE, g.DISTRICT, g.CITY
FROM INT.DIM_DEALER d
LEFT JOIN INT.DIM_GEOGRAPHY g ON g.GEO_KEY = d.GEO_KEY;

/* =============== 1) Forecast vs Actual (base) ============================== */
CREATE OR REPLACE VIEW V_FORECAST_VS_SALES_DAILY AS
WITH fc AS (
  SELECT DATE_KEY, DEALER_KEY, BMV_KEY,
         SUM(FORECAST_DEMAND_UNITS) AS forecast_units
  FROM INT.FCT_DEMAND_FORECAST_DAILY
  GROUP BY 1,2,3
),
act AS (
  SELECT INVOICE_DATE_KEY AS DATE_KEY, DEALER_KEY, BMV_KEY,
         COUNT(*) AS actual_units
  FROM INT.FCT_RETAIL_SALES
  GROUP BY 1,2,3
)
SELECT
  COALESCE(fc.DATE_KEY, act.DATE_KEY)     AS DATE_KEY,
  COALESCE(fc.DEALER_KEY, act.DEALER_KEY) AS DEALER_KEY,
  COALESCE(fc.BMV_KEY,    act.BMV_KEY)    AS BMV_KEY,
  COALESCE(fc.forecast_units, 0)          AS forecast_units,
  COALESCE(act.actual_units,   0)         AS actual_units,
  (COALESCE(fc.forecast_units,0) - COALESCE(act.actual_units,0))               AS error_units,
  ABS(COALESCE(fc.forecast_units,0) - COALESCE(act.actual_units,0))            AS abs_error_units,
  CASE WHEN COALESCE(act.actual_units,0)=0 THEN NULL
       ELSE (COALESCE(fc.forecast_units,0) - act.actual_units)
            / NULLIF(act.actual_units,0) END                                    AS bias_pct,
  CASE WHEN COALESCE(act.actual_units,0)=0 THEN NULL
       ELSE ABS(COALESCE(fc.forecast_units,0) - act.actual_units)
            / NULLIF(act.actual_units,0) END                                    AS mape_daily
FROM fc FULL OUTER JOIN act
  ON act.DATE_KEY=fc.DATE_KEY AND act.DEALER_KEY=fc.DEALER_KEY AND act.BMV_KEY=fc.BMV_KEY;

/* Weekly accuracy (MAPE/WAPE) */
CREATE OR REPLACE VIEW V_FORECAST_ACCURACY_WEEKLY AS
WITH base AS (
  SELECT
    d.YEAR, d.WEEK_OF_YEAR, v.DEALER_KEY, v.BMV_KEY,
    SUM(v.forecast_units) AS fc_units,
    SUM(v.actual_units)   AS act_units
  FROM MARTS.V_FORECAST_VS_SALES_DAILY v
  JOIN INT.DIM_DATE d ON d.DATE_KEY = v.DATE_KEY
  GROUP BY d.YEAR, d.WEEK_OF_YEAR, v.DEALER_KEY, v.BMV_KEY
)
SELECT
  YEAR, WEEK_OF_YEAR, DEALER_KEY, BMV_KEY, fc_units, act_units,
  CASE WHEN act_units=0 THEN NULL ELSE ABS(fc_units-act_units)::FLOAT/NULLIF(act_units,0) END AS mape,
  CASE WHEN SUM(act_units) OVER (PARTITION BY YEAR, WEEK_OF_YEAR)=0 THEN NULL
       ELSE ABS(fc_units-act_units)::FLOAT
            / NULLIF(SUM(act_units) OVER (PARTITION BY YEAR, WEEK_OF_YEAR),0) END           AS wape
FROM base;

/* Monthly accuracy */
CREATE OR REPLACE VIEW V_FORECAST_ACCURACY_MONTHLY AS
WITH base AS (
  SELECT
    d.YEAR, d.MONTH, v.DEALER_KEY, v.BMV_KEY,
    SUM(v.forecast_units) AS fc_units,
    SUM(v.actual_units)   AS act_units
  FROM MARTS.V_FORECAST_VS_SALES_DAILY v
  JOIN INT.DIM_DATE d ON d.DATE_KEY = v.DATE_KEY
  GROUP BY d.YEAR, d.MONTH, v.DEALER_KEY, v.BMV_KEY
)
SELECT
  YEAR, MONTH, DEALER_KEY, BMV_KEY, fc_units, act_units,
  CASE WHEN act_units=0 THEN NULL ELSE ABS(fc_units-act_units)::FLOAT/NULLIF(act_units,0) END AS mape
FROM base;

/* =============== 2) Delivery latency (Dispatch -> Arrival) ================= */
CREATE OR REPLACE VIEW V_DELIVERY_LATENCY AS
SELECT
  vd.DISPATCH_DATE_KEY,
  vd.EXPECTED_ARRIVAL_DATE_KEY,
  vd.ACTUAL_ARRIVAL_DATE_KEY,
  vd.PLANT_KEY,
  vd.DEALER_KEY,
  vd.BMV_KEY,
  vd.DISPATCH_QTY,
  vd.FREIGHT_COST,
  /* day diffs via DIM_DATE join */
  (dact.CALENDAR_DATE - dexp.CALENDAR_DATE) AS delay_days
FROM INT.FCT_VEHICLE_DISPATCH vd
LEFT JOIN INT.DIM_DATE dexp ON dexp.DATE_KEY = vd.EXPECTED_ARRIVAL_DATE_KEY
LEFT JOIN INT.DIM_DATE dact ON dact.DATE_KEY = vd.ACTUAL_ARRIVAL_DATE_KEY;

/* Aggregated latency by dealer/model/week */
CREATE OR REPLACE VIEW V_DELIVERY_LATENCY_WEEKLY AS
SELECT
  d.YEAR, d.WEEK_OF_YEAR,
  v.DEALER_KEY, v.BMV_KEY,
  AVG(v.delay_days)                      AS avg_delay_days,
  PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY v.delay_days) AS p90_delay_days,
  SUM(v.DISPATCH_QTY)                    AS qty_moved
FROM MARTS.V_DELIVERY_LATENCY v
JOIN INT.DIM_DATE d ON d.DATE_KEY = v.ACTUAL_ARRIVAL_DATE_KEY
GROUP BY d.YEAR, d.WEEK_OF_YEAR, v.DEALER_KEY, v.BMV_KEY;

/* =============== 3) Inventory ageing / Unused inventory ==================== */
CREATE OR REPLACE VIEW V_PLANT_INVENTORY_AGEING AS
SELECT
  s.DATE_KEY, s.PLANT_KEY, s.BMV_KEY,
  s.CLOSING_STOCK_UNITS,
  s.AGEING_30_PLUS_UNITS,
  /* You can extend with 60/90 if source has columns; here derive approx buckets */
  LEAST(s.AGEING_30_PLUS_UNITS, GREATEST(s.CLOSING_STOCK_UNITS - s.AGEING_30_PLUS_UNITS,0)) AS ageing_30_60_est,
  GREATEST(s.AGEING_30_PLUS_UNITS - LEAST(s.AGEING_30_PLUS_UNITS,
           GREATEST(s.CLOSING_STOCK_UNITS - s.AGEING_30_PLUS_UNITS,0)),0)                    AS ageing_60_plus_est
FROM INT.FCT_PLANT_INVENTORY_SNAPSHOT s;

CREATE OR REPLACE VIEW V_DEALER_INVENTORY_AGEING AS
SELECT
  s.DATE_KEY, s.DEALER_KEY, s.BMV_KEY,
  s.CLOSING_STOCK_UNITS,
  /* Assume 30+ parked in TEST_DRIVE_VEHICLES or slow movers ~ proxy */
  GREATEST(s.CLOSING_STOCK_UNITS - s.UNITS_SOLD, 0) AS potential_slow_movers
FROM INT.FCT_DEALER_STOCK_SNAPSHOT s;

/* Unused inventory candidates (ageing > 60 estimate or potential slow movers) */
CREATE OR REPLACE VIEW V_UNUSED_INVENTORY AS
SELECT
  'PLANT' AS level, p.DATE_KEY, p.PLANT_KEY AS LOC_KEY, NULL::NUMBER AS DEALER_KEY,
  p.BMV_KEY, p.CLOSING_STOCK_UNITS, p.ageing_60_plus_est AS unused_units
FROM MARTS.V_PLANT_INVENTORY_AGEING p
WHERE p.ageing_60_plus_est > 0
UNION ALL
SELECT
  'DEALER' AS level, d.DATE_KEY, NULL::NUMBER, d.DEALER_KEY,
  d.BMV_KEY, d.CLOSING_STOCK_UNITS, d.potential_slow_movers AS unused_units
FROM MARTS.V_DEALER_INVENTORY_AGEING d
WHERE d.potential_slow_movers > 0;

/* =============== 4) Manufacturing defects & Service KPIs =================== */
/* Join service header + fault lines to compute defect intensities */
CREATE OR REPLACE VIEW V_SERVICE_DEFECTS AS
WITH sv AS (
  SELECT SERVICE_VISIT_ID, SERVICE_DATE_KEY, DEALER_KEY, VEHICLE_KEY
  FROM INT.FCT_SERVICE_VISIT
),
ln AS (
  SELECT SERVICE_VISIT_ID, LINE_NO, FAULT_CODE_KEY, MATERIAL_KEY,
         IS_MANUFACTURING_DEFECT_FLAG, WARRANTY_FLAG, REPAIR_HOURS
  FROM INT.FCT_SERVICE_FAULT_DETAIL
)
SELECT
  sv.SERVICE_DATE_KEY,
  sv.DEALER_KEY,
  dv.BMV_KEY,
  ln.FAULT_CODE_KEY,
  SUM(IFF(ln.IS_MANUFACTURING_DEFECT_FLAG,1,0)) AS mfg_defect_count,
  SUM(1)                                        AS total_fault_lines,
  AVG(ln.REPAIR_HOURS)                          AS avg_repair_hours
FROM sv
LEFT JOIN ln ON ln.SERVICE_VISIT_ID = sv.SERVICE_VISIT_ID
LEFT JOIN INT.DIM_VEHICLE dv ON dv.VEHICLE_KEY = sv.VEHICLE_KEY
GROUP BY sv.SERVICE_DATE_KEY, sv.DEALER_KEY, dv.BMV_KEY, ln.FAULT_CODE_KEY;

CREATE OR REPLACE VIEW V_DEFECT_RATE_BY_MODEL_PLANT AS
WITH base AS (
  SELECT
    d.YEAR, d.MONTH,
    v.PLANT_KEY, s.BMV_KEY,
    SUM(s.mfg_defect_count) AS mfg_defects,
    SUM(s.total_fault_lines) AS total_faults
  FROM MARTS.V_SERVICE_DEFECTS s
  LEFT JOIN INT.DIM_DATE d ON d.DATE_KEY = s.SERVICE_DATE_KEY
  LEFT JOIN INT.DIM_VEHICLE v ON v.BMV_KEY = s.BMV_KEY
  GROUP BY d.YEAR, d.MONTH, v.PLANT_KEY, s.BMV_KEY
)
SELECT
  YEAR, MONTH, PLANT_KEY, BMV_KEY,
  mfg_defects,
  total_faults,
  CASE WHEN total_faults=0 THEN NULL ELSE mfg_defects::FLOAT/NULLIF(total_faults,0) END AS mfg_defect_rate
FROM base;

/* Warranty claim rate per 1k sales (by model x dealer x month) */
CREATE OR REPLACE VIEW V_WARRANTY_CLAIM_RATE AS
WITH sales AS (
  SELECT d.YEAR, d.MONTH, r.DEALER_KEY, r.BMV_KEY, COUNT(*) AS units_sold
  FROM INT.FCT_RETAIL_SALES r
  JOIN INT.DIM_DATE d ON d.DATE_KEY = r.INVOICE_DATE_KEY
  GROUP BY d.YEAR, d.MONTH, r.DEALER_KEY, r.BMV_KEY
),
claims AS (
  SELECT d.YEAR, d.MONTH, w.DEALER_KEY, dv.BMV_KEY, COUNT(*) AS claims
  FROM INT.FCT_WARRANTY_CLAIM w
  JOIN INT.DIM_DATE d ON d.DATE_KEY = w.CLAIM_DATE_KEY
  LEFT JOIN INT.DIM_VEHICLE dv ON dv.VEHICLE_KEY = w.VEHICLE_KEY
  GROUP BY d.YEAR, d.MONTH, w.DEALER_KEY, dv.BMV_KEY
)
SELECT
  COALESCE(s.YEAR, c.YEAR)   AS YEAR,
  COALESCE(s.MONTH, c.MONTH) AS MONTH,
  COALESCE(s.DEALER_KEY, c.DEALER_KEY) AS DEALER_KEY,
  COALESCE(s.BMV_KEY, c.BMV_KEY)       AS BMV_KEY,
  COALESCE(s.units_sold,0) AS units_sold,
  COALESCE(c.claims,0)     AS claims,
  CASE WHEN COALESCE(s.units_sold,0)=0 THEN NULL
       ELSE (COALESCE(c.claims,0)::FLOAT / NULLIF(s.units_sold,0)) * 1000 END AS claims_per_1000
FROM sales s FULL OUTER JOIN claims c
  ON s.YEAR=c.YEAR AND s.MONTH=c.MONTH AND s.DEALER_KEY=c.DEALER_KEY AND s.BMV_KEY=c.BMV_KEY;

/* Top Faults (by frequency) */
CREATE OR REPLACE VIEW V_TOP_FAULTS_BY_MODEL AS
SELECT
  d.YEAR, d.MONTH, s.BMV_KEY, s.FAULT_CODE_KEY,
  SUM(s.total_fault_lines) AS fault_count,
  RANK() OVER (PARTITION BY d.YEAR, d.MONTH, s.BMV_KEY
               ORDER BY SUM(s.total_fault_lines) DESC) AS fault_rank
FROM MARTS.V_SERVICE_DEFECTS s
JOIN INT.DIM_DATE d ON d.DATE_KEY = s.SERVICE_DATE_KEY
GROUP BY d.YEAR, d.MONTH, s.BMV_KEY, s.FAULT_CODE_KEY;

/* =============== 5) Booking -> Delivery latency & CX ======================= */
CREATE OR REPLACE VIEW V_BOOKING_TO_DELIVERY_LATENCY AS
SELECT
  r.BOOKING_ID,
  r.DEALER_KEY,
  r.BMV_KEY,
  /* Days between booking and delivery */
  (ddel.CALENDAR_DATE - dbook.CALENDAR_DATE) AS booking_to_delivery_days
FROM INT.FCT_RETAIL_SALES r
LEFT JOIN INT.DIM_DATE dbook ON dbook.DATE_KEY = r.BOOKING_ID::NUMBER /* if not linked, try BOOKING_DATE_KEY via joins */
LEFT JOIN INT.DIM_DATE ddel  ON ddel.DATE_KEY  = r.DELIVERY_DATE_KEY;

/* Customer Experience (from feedback + service) */
USE DATABASE MARUTI_AUTO_DWH;
USE SCHEMA MARTS;

CREATE OR REPLACE VIEW V_CX_SCORE_DAILY AS
WITH fb AS (
  SELECT
    f.FEEDBACK_DATE_KEY                       AS DATE_KEY,
    f.DEALER_KEY,
    dv.BMV_KEY,                               -- derive from vehicle
    AVG(f.OVERALL_SATISFACTION_SCORE) AS avg_osat,
    AVG(f.RECOMMEND_SCORE)            AS avg_reco,
    SUM(IFF(f.COMPLAINT_FLAG,1,0))    AS complaints,
    COUNT(*)                          AS feedback_cnt
  FROM INT.FCT_CUSTOMER_FEEDBACK f
  LEFT JOIN INT.DIM_VEHICLE dv
    ON dv.VEHICLE_KEY = f.VEHICLE_KEY
  GROUP BY 1,2,3
),
svc AS (
  SELECT
    v.SERVICE_DATE_KEY AS DATE_KEY,
    v.DEALER_KEY,
    dv.BMV_KEY,                               -- derive from vehicle
    AVG(v.NPS_SCORE) AS avg_nps
  FROM INT.FCT_SERVICE_VISIT v
  LEFT JOIN INT.DIM_VEHICLE dv
    ON dv.VEHICLE_KEY = v.VEHICLE_KEY
  GROUP BY 1,2,3
)
SELECT
  COALESCE(fb.DATE_KEY, svc.DATE_KEY)       AS DATE_KEY,
  COALESCE(fb.DEALER_KEY, svc.DEALER_KEY)   AS DEALER_KEY,
  COALESCE(fb.BMV_KEY,    svc.BMV_KEY)      AS BMV_KEY,
  fb.avg_osat,
  fb.avg_reco,
  svc.avg_nps,
  fb.complaints,
  fb.feedback_cnt
FROM fb
FULL OUTER JOIN svc
  ON fb.DATE_KEY  = svc.DATE_KEY
 AND fb.DEALER_KEY= svc.DEALER_KEY
 AND fb.BMV_KEY   = svc.BMV_KEY;


/* =============== 6) Revenue & Stock Turns ================================= */
CREATE OR REPLACE VIEW V_MODEL_REVENUE_MONTHLY AS
SELECT
  d.YEAR, d.MONTH, r.DEALER_KEY, r.BMV_KEY,
  SUM(r.ONROAD_PRICE) AS revenue
FROM INT.FCT_RETAIL_SALES r
JOIN INT.DIM_DATE d ON d.DATE_KEY = r.INVOICE_DATE_KEY
GROUP BY d.YEAR, d.MONTH, r.DEALER_KEY, r.BMV_KEY;

CREATE OR REPLACE VIEW V_MODEL_REVENUE_RANK AS
SELECT
  YEAR, MONTH, BMV_KEY,
  SUM(revenue) AS revenue,
  RANK() OVER (PARTITION BY YEAR, MONTH ORDER BY SUM(revenue) DESC) AS revenue_rank
FROM V_MODEL_REVENUE_MONTHLY
GROUP BY YEAR, MONTH, BMV_KEY;

/* Stock turns (Dealer level): Units sold / average stock */
CREATE OR REPLACE VIEW V_DEALER_STOCK_TURN_MONTHLY AS
WITH sold AS (
  SELECT d.YEAR, d.MONTH, DEALER_KEY, BMV_KEY, COUNT(*) AS units_sold
  FROM INT.FCT_RETAIL_SALES r
  JOIN INT.DIM_DATE d ON d.DATE_KEY = r.INVOICE_DATE_KEY
  GROUP BY d.YEAR, d.MONTH, DEALER_KEY, BMV_KEY
),
stk AS (
  SELECT d.YEAR, d.MONTH, DEALER_KEY, BMV_KEY,
         AVG(CLOSING_STOCK_UNITS) AS avg_stock
  FROM INT.FCT_DEALER_STOCK_SNAPSHOT s
  JOIN INT.DIM_DATE d ON d.DATE_KEY = s.DATE_KEY
  GROUP BY d.YEAR, d.MONTH, DEALER_KEY, BMV_KEY
)
SELECT
  COALESCE(sold.YEAR, stk.YEAR)     AS YEAR,
  COALESCE(sold.MONTH, stk.MONTH)   AS MONTH,
  COALESCE(sold.DEALER_KEY, stk.DEALER_KEY) AS DEALER_KEY,
  COALESCE(sold.BMV_KEY, stk.BMV_KEY)       AS BMV_KEY,
  COALESCE(sold.units_sold,0) AS units_sold,
  COALESCE(stk.avg_stock,0)  AS avg_stock,
  CASE WHEN COALESCE(stk.avg_stock,0)=0 THEN NULL
       ELSE COALESCE(sold.units_sold,0)::FLOAT/NULLIF(stk.avg_stock,0) END AS stock_turn
FROM sold FULL OUTER JOIN stk
 ON sold.YEAR=stk.YEAR AND sold.MONTH=stk.MONTH
AND sold.DEALER_KEY=stk.DEALER_KEY AND sold.BMV_KEY=stk.BMV_KEY;

/* =============== 7) Dealer grading (multi-KPI composite) =================== */
CREATE OR REPLACE VIEW V_DEALER_GRADE_MONTHLY AS
WITH sales AS (
  SELECT d.YEAR, d.MONTH, DEALER_KEY, COUNT(*) AS units_sold
  FROM INT.FCT_RETAIL_SALES r
  JOIN INT.DIM_DATE d ON d.DATE_KEY = r.INVOICE_DATE_KEY
  GROUP BY d.YEAR, d.MONTH, DEALER_KEY
),
cx AS (
  SELECT d.YEAR, d.MONTH, DEALER_KEY,
         AVG(CUSTOMER_SATISFACTION_SCORE) AS avg_csat,
         AVG(NPS_SCORE)                   AS avg_nps
  FROM INT.FCT_SERVICE_VISIT v
  JOIN INT.DIM_DATE d ON d.DATE_KEY = v.SERVICE_DATE_KEY
  GROUP BY d.YEAR, d.MONTH, DEALER_KEY
),
lat AS (
  SELECT d.YEAR, d.MONTH, DEALER_KEY, AVG(delay_days) AS avg_delay_days
  FROM MARTS.V_DELIVERY_LATENCY v
  JOIN INT.DIM_DATE d ON d.DATE_KEY = v.ACTUAL_ARRIVAL_DATE_KEY
  GROUP BY d.YEAR, d.MONTH, DEALER_KEY
),
wcr AS (
  SELECT YEAR, MONTH, DEALER_KEY,
         SUM(claims) AS claims, SUM(units_sold) AS units_sold
  FROM MARTS.V_WARRANTY_CLAIM_RATE
  GROUP BY YEAR, MONTH, DEALER_KEY
)
SELECT
  COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR)   AS YEAR,
  COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH) AS MONTH,
  COALESCE(sales.DEALER_KEY, cx.DEALER_KEY, lat.DEALER_KEY, wcr.DEALER_KEY) AS DEALER_KEY,
  /* Min/max normalization via percent_rank on each metric */
  PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                  COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                       ORDER BY COALESCE(sales.units_sold,0))                                 AS pr_units_sold,
  PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                  COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                       ORDER BY COALESCE(cx.avg_csat,0))                                      AS pr_csat,
  PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                  COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                       ORDER BY COALESCE(cx.avg_nps,0))                                       AS pr_nps,
  PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                  COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                       ORDER BY COALESCE(lat.avg_delay_days,0) DESC)                          AS pr_delay_penalty,
  PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                  COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                       ORDER BY (COALESCE(wcr.claims,0)::FLOAT/NULLIF(wcr.units_sold,0)) DESC) AS pr_claim_rate_penalty,
  /* Composite score (weights: sales 30%, csat 20%, nps 20%, delay 15% (penalty), claims 15% (penalty)) */
  (0.30*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                         COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                             ORDER BY COALESCE(sales.units_sold,0))
 +0.20*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                         COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                             ORDER BY COALESCE(cx.avg_csat,0))
 +0.20*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                         COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                             ORDER BY COALESCE(cx.avg_nps,0))
 +0.15*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                         COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                             ORDER BY COALESCE(lat.avg_delay_days,0) ASC)  /* less is better */
 +0.15*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                         COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                             ORDER BY (COALESCE(wcr.claims,0)::FLOAT/NULLIF(wcr.units_sold,0)) ASC)
  ) AS dealer_score,
  CASE
    WHEN (/* the composite above */ 0) IS NULL THEN 'C'
    ELSE CASE
      WHEN ( 0.30*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY COALESCE(sales.units_sold,0))
           + 0.20*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY COALESCE(cx.avg_csat,0))
           + 0.20*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY COALESCE(cx.avg_nps,0))
           + 0.15*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY COALESCE(lat.avg_delay_days,0) ASC)
           + 0.15*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY (COALESCE(wcr.claims,0)::FLOAT/NULLIF(wcr.units_sold,0)) ASC)
      ) >= 0.67 THEN 'A'
      WHEN ( 0.30*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY COALESCE(sales.units_sold,0))
           + 0.20*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY COALESCE(cx.avg_csat,0))
           + 0.20*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY COALESCE(cx.avg_nps,0))
           + 0.15*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY COALESCE(lat.avg_delay_days,0) ASC)
           + 0.15*PERCENT_RANK() OVER (PARTITION BY COALESCE(sales.YEAR, cx.YEAR, lat.YEAR, wcr.YEAR),
                                                   COALESCE(sales.MONTH, cx.MONTH, lat.MONTH, wcr.MONTH)
                                       ORDER BY (COALESCE(wcr.claims,0)::FLOAT/NULLIF(wcr.units_sold,0)) ASC)
      ) >= 0.33 THEN 'B'
      ELSE 'C'
    END
  END AS dealer_grade
FROM sales
FULL OUTER JOIN cx  USING (YEAR, MONTH, DEALER_KEY)
FULL OUTER JOIN lat USING (YEAR, MONTH, DEALER_KEY)
FULL OUTER JOIN wcr USING (YEAR, MONTH, DEALER_KEY);

/* =============== 8) Secure, PII-masked views for sharing =================== */
/* Dealer-scoped secure view (for RLS via DEALER_KEY filter at query time). */
CREATE OR REPLACE SECURE VIEW V_RETAIL_SALES_SECURE AS
SELECT
  r.INVOICE_NO, r.INVOICE_DATE_KEY, r.DELIVERY_DATE_KEY,
  r.DEALER_KEY, r.BMV_KEY, r.SALESPERSON_KEY, r.VEHICLE_KEY,
  r.EXSHOWROOM_PRICE, r.DISCOUNT_AMOUNT, r.ONROAD_PRICE,
  r.PAYMENT_MODE, r.PAYMENT_STATUS,
  /* PII masked from DIM_CUSTOMER */
  dc.CUSTOMER_KEY,
  CONCAT(LEFT(dc.EMAIL_ID, 3), '***@***')            AS EMAIL_MASKED,
  CONCAT('******', RIGHT(dc.MOBILE_NUMBER, 4))       AS MOBILE_MASKED
FROM INT.FCT_RETAIL_SALES r
LEFT JOIN INT.DIM_CUSTOMER dc ON dc.CUSTOMER_KEY = r.CUSTOMER_KEY;

/* CX secure (hides free-text) */
USE DATABASE MARUTI_AUTO_DWH;
USE SCHEMA MARTS;

CREATE OR REPLACE SECURE VIEW V_CX_SECURE AS
SELECT
  DATE_KEY,
  DEALER_KEY,
  BMV_KEY,
  avg_osat,
  avg_reco,
  avg_nps,
  complaints,
  feedback_cnt
FROM MARTS.V_CX_SCORE_DAILY;


/* =============== 9) Helpful joins for reporting ============================ */
CREATE OR REPLACE VIEW V_FORECAST_ACCURACY_WEEKLY_ENRICHED AS
SELECT
  a.*, dl.REGION, dl.STATE, dl.CITY,
  bmv.BRAND_NAME, bmv.MODEL_NAME, bmv.VARIANT_NAME
FROM V_FORECAST_ACCURACY_WEEKLY a
LEFT JOIN V_DIM_DEALER_BASE dl ON dl.DEALER_KEY = a.DEALER_KEY
LEFT JOIN V_DIM_BMV bmv        ON bmv.BMV_KEY   = a.BMV_KEY;

CREATE OR REPLACE VIEW V_MODEL_REVENUE_RANK_ENRICHED AS
SELECT
  r.*, bmv.BRAND_NAME, bmv.MODEL_NAME, bmv.VARIANT_NAME
FROM V_MODEL_REVENUE_RANK r
LEFT JOIN V_DIM_BMV bmv ON bmv.BMV_KEY = r.BMV_KEY;

/* =============== 10) Optional grants ====================================== */
/* Adjust roles as needed
GRANT USAGE ON SCHEMA MARTS TO ROLE ANALYST_R;
GRANT SELECT ON ALL VIEWS IN SCHEMA MARTS TO ROLE ANALYST_R;
ALTER SCHEMA MARTS TRANSFER OWNERSHIP TO ROLE DATA_GOVERNOR;
*/
USE DATABASE MARUTI_AUTO_DWH;
CREATE SCHEMA IF NOT EXISTS MARTS;
USE SCHEMA MARTS;

-- ---------------------------------------------------------------------------
-- 1) Production KPIs per day / plant / model-variant (shift-level)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW V_PRODUCTION_KPIS_DAILY AS
SELECT
  dd.CALENDAR_DATE                                         AS DATE,
  p.PLANT_CODE,
  p.PLANT_NAME,
  bmv.BRAND_CODE,
  bmv.BRAND_NAME,
  bmv.MODEL_CODE,
  bmv.MODEL_NAME,
  bmv.VARIANT_CODE,
  bmv.VARIANT_NAME,
  f.SHIFT,
  f.UNITS_PRODUCED,
  f.UNITS_REJECTED,
  f.UNITS_REWORKED,
  f.TOTAL_PRODUCTION_HRS,
  f.OEE_PERCENT,
  /* Derived KPIs */
  IFF(NULLIF(f.UNITS_PRODUCED,0) IS NULL, 0, f.UNITS_REJECTED / NULLIF(f.UNITS_PRODUCED,0)) AS REJECT_RATE,
  IFF(NULLIF(f.UNITS_PRODUCED,0) IS NULL, 0, f.UNITS_REWORKED  / NULLIF(f.UNITS_PRODUCED,0)) AS REWORK_RATE,
  IFF(NULLIF(f.TOTAL_PRODUCTION_HRS,0) IS NULL, NULL, f.UNITS_PRODUCED / NULLIF(f.TOTAL_PRODUCTION_HRS,0)) AS THROUGHPUT_UPH
FROM MARUTI_AUTO_DWH.INT.FCT_PRODUCTION_DAILY f
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE                dd  ON dd.DATE_KEY   = f.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_PLANT               p   ON p.PLANT_KEY   = f.PLANT_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY   = f.BMV_KEY;

-- ---------------------------------------------------------------------------
-- 2) Backlog & delay insights (daily, by plant and model-variant)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW V_BACKLOG_INSIGHTS_DAILY AS
SELECT
  dd.CALENDAR_DATE                                         AS AS_OF_DATE,
  p.PLANT_CODE,
  p.PLANT_NAME,
  bmv.BRAND_CODE,
  bmv.BRAND_NAME,
  bmv.MODEL_CODE,
  bmv.MODEL_NAME,
  bmv.VARIANT_CODE,
  bmv.VARIANT_NAME,
  f.TOTAL_OPEN_BOOKINGS_UNITS,
  f.NEAR_TERM_FORECAST_30D_UNITS,
  f.AVAILABLE_VEHICLE_SUPPLY_UNITS,
  f.PLANNED_PRODUCTION_30D_UNITS,
  f.EXPECTED_VENDOR_SUPPLY_30D_UOM,
  f.BACKLOG_UNITS,
  f.EXPECTED_AVG_DELAY_DAYS,
  f.RECOMMENDED_EXTRA_PRODUCTION_UNITS,
  f.RECOMMENDED_EXTRA_PROCUREMENT_UOM,
  f.SEASONAL_PEAK_FLAG
FROM MARUTI_AUTO_DWH.INT.FCT_ORDER_BACKLOG_DAILY f
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE                dd  ON dd.DATE_KEY   = f.AS_OF_DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_PLANT               p   ON p.PLANT_KEY   = f.PLANT_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY   = f.BMV_KEY;

-- ---------------------------------------------------------------------------
-- 3) Warranty & defects (daily; join fault meta + dealer + model)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW V_WARRANTY_DEFECTS_DAILY AS
SELECT
  dd.CALENDAR_DATE                                         AS CLAIM_DATE,
  d.DEALER_CODE,
  d.DEALER_GROUP_NAME,
  bmv.BRAND_CODE,
  bmv.BRAND_NAME,
  bmv.MODEL_CODE,
  bmv.MODEL_NAME,
  bmv.VARIANT_CODE,
  bmv.VARIANT_NAME,
  fc.FAULT_CODE,
  fc.FAULT_DESCRIPTION,
  fc.SEVERITY_LEVEL,
  fc.SYSTEM_AREA,
  f.MANUFACTURING_DEFECT_FLAG,
  /* Aggregates at row-level already represent a claim; expose amounts and simple ratios */
  f.CLAIM_AMOUNT,
  f.APPROVED_AMOUNT,
  IFF(NULLIF(f.CLAIM_AMOUNT,0) IS NULL, NULL, f.APPROVED_AMOUNT/NULLIF(f.CLAIM_AMOUNT,0)) AS APPROVAL_RATE
FROM MARUTI_AUTO_DWH.INT.FCT_WARRANTY_CLAIM f
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE            dd  ON dd.DATE_KEY          = f.CLAIM_DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DEALER          d   ON d.DEALER_KEY         = f.DEALER_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_FAULT_CODE      fc  ON fc.FAULT_CODE_KEY    = f.FAULT_CODE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_VEHICLE         vh  ON vh.VEHICLE_KEY       = f.VEHICLE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY      = vh.BMV_KEY;

-- ---------------------------------------------------------------------------
-- 4) Dealer scorecard (daily, per dealer) — sales, bookings, CX, stock
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW V_DEALER_SCORECARD_DAILY AS
WITH sales AS (
  SELECT
    rs.DEALER_KEY,
    rs.INVOICE_DATE_KEY AS DATE_KEY,
    COUNT(*)                           AS UNITS_SOLD,
    SUM(rs.ONROAD_PRICE)               AS ONROAD_REVENUE,
    AVG(rs.DISCOUNT_AMOUNT)            AS AVG_DISCOUNT
  FROM MARUTI_AUTO_DWH.INT.FCT_RETAIL_SALES rs
  GROUP BY rs.DEALER_KEY, rs.INVOICE_DATE_KEY
),
bookings AS (
  SELECT
    b.DEALER_KEY,
    b.BOOKING_DATE_KEY AS DATE_KEY,
    COUNT(*)           AS BOOKINGS_CNT
  FROM MARUTI_AUTO_DWH.INT.FCT_BOOKING b
  GROUP BY b.DEALER_KEY, b.BOOKING_DATE_KEY
),
cx AS (
  SELECT
    f.DEALER_KEY,
    f.FEEDBACK_DATE_KEY AS DATE_KEY,
    AVG(f.OVERALL_SATISFACTION_SCORE) AS AVG_CSAT,
    AVG(f.RECOMMEND_SCORE)            AS AVG_RECOMMEND
  FROM MARUTI_AUTO_DWH.INT.FCT_CUSTOMER_FEEDBACK f
  GROUP BY f.DEALER_KEY, f.FEEDBACK_DATE_KEY
),
stock AS (
  SELECT
    s.DEALER_KEY,
    s.DATE_KEY,
    SUM(s.CLOSING_STOCK_UNITS)        AS CLOSING_STOCK_UNITS,
    SUM(s.UNITS_RECEIVED)             AS UNITS_RECEIVED,
    SUM(s.UNITS_SOLD)                 AS UNITS_SOLD
  FROM MARUTI_AUTO_DWH.INT.FCT_DEALER_STOCK_SNAPSHOT s
  GROUP BY s.DEALER_KEY, s.DATE_KEY
)
SELECT
  dd.CALENDAR_DATE                                 AS DATE,
  d.DEALER_CODE,
  d.DEALER_GROUP_NAME,
  COALESCE(sales.UNITS_SOLD,0)                     AS UNITS_SOLD,
  COALESCE(sales.ONROAD_REVENUE,0)                 AS ONROAD_REVENUE,
  sales.AVG_DISCOUNT,
  COALESCE(bookings.BOOKINGS_CNT,0)                AS BOOKINGS_CNT,
  IFF(COALESCE(bookings.BOOKINGS_CNT,0)=0, NULL,
      COALESCE(sales.UNITS_SOLD,0)/NULLIF(bookings.BOOKINGS_CNT,0)) AS SALES_CONV_RATE,
  cx.AVG_CSAT,
  cx.AVG_RECOMMEND,
  stock.CLOSING_STOCK_UNITS,
  stock.UNITS_RECEIVED  AS DEALER_UNITS_IN,
  stock.UNITS_SOLD      AS DEALER_UNITS_OUT
FROM ( -- drive by all dealer-dates that appear anywhere
  SELECT DEALER_KEY, DATE_KEY FROM sales
  UNION SELECT DEALER_KEY, DATE_KEY FROM bookings
  UNION SELECT DEALER_KEY, DATE_KEY FROM cx
  UNION SELECT DEALER_KEY, DATE_KEY FROM stock
) k
LEFT JOIN sales    ON sales.DEALER_KEY  = k.DEALER_KEY AND sales.DATE_KEY  = k.DATE_KEY
LEFT JOIN bookings ON bookings.DEALER_KEY=k.DEALER_KEY AND bookings.DATE_KEY=k.DATE_KEY
LEFT JOIN cx       ON cx.DEALER_KEY     = k.DEALER_KEY AND cx.DATE_KEY     = k.DATE_KEY
LEFT JOIN stock    ON stock.DEALER_KEY  = k.DEALER_KEY AND stock.DATE_KEY  = k.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DEALER d  ON d.DEALER_KEY = k.DEALER_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE   dd ON dd.DATE_KEY  = k.DATE_KEY;

-- ---------------------------------------------------------------------------
-- 5) Inventory flow (normalize plant/dealer snapshots with common columns)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW V_INVENTORY_FLOW_DAILY AS
SELECT
  dd.CALENDAR_DATE                                 AS DATE,
  'PLANT'                                          AS ENTITY_TYPE,
  p.PLANT_CODE                                     AS ENTITY_CODE,
  p.PLANT_NAME                                     AS ENTITY_NAME,
  bmv.BRAND_CODE,
  bmv.MODEL_CODE,
  bmv.VARIANT_CODE,
  s.OPENING_STOCK_UNITS,
  s.UNITS_PRODUCED           AS UNITS_IN,
  s.UNITS_DISPATCHED         AS UNITS_OUT,
  s.CLOSING_STOCK_UNITS,
  s.AGEING_30_PLUS_UNITS
FROM MARUTI_AUTO_DWH.INT.FCT_PLANT_INVENTORY_SNAPSHOT s
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE                dd  ON dd.DATE_KEY = s.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_PLANT               p   ON p.PLANT_KEY = s.PLANT_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY = s.BMV_KEY

UNION ALL
SELECT
  dd.CALENDAR_DATE                                 AS DATE,
  'DEALER'                                         AS ENTITY_TYPE,
  d.DEALER_CODE                                    AS ENTITY_CODE,
  d.DEALER_GROUP_NAME                              AS ENTITY_NAME,
  bmv.BRAND_CODE,
  bmv.MODEL_CODE,
  bmv.VARIANT_CODE,
  s.OPENING_STOCK_UNITS,
  s.UNITS_RECEIVED           AS UNITS_IN,
  (s.UNITS_SOLD + s.UNITS_TRANSFERRED_OUT)         AS UNITS_OUT,
  s.CLOSING_STOCK_UNITS,
  NULL                                             AS AGEING_30_PLUS_UNITS
FROM MARUTI_AUTO_DWH.INT.FCT_DEALER_STOCK_SNAPSHOT s
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE                dd  ON dd.DATE_KEY = s.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DEALER              d   ON d.DEALER_KEY = s.DEALER_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY = s.BMV_KEY;

-- ---------------------------------------------------------------------------
-- 6) Procurement lead-time and delivery performance (daily)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE VIEW V_PROCUREMENT_LT_DAILY AS
SELECT
  dd.CALENDAR_DATE                                 AS GRN_DATE,
  v.VENDOR_CODE,
  v.VENDOR_NAME,
  m.MATERIAL_CODE,
  m.MATERIAL_NAME,
  p.PLANT_CODE,
  p.PLANT_NAME,
  /* Shipment-level measures */
  s.ACCEPTED_QTY,
  s.RECEIVED_QTY,
  s.REJECTED_QTY,
  s.LEAD_TIME_DAYS,
  s.DELIVERY_DELAY_DAYS,
  /* Derived KPIs */
  IFF(NULLIF(s.RECEIVED_QTY,0) IS NULL, NULL, s.REJECTED_QTY/NULLIF(s.RECEIVED_QTY,0)) AS REJECTION_RATE
FROM MARUTI_AUTO_DWH.INT.FCT_INBOUND_SHIPMENT s
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE          dd ON dd.DATE_KEY   = s.GRN_DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_VENDOR        v  ON v.VENDOR_KEY  = s.VENDOR_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_RAW_MATERIAL  m  ON m.MATERIAL_KEY= s.MATERIAL_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_PLANT         p  ON p.PLANT_KEY   = s.PLANT_KEY;

====================================================================================
-- =====================================================================================
-- Speed up Streamlit: Convert marts views to Dynamic Tables (24h refresh) + thin views
-- =====================================================================================
USE DATABASE MARUTI_AUTO_DWH;
CREATE SCHEMA IF NOT EXISTS MARTS;
USE SCHEMA MARTS;
USE WAREHOUSE COMPUTE_WH;  -- <== change if needed

-- ---------------------------
-- 1) PRODUCTION KPIs (Daily)
-- ---------------------------
CREATE OR REPLACE DYNAMIC TABLE DT_PRODUCTION_KPIS_DAILY
  TARGET_LAG = '24 hours'
  WAREHOUSE = COMPUTE_WH
AS
SELECT
  dd.CALENDAR_DATE                                         AS DATE,
  p.PLANT_CODE,
  p.PLANT_NAME,
  bmv.BRAND_CODE, bmv.BRAND_NAME,
  bmv.MODEL_CODE, bmv.MODEL_NAME,
  bmv.VARIANT_CODE, bmv.VARIANT_NAME,
  f.SHIFT,
  f.UNITS_PRODUCED, f.UNITS_REJECTED, f.UNITS_REWORKED,
  f.TOTAL_PRODUCTION_HRS, f.OEE_PERCENT,
  IFF(NULLIF(f.UNITS_PRODUCED,0) IS NULL, 0, f.UNITS_REJECTED / NULLIF(f.UNITS_PRODUCED,0)) AS REJECT_RATE,
  IFF(NULLIF(f.UNITS_PRODUCED,0) IS NULL, 0, f.UNITS_REWORKED  / NULLIF(f.UNITS_PRODUCED,0)) AS REWORK_RATE,
  IFF(NULLIF(f.TOTAL_PRODUCTION_HRS,0) IS NULL, NULL, f.UNITS_PRODUCED / NULLIF(f.TOTAL_PRODUCTION_HRS,0)) AS THROUGHPUT_UPH
FROM MARUTI_AUTO_DWH.INT.FCT_PRODUCTION_DAILY f
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE                dd  ON dd.DATE_KEY   = f.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_PLANT               p   ON p.PLANT_KEY   = f.PLANT_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY   = f.BMV_KEY;

CREATE OR REPLACE VIEW V_PRODUCTION_KPIS_DAILY AS
SELECT * FROM DT_PRODUCTION_KPIS_DAILY;

-- ---------------------------------
-- 2) BACKLOG & DELAY INSIGHTS (Dly)
-- ---------------------------------
CREATE OR REPLACE DYNAMIC TABLE DT_BACKLOG_INSIGHTS_DAILY
  TARGET_LAG = '24 hours'
  WAREHOUSE = COMPUTE_WH
AS
SELECT
  dd.CALENDAR_DATE AS AS_OF_DATE,
  p.PLANT_CODE, p.PLANT_NAME,
  bmv.BRAND_CODE, bmv.BRAND_NAME,
  bmv.MODEL_CODE, bmv.MODEL_NAME,
  bmv.VARIANT_CODE, bmv.VARIANT_NAME,
  f.TOTAL_OPEN_BOOKINGS_UNITS,
  f.NEAR_TERM_FORECAST_30D_UNITS,
  f.AVAILABLE_VEHICLE_SUPPLY_UNITS,
  f.PLANNED_PRODUCTION_30D_UNITS,
  f.EXPECTED_VENDOR_SUPPLY_30D_UOM,
  f.BACKLOG_UNITS,
  f.EXPECTED_AVG_DELAY_DAYS,
  f.RECOMMENDED_EXTRA_PRODUCTION_UNITS,
  f.RECOMMENDED_EXTRA_PROCUREMENT_UOM,
  f.SEASONAL_PEAK_FLAG
FROM MARUTI_AUTO_DWH.INT.FCT_ORDER_BACKLOG_DAILY f
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE                dd  ON dd.DATE_KEY   = f.AS_OF_DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_PLANT               p   ON p.PLANT_KEY   = f.PLANT_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY   = f.BMV_KEY;

CREATE OR REPLACE VIEW V_BACKLOG_INSIGHTS_DAILY AS
SELECT * FROM DT_BACKLOG_INSIGHTS_DAILY;

-- -----------------------------------
-- 3) WARRANTY & DEFECTS CLAIMS (Dly)
-- -----------------------------------
CREATE OR REPLACE DYNAMIC TABLE DT_WARRANTY_DEFECTS_DAILY
  TARGET_LAG = '24 hours'
  WAREHOUSE  = COMPUTE_WH
AS
SELECT
  dd.CALENDAR_DATE AS CLAIM_DATE,
  d.DEALER_CODE, d.DEALER_GROUP_NAME,
  bmv.BRAND_CODE, bmv.BRAND_NAME,
  bmv.MODEL_CODE, bmv.MODEL_NAME,
  bmv.VARIANT_CODE, bmv.VARIANT_NAME,
  fc.FAULT_CODE, fc.FAULT_DESCRIPTION, fc.SEVERITY_LEVEL, fc.SYSTEM_AREA,
  f.MANUFACTURING_DEFECT_FLAG,
  f.CLAIM_AMOUNT, f.APPROVED_AMOUNT,
  IFF(NULLIF(f.CLAIM_AMOUNT,0) IS NULL, NULL, f.APPROVED_AMOUNT/NULLIF(f.CLAIM_AMOUNT,0)) AS APPROVAL_RATE
FROM MARUTI_AUTO_DWH.INT.FCT_WARRANTY_CLAIM f
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE            dd  ON dd.DATE_KEY          = f.CLAIM_DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DEALER          d   ON d.DEALER_KEY         = f.DEALER_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_FAULT_CODE      fc  ON fc.FAULT_CODE_KEY    = f.FAULT_CODE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_VEHICLE         vh  ON vh.VEHICLE_KEY       = f.VEHICLE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY      = vh.BMV_KEY;

CREATE OR REPLACE VIEW V_WARRANTY_DEFECTS_DAILY AS
SELECT * FROM DT_WARRANTY_DEFECTS_DAILY;

-- ---------------------------------
-- 4) DEALER SCORECARD (Agg Daily)
-- ---------------------------------
CREATE OR REPLACE DYNAMIC TABLE DT_DEALER_SCORECARD_DAILY
  TARGET_LAG = '24 hours'
  WAREHOUSE  = COMPUTE_WH
AS
WITH sales AS (
  SELECT rs.DEALER_KEY, rs.INVOICE_DATE_KEY AS DATE_KEY,
         COUNT(*) AS UNITS_SOLD, SUM(rs.ONROAD_PRICE) AS ONROAD_REVENUE,
         AVG(rs.DISCOUNT_AMOUNT) AS AVG_DISCOUNT
  FROM MARUTI_AUTO_DWH.INT.FCT_RETAIL_SALES rs
  GROUP BY rs.DEALER_KEY, rs.INVOICE_DATE_KEY
),
bookings AS (
  SELECT b.DEALER_KEY, b.BOOKING_DATE_KEY AS DATE_KEY,
         COUNT(*) AS BOOKINGS_CNT
  FROM MARUTI_AUTO_DWH.INT.FCT_BOOKING b
  GROUP BY b.DEALER_KEY, b.BOOKING_DATE_KEY
),
cx AS (
  SELECT f.DEALER_KEY, f.FEEDBACK_DATE_KEY AS DATE_KEY,
         AVG(f.OVERALL_SATISFACTION_SCORE) AS AVG_CSAT,
         AVG(f.RECOMMEND_SCORE)            AS AVG_RECOMMEND
  FROM MARUTI_AUTO_DWH.INT.FCT_CUSTOMER_FEEDBACK f
  GROUP BY f.DEALER_KEY, f.FEEDBACK_DATE_KEY
),
stock AS (
  SELECT s.DEALER_KEY, s.DATE_KEY,
         SUM(s.CLOSING_STOCK_UNITS) AS CLOSING_STOCK_UNITS,
         SUM(s.UNITS_RECEIVED)      AS UNITS_RECEIVED,
         SUM(s.UNITS_SOLD)          AS UNITS_SOLD
  FROM MARUTI_AUTO_DWH.INT.FCT_DEALER_STOCK_SNAPSHOT s
  GROUP BY s.DEALER_KEY, s.DATE_KEY
),
keys AS (
  SELECT DEALER_KEY, DATE_KEY FROM sales
  UNION SELECT DEALER_KEY, DATE_KEY FROM bookings
  UNION SELECT DEALER_KEY, DATE_KEY FROM cx
  UNION SELECT DEALER_KEY, DATE_KEY FROM stock
)
SELECT
  dd.CALENDAR_DATE AS DATE,
  d.DEALER_CODE, d.DEALER_GROUP_NAME,
  COALESCE(sales.UNITS_SOLD,0)      AS UNITS_SOLD,
  COALESCE(sales.ONROAD_REVENUE,0)  AS ONROAD_REVENUE,
  sales.AVG_DISCOUNT,
  COALESCE(bookings.BOOKINGS_CNT,0) AS BOOKINGS_CNT,
  IFF(COALESCE(bookings.BOOKINGS_CNT,0)=0, NULL,
      COALESCE(sales.UNITS_SOLD,0)/NULLIF(bookings.BOOKINGS_CNT,0)) AS SALES_CONV_RATE,
  cx.AVG_CSAT,
  cx.AVG_RECOMMEND,
  stock.CLOSING_STOCK_UNITS,
  stock.UNITS_RECEIVED  AS DEALER_UNITS_IN,
  stock.UNITS_SOLD      AS DEALER_UNITS_OUT
FROM keys k
LEFT JOIN sales    ON sales.DEALER_KEY   = k.DEALER_KEY AND sales.DATE_KEY   = k.DATE_KEY
LEFT JOIN bookings ON bookings.DEALER_KEY= k.DEALER_KEY AND bookings.DATE_KEY= k.DATE_KEY
LEFT JOIN cx       ON cx.DEALER_KEY      = k.DEALER_KEY AND cx.DATE_KEY      = k.DATE_KEY
LEFT JOIN stock    ON stock.DEALER_KEY   = k.DEALER_KEY AND stock.DATE_KEY   = k.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DEALER d  ON d.DEALER_KEY = k.DEALER_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE   dd ON dd.DATE_KEY  = k.DATE_KEY;

CREATE OR REPLACE VIEW V_DEALER_SCORECARD_DAILY AS
SELECT * FROM DT_DEALER_SCORECARD_DAILY;

-- -----------------------------------
-- 5) INVENTORY FLOW (Plant+Dealer)
-- -----------------------------------
CREATE OR REPLACE DYNAMIC TABLE DT_INVENTORY_FLOW_DAILY
  TARGET_LAG = '24 hours'
  WAREHOUSE  = COMPUTE_WH
AS
SELECT
  dd.CALENDAR_DATE AS DATE,
  'PLANT'          AS ENTITY_TYPE,
  p.PLANT_CODE     AS ENTITY_CODE,
  p.PLANT_NAME     AS ENTITY_NAME,
  bmv.BRAND_CODE, bmv.MODEL_CODE, bmv.VARIANT_CODE,
  s.OPENING_STOCK_UNITS,
  s.UNITS_PRODUCED AS UNITS_IN,
  s.UNITS_DISPATCHED AS UNITS_OUT,
  s.CLOSING_STOCK_UNITS,
  s.AGEING_30_PLUS_UNITS
FROM MARUTI_AUTO_DWH.INT.FCT_PLANT_INVENTORY_SNAPSHOT s
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE                dd  ON dd.DATE_KEY = s.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_PLANT               p   ON p.PLANT_KEY = s.PLANT_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY = s.BMV_KEY

UNION ALL
SELECT
  dd.CALENDAR_DATE AS DATE,
  'DEALER'         AS ENTITY_TYPE,
  d.DEALER_CODE    AS ENTITY_CODE,
  d.DEALER_GROUP_NAME AS ENTITY_NAME,
  bmv.BRAND_CODE, bmv.MODEL_CODE, bmv.VARIANT_CODE,
  s.OPENING_STOCK_UNITS,
  s.UNITS_RECEIVED  AS UNITS_IN,
  (s.UNITS_SOLD + s.UNITS_TRANSFERRED_OUT) AS UNITS_OUT,
  s.CLOSING_STOCK_UNITS,
  NULL AS AGEING_30_PLUS_UNITS
FROM MARUTI_AUTO_DWH.INT.FCT_DEALER_STOCK_SNAPSHOT s
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE                dd  ON dd.DATE_KEY = s.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DEALER              d   ON d.DEALER_KEY = s.DEALER_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY = s.BMV_KEY;

CREATE OR REPLACE VIEW V_INVENTORY_FLOW_DAILY AS
SELECT * FROM DT_INVENTORY_FLOW_DAILY;

-- ----------------------------------------
-- 6) PROCUREMENT Lead Time / Delivery (D)
-- ----------------------------------------
CREATE OR REPLACE DYNAMIC TABLE DT_PROCUREMENT_LT_DAILY
  TARGET_LAG = '24 hours'
  WAREHOUSE  = COMPUTE_WH
AS
SELECT
  dd.CALENDAR_DATE AS GRN_DATE,
  v.VENDOR_CODE, v.VENDOR_NAME,
  m.MATERIAL_CODE, m.MATERIAL_NAME,
  p.PLANT_CODE,   p.PLANT_NAME,
  s.ACCEPTED_QTY, s.RECEIVED_QTY, s.REJECTED_QTY,
  s.LEAD_TIME_DAYS, s.DELIVERY_DELAY_DAYS,
  IFF(NULLIF(s.RECEIVED_QTY,0) IS NULL, NULL, s.REJECTED_QTY/NULLIF(s.RECEIVED_QTY,0)) AS REJECTION_RATE
FROM MARUTI_AUTO_DWH.INT.FCT_INBOUND_SHIPMENT s
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE          dd ON dd.DATE_KEY   = s.GRN_DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_VENDOR        v  ON v.VENDOR_KEY  = s.VENDOR_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_RAW_MATERIAL  m  ON m.MATERIAL_KEY= s.MATERIAL_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_PLANT         p  ON p.PLANT_KEY   = s.PLANT_KEY;

CREATE OR REPLACE VIEW V_PROCUREMENT_LT_DAILY AS
SELECT * FROM DT_PROCUREMENT_LT_DAILY;

