USE DATABASE MARUTI_AUTO_DWH;
CREATE SCHEMA IF NOT EXISTS MARTS;
USE SCHEMA MARTS;
USE WAREHOUSE COMPUTE_WH;

/* ============================================================
   1) Forecast vs Sales (Daily)  -> DT + thin View
   ============================================================ */
CREATE OR REPLACE DYNAMIC TABLE DT_FORECAST_VS_SALES_DAILY
  TARGET_LAG = '24 hours'
  WAREHOUSE = COMPUTE_WH
AS
WITH sales AS (
  SELECT
    rs.INVOICE_DATE_KEY      AS DATE_KEY,
    rs.DEALER_KEY,
    rs.BMV_KEY,
    COUNT(*)                 AS ACTUAL_UNITS,
    SUM(rs.ONROAD_PRICE)     AS ACTUAL_REVENUE
  FROM MARUTI_AUTO_DWH.INT.FCT_RETAIL_SALES rs
  GROUP BY rs.INVOICE_DATE_KEY, rs.DEALER_KEY, rs.BMV_KEY
),
fc AS (
  SELECT
    f.DATE_KEY,
    f.DEALER_KEY,
    f.BMV_KEY,
    SUM(f.FORECAST_DEMAND_UNITS) AS FORECAST_UNITS,
    MAX(f.SEASONAL_PEAK_FLAG)    AS SEASONAL_PEAK_FLAG
  FROM MARUTI_AUTO_DWH.INT.FCT_DEMAND_FORECAST_DAILY f
  GROUP BY f.DATE_KEY, f.DEALER_KEY, f.BMV_KEY
),
keys AS (
  SELECT DATE_KEY, DEALER_KEY, BMV_KEY FROM sales
  UNION
  SELECT DATE_KEY, DEALER_KEY, BMV_KEY FROM fc
)
SELECT
  dd.CALENDAR_DATE                                        AS DATE,
  d.DEALER_CODE, d.DEALER_GROUP_NAME,
  bmv.BRAND_CODE, bmv.BRAND_NAME,
  bmv.MODEL_CODE, bmv.MODEL_NAME,
  bmv.VARIANT_CODE, bmv.VARIANT_NAME,
  COALESCE(fc.FORECAST_UNITS, 0)                          AS FORECAST_UNITS,
  COALESCE(sales.ACTUAL_UNITS, 0)                         AS ACTUAL_UNITS,
  COALESCE(sales.ACTUAL_REVENUE, 0)                       AS ACTUAL_REVENUE,
  (COALESCE(fc.FORECAST_UNITS,0) - COALESCE(sales.ACTUAL_UNITS,0)) AS VARIANCE_UNITS,
  IFF(NULLIF(COALESCE(sales.ACTUAL_UNITS,0),0) IS NULL, NULL,
      ABS(COALESCE(fc.FORECAST_UNITS,0) - sales.ACTUAL_UNITS) / NULLIF(sales.ACTUAL_UNITS,0)
  )                                                       AS MAPE_LIKE_ERROR,
  fc.SEASONAL_PEAK_FLAG
FROM keys k
LEFT JOIN sales ON sales.DATE_KEY = k.DATE_KEY
              AND sales.DEALER_KEY = k.DEALER_KEY
              AND sales.BMV_KEY = k.BMV_KEY
LEFT JOIN fc    ON fc.DATE_KEY = k.DATE_KEY
              AND fc.DEALER_KEY = k.DEALER_KEY
              AND fc.BMV_KEY = k.BMV_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE dd ON dd.DATE_KEY = k.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DEALER d ON d.DEALER_KEY = k.DEALER_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY = k.BMV_KEY;

CREATE OR REPLACE VIEW V_FORECAST_VS_SALES_DAILY AS
SELECT * FROM DT_FORECAST_VS_SALES_DAILY;

/* ============================================================
   2) Customer Experience (Daily) -> DT + thin View
   ============================================================ */
CREATE OR REPLACE DYNAMIC TABLE DT_CX_SCORE_DAILY
  TARGET_LAG = '24 hours'
  WAREHOUSE = COMPUTE_WH
AS
WITH base AS (
  SELECT
    f.FEEDBACK_DATE_KEY  AS DATE_KEY,
    f.DEALER_KEY,
    vh.BMV_KEY,
    f.OVERALL_SATISFACTION_SCORE,
    f.RECOMMEND_SCORE,
    IFF(f.COMPLAINT_FLAG, 1, 0) AS COMPLAINT_INT
  FROM MARUTI_AUTO_DWH.INT.FCT_CUSTOMER_FEEDBACK f
  LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_VEHICLE vh
    ON vh.VEHICLE_KEY = f.VEHICLE_KEY
)
SELECT
  dd.CALENDAR_DATE                          AS DATE,
  d.DEALER_CODE, d.DEALER_GROUP_NAME,
  bmv.BRAND_CODE, bmv.BRAND_NAME,
  bmv.MODEL_CODE, bmv.MODEL_NAME,
  bmv.VARIANT_CODE, bmv.VARIANT_NAME,
  AVG(base.OVERALL_SATISFACTION_SCORE)      AS AVG_CSAT,
  AVG(base.RECOMMEND_SCORE)                 AS AVG_RECOMMEND,
  IFF(COUNT(*)=0, NULL, SUM(base.COMPLAINT_INT)/COUNT(*)) AS COMPLAINT_RATE
FROM base
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DATE dd ON dd.DATE_KEY = base.DATE_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_DEALER d ON d.DEALER_KEY = base.DEALER_KEY
LEFT JOIN MARUTI_AUTO_DWH.INT.DIM_BRAND_MODEL_VARIANT bmv ON bmv.BMV_KEY = base.BMV_KEY
GROUP BY
  dd.CALENDAR_DATE, d.DEALER_CODE, d.DEALER_GROUP_NAME,
  bmv.BRAND_CODE, bmv.BRAND_NAME, bmv.MODEL_CODE, bmv.MODEL_NAME, bmv.VARIANT_CODE, bmv.VARIANT_NAME;

CREATE OR REPLACE VIEW V_CX_SCORE_DAILY AS
SELECT * FROM DT_CX_SCORE_DAILY;

/* ============================================================
   3) First-time refresh to populate both DTs
   ============================================================ */
ALTER DYNAMIC TABLE DT_FORECAST_VS_SALES_DAILY REFRESH;
ALTER DYNAMIC TABLE DT_CX_SCORE_DAILY        REFRESH;

CREATE OR REPLACE STAGE MARUTI_SEMANTIC_STAGE;

