USE DATABASE MARUTI_AUTO_DWH;
USE SCHEMA INT;

-- Core conformed dimensions
ALTER TABLE DIM_DATE                     ADD CONSTRAINT PK_DIM_DATE                     PRIMARY KEY (DATE_KEY)                     NOT ENFORCED;
ALTER TABLE DIM_PLANT                    ADD CONSTRAINT PK_DIM_PLANT                    PRIMARY KEY (PLANT_KEY)                    NOT ENFORCED;
ALTER TABLE DIM_DEALER                   ADD CONSTRAINT PK_DIM_DEALER                   PRIMARY KEY (DEALER_KEY)                   NOT ENFORCED;
ALTER TABLE DIM_CUSTOMER                 ADD CONSTRAINT PK_DIM_CUSTOMER                 PRIMARY KEY (CUSTOMER_KEY)                 NOT ENFORCED;
ALTER TABLE DIM_SALESPERSON              ADD CONSTRAINT PK_DIM_SALESPERSON              PRIMARY KEY (SALESPERSON_KEY)              NOT ENFORCED;
ALTER TABLE DIM_BRAND_MODEL_VARIANT      ADD CONSTRAINT PK_DIM_BMV                      PRIMARY KEY (BMV_KEY)                      NOT ENFORCED;
ALTER TABLE DIM_VEHICLE                  ADD CONSTRAINT PK_DIM_VEHICLE                  PRIMARY KEY (VEHICLE_KEY)                  NOT ENFORCED;

-- Procurement / service dimensions
ALTER TABLE DIM_RAW_MATERIAL             ADD CONSTRAINT PK_DIM_RAW_MATERIAL             PRIMARY KEY (MATERIAL_KEY)                 NOT ENFORCED;
ALTER TABLE DIM_VENDOR                   ADD CONSTRAINT PK_DIM_VENDOR                   PRIMARY KEY (VENDOR_KEY)                   NOT ENFORCED;
ALTER TABLE DIM_SUPPLY_CONTRACT          ADD CONSTRAINT PK_DIM_SUPPLY_CONTRACT          PRIMARY KEY (CONTRACT_KEY)                 NOT ENFORCED;
ALTER TABLE DIM_SERVICE_CENTER           ADD CONSTRAINT PK_DIM_SERVICE_CENTER           PRIMARY KEY (SERVICE_CENTER_KEY)           NOT ENFORCED;
ALTER TABLE DIM_SERVICE_JOB_TYPE         ADD CONSTRAINT PK_DIM_SERVICE_JOB_TYPE         PRIMARY KEY (SERVICE_JOB_TYPE_KEY)         NOT ENFORCED;
ALTER TABLE DIM_FAULT_CODE               ADD CONSTRAINT PK_DIM_FAULT_CODE               PRIMARY KEY (FAULT_CODE_KEY)               NOT ENFORCED;

--- Add foreign keys on your INT facts

-- Production / Inventory
ALTER TABLE FCT_PRODUCTION_DAILY
