  ADD CONSTRAINT FK_FPIS_BMV     FOREIGN KEY (BMV_KEY)      REFERENCES DIM_BRAND_MODEL_VARIANT(BMV_KEY)   NOT ENFORCED;

-- Dispatch / Dealer stock
ALTER TABLE FCT_VEHICLE_DISPATCH
