  ADD CONSTRAINT FK_FCF_VEH      FOREIGN KEY (VEHICLE_KEY)                REFERENCES DIM_VEHICLE(VEHICLE_KEY) NOT ENFORCED,
  ADD CONSTRAINT FK_FCF_DEALER   FOREIGN KEY (DEALER_KEY)                 REFERENCES DIM_DEALER(DEALER_KEY)   NOT ENFORCED;


----Keys to select
-->Dimensions (INT)

-->DIM_DATE — key: DATE_KEY

-->DIM_DEALER — key: DEALER_KEY

-->DIM_BRAND_MODEL_VARIANT — key: BMV_KEY

-->DIM_PLANT — key: PLANT_KEY

-->Facts (INT)

--> FCT_BOOKING
--BOOKING_DATE_KEY → DIM_DATE.DATE_KEY
--DEALER_KEY → DIM_DEALER.DEALER_KEY
--BMV_KEY → DIM_BMV.BMV_KEY

--> FCT_RETAIL_SALES

---INVOICE_DATE_KEY → DIM_DATE.DATE_KEY (role: Invoice Date)
---DELIVERY_DATE_KEY → DIM_DATE.DATE_KEY (role: Delivery Date)
---DEALER_KEY → DIM_DEALER.DEALER_KEY
---BMV_KEY → DIM_BMV.BMV_KEY

--> FCT_DEALER_STOCK_SNAPSHOT

---DATE_KEY → DIM_DATE
---DEALER_KEY → DIM_DEALER
---BMV_KEY → DIM_BMV

--> FCT_VEHICLE_DISPATCH

--DISPATCH_DATE_KEY → DIM_DATE
--DEALER_KEY → DIM_DEALER
--PLANT_KEY → DIM_PLANT
--BMV_KEY → DIM_BMV	

---> Relationships in one glance
FCT_RETAIL_SALES.INVOICE_DATE_KEY → DIM_DATE.DATE_KEY (Cardinality: Many→One, Required: Yes)

FCT_RETAIL_SALES.DELIVERY_DATE_KEY → DIM_DATE.DATE_KEY (Alt date, Many→One, Optional)

FCT_RETAIL_SALES.DEALER_KEY → DIM_DEALER.DEALER_KEY (Many→One)

FCT_RETAIL_SALES.BMV_KEY → DIM_BRAND_MODEL_VARIANT.BMV_KEY (Many→One)

FCT_BOOKING.BOOKING_DATE_KEY → DIM_DATE.DATE_KEY

FCT_BOOKING.DEALER_KEY → DIM_DEALER.DEALER_KEY

FCT_BOOKING.BMV_KEY → DIM_BRAND_MODEL_VARIANT.BMV_KEY

FCT_DEALER_STOCK_SNAPSHOT.DATE_KEY → DIM_DATE.DATE_KEY

FCT_DEALER_STOCK_SNAPSHOT.DEALER_KEY → DIM_DEALER.DEALER_KEY

FCT_DEALER_STOCK_SNAPSHOT.BMV_KEY → DIM_BRAND_MODEL_VARIANT.BMV_KEY

FCT_VEHICLE_DISPATCH.DISPATCH_DATE_KEY → DIM_DATE.DATE_KEY

FCT_VEHICLE_DISPATCH.PLANT_KEY → DIM_PLANT.PLANT_KEY

FCT_VEHICLE_DISPATCH.DEALER_KEY → DIM_DEALER.DEALER_KEY

FCT_VEHICLE_DISPATCH.BMV_KEY → DIM_BRAND_MODEL_VARIANT.BMV_KEY


---Define metrics for all facts
--FCT_RETAIL_SALES
| Metric name                              | Expression (create as Metric / Calculated Metric)                                                                                                             | Notes / Format  |
| ---------------------------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------- | --------------- |
| **Revenue**                              | `SUM(FCT_RETAIL_SALES.ONROAD_PRICE)`                                                                                                                          | Currency        |
| **Ex-Showroom Revenue**                  | `SUM(FCT_RETAIL_SALES.EXSHOWROOM_PRICE)`                                                                                                                      | Currency        |
| **Discount Amount**                      | `SUM(FCT_RETAIL_SALES.DISCOUNT_AMOUNT)`                                                                                                                       | Currency        |
| **Net Revenue (Ex-Showroom – Discount)** | `SUM(FCT_RETAIL_SALES.EXSHOWROOM_PRICE - FCT_RETAIL_SALES.DISCOUNT_AMOUNT)`                                                                                   | Currency        |
| **Invoices**                             | `COUNT_DISTINCT(FCT_RETAIL_SALES.INVOICE_NO)`                                                                                                                 | Integer         |
| **Units Sold**                           | `COUNT_DISTINCT(FCT_RETAIL_SALES.VEHICLE_KEY)`                                                                                                                | Integer         |
| **Avg Selling Price (ASP)**              | `SUM(FCT_RETAIL_SALES.ONROAD_PRICE) / NULLIF(COUNT_DISTINCT(FCT_RETAIL_SALES.VEHICLE_KEY), 0)`                                                                | Number (₹/unit) |
| **Avg Discount %**                       | `SUM(FCT_RETAIL_SALES.DISCOUNT_AMOUNT) / NULLIF(SUM(FCT_RETAIL_SALES.EXSHOWROOM_PRICE), 0)`                                                                   | Percentage      |
| **Down Payment**                         | `SUM(FCT_RETAIL_SALES.DOWN_PAYMENT_AMOUNT)`                                                                                                                   | Currency        |
| **Loan Amount**                          | `SUM(FCT_RETAIL_SALES.LOAN_AMOUNT)`                                                                                                                           | Currency        |
| **Finance Penetration %**                | `COUNT_DISTINCT(CASE WHEN FCT_RETAIL_SALES.LOAN_AMOUNT > 0 THEN FCT_RETAIL_SALES.INVOICE_NO END) / NULLIF(COUNT_DISTINCT(FCT_RETAIL_SALES.INVOICE_NO), 0)`    | Percentage      |
| **Paid Revenue**                         | `SUM(CASE WHEN UPPER(FCT_RETAIL_SALES.PAYMENT_STATUS) = 'PAID' THEN FCT_RETAIL_SALES.ONROAD_PRICE ELSE 0 END)`                                                | Currency        |
| **Pending/Partial Revenue**              | `SUM(CASE WHEN UPPER(FCT_RETAIL_SALES.PAYMENT_STATUS) IN ('PENDING','PARTIAL') THEN FCT_RETAIL_SALES.ONROAD_PRICE ELSE 0 END)`                                | Currency        |
| **Cash Share %**                         | `SUM(CASE WHEN UPPER(FCT_RETAIL_SALES.PAYMENT_MODE) = 'CASH' THEN FCT_RETAIL_SALES.ONROAD_PRICE ELSE 0 END) / NULLIF(SUM(FCT_RETAIL_SALES.ONROAD_PRICE), 0)`  | Percentage      |
| **Non-Cash Share %**                     | `SUM(CASE WHEN UPPER(FCT_RETAIL_SALES.PAYMENT_MODE) <> 'CASH' THEN FCT_RETAIL_SALES.ONROAD_PRICE ELSE 0 END) / NULLIF(SUM(FCT_RETAIL_SALES.ONROAD_PRICE), 0)` | Percentage      |
| **Effective Discount per Unit**          | `SUM(FCT_RETAIL_SALES.DISCOUNT_AMOUNT) / NULLIF(COUNT_DISTINCT(FCT_RETAIL_SALES.VEHICLE_KEY), 0)`                                                             | Currency        |
| **Avg Down Payment %**                   | `SUM(FCT_RETAIL_SALES.DOWN_PAYMENT_AMOUNT) / NULLIF(SUM(FCT_RETAIL_SALES.ONROAD_PRICE), 0)`                                                                   | Percentage      |
| **Avg Loan %**                           | `SUM(FCT_RETAIL_SALES.LOAN_AMOUNT) / NULLIF(SUM(FCT_RETAIL_SALES.ONROAD_PRICE), 0)`                                                                           | Percentage      |

