--RAP and MP
USE ROLE ACCOUNTADMIN;
USE DATABASE MARUTI_AUTO_DWH;
CREATE SCHEMA IF NOT EXISTS GOV;
USE SCHEMA GOV;

/* ============================================================
   1) Roles for the demo
   ============================================================ */
CREATE OR REPLACE ROLE DATA_GOVERNOR;   -- bypass RAP, can see PII
CREATE OR REPLACE ROLE SALES_EAST;      -- only REGION='EAST'
CREATE OR REPLACE ROLE PII_PRIVILEGED;  -- can see PII but not bypass RAP

-- (Optionally grant to your user)
-- GRANT ROLE DATA_GOVERNOR  TO USER <YOUR_USER>;
-- GRANT ROLE SALES_EAST     TO USER <YOUR_USER>;
-- GRANT ROLE PII_PRIVILEGED TO USER <YOUR_USER>;

/* Basic usage on DB/SCHEMAS for these roles */
GRANT USAGE ON DATABASE MARUTI_AUTO_DWH TO ROLE DATA_GOVERNOR;
GRANT USAGE ON ALL SCHEMAS IN DATABASE MARUTI_AUTO_DWH TO ROLE DATA_GOVERNOR;
GRANT USAGE ON FUTURE SCHEMAS IN DATABASE MARUTI_AUTO_DWH TO ROLE DATA_GOVERNOR;

GRANT USAGE ON DATABASE MARUTI_AUTO_DWH TO ROLE SALES_EAST;
GRANT USAGE ON ALL SCHEMAS IN DATABASE MARUTI_AUTO_DWH TO ROLE SALES_EAST;
GRANT USAGE ON FUTURE SCHEMAS IN DATABASE MARUTI_AUTO_DWH TO ROLE SALES_EAST;

GRANT USAGE ON DATABASE MARUTI_AUTO_DWH TO ROLE PII_PRIVILEGED;
GRANT USAGE ON ALL SCHEMAS IN DATABASE MARUTI_AUTO_DWH TO ROLE PII_PRIVILEGED;
GRANT USAGE ON FUTURE SCHEMAS IN DATABASE MARUTI_AUTO_DWH TO ROLE PII_PRIVILEGED;

/* ============================================================
   2) Mapping table for RAP (role → allowed REGION)
   (lives in GOV schema; no new DIM tables created)
   ============================================================ */
USE SCHEMA MARUTI_AUTO_DWH.GOV;

CREATE OR REPLACE TABLE RLS_REGION_MAP (
  ROLE_NAME STRING,
  REGION    STRING
);

DELETE FROM RLS_REGION_MAP;
INSERT INTO RLS_REGION_MAP VALUES
  ('SALES_EAST','EAST');
-- Add more rows if you later create SALES_WEST / SALES_NORTH, etc.

/* ============================================================
   3) Row Access Policy (RAP) — by REGION
   ============================================================ */
CREATE OR REPLACE ROW ACCESS POLICY RAP_BY_REGION
AS (REGION STRING)
RETURNS BOOLEAN ->
  CASE
    WHEN IS_ROLE_IN_SESSION('DATA_GOVERNOR') THEN TRUE
    WHEN EXISTS (
      SELECT 1
      FROM MARUTI_AUTO_DWH.GOV.RLS_REGION_MAP m
      WHERE m.REGION = REGION
        AND IS_ROLE_IN_SESSION(m.ROLE_NAME)
    ) THEN TRUE
    ELSE FALSE
  END;

/* ============================================================
   4) Masking Policy (MP) — for PII
   ============================================================ */
CREATE OR REPLACE MASKING POLICY MP_MASK_MOBILE_ERP_CUSTOMER
  AS (mobile VARCHAR)
  RETURNS VARCHAR ->
    CASE
      WHEN CURRENT_ROLE() IN ('DATA_GOVERNOR')
        THEN mobile
      WHEN mobile IS NULL OR mobile = ''
        THEN mobile
      ELSE CONCAT('XXXXXX', RIGHT(mobile, 4))
    END;

CREATE OR REPLACE MASKING POLICY MP_MASK_EMAIL_ERP_CUSTOMER
  AS (email VARCHAR)
  RETURNS VARCHAR ->
    CASE
      WHEN CURRENT_ROLE() IN ('DATA_GOVERNOR')
        THEN email
      WHEN email IS NULL OR email = '' THEN email
      ELSE
        CONCAT(
          LEFT(email, 3),
          '*****',
          SUBSTR(email, POSITION('@' IN email))  -- from @ till end
        )
    END;

/* ============================================================
   5) Attach MP to existing INT.DIM_CUSTOMER (no new tables)
   ============================================================ */
USE SCHEMA MARUTI_AUTO_DWH.INT;

-- Ensure columns exist in your DIM_CUSTOMER
-- (EMAIL_ID, MOBILE_NUMBER were present in your earlier scripts)
ALTER TABLE DIM_CUSTOMER ALTER COLUMN EMAIL_ID UNSET  MASKING POLICY;
ALTER TABLE DIM_CUSTOMER ALTER COLUMN MOBILE_NUMBER UNSET  MASKING POLICY;

ALTER TABLE DIM_CUSTOMER
  MODIFY COLUMN EMAIL_ID
  SET MASKING POLICY MARUTI_AUTO_DWH.INT.MP_MASK_MOBILE_ERP_CUSTOMER;

ALTER TABLE DIM_CUSTOMER
  MODIFY COLUMN MOBILE_NUMBER
  SET MASKING POLICY MARUTI_AUTO_DWH.INT.MP_MASK_EMAIL_ERP_CUSTOMER;

USE SECONDARY ROLES NONE;
USE ROLE SALES_EAST;
SELECT * FROM DIM_CUSTOMER;

/* ============================================================
   6) RAP via a SECURE VIEW over your existing fact
      We do NOT alter your fact table schema.
      We project REGION by joining:
        FCT_RETAIL_SALES → DIM_DEALER (DEALER_KEY) → DIM_GEOGRAPHY (REGION via GEO_KEY)
   ============================================================ */
USE SCHEMA MARUTI_AUTO_DWH.INT;

CREATE OR REPLACE SECURE VIEW V_FCT_RETAIL_SALES_RAP AS
SELECT
  f.INVOICE_NO,
  f.INVOICE_DATE_KEY,
  f.DELIVERY_DATE_KEY,
  f.DEALER_KEY,
  f.BMV_KEY,
  f.CUSTOMER_KEY,
  f.SALESPERSON_KEY,
  f.VEHICLE_KEY,
  f.EXSHOWROOM_PRICE,
  f.DISCOUNT_AMOUNT,
  f.ONROAD_PRICE,
  f.PAYMENT_MODE,
  f.DOWN_PAYMENT_AMOUNT,
  f.LOAN_AMOUNT,
  f.PAYMENT_STATUS,
  f.BOOKING_ID,
  /* Join to expose REGION & DEALER_CODE for policy + readability */
  dd.DEALER_CODE,
  g.REGION,
  /* keep lineage columns if you like */
  f.DW_CREATED_TS,
  f.DW_LAST_UPDATED_TS,
  f.DW_BATCH_ID,
  f.DW_SOURCE_FILE_NAME
FROM INT.FCT_RETAIL_SALES f
LEFT JOIN INT.DIM_DEALER dd
  ON dd.DEALER_KEY = f.DEALER_KEY
LEFT JOIN INT.DIM_GEOGRAPHY g
  ON g.GEO_KEY = dd.GEO_KEY;

-- Attach RAP to the VIEW (on REGION)
ALTER VIEW V_FCT_RETAIL_SALES_RAP
  ADD ROW ACCESS POLICY MARUTI_AUTO_DWH.GOV.RAP_BY_REGION
  ON (REGION);

/* ============================================================
   7) Grants so roles can actually SELECT
   (We do not change your base tables; we just grant SELECT.)
   ============================================================ */
-- Base tables/views commonly used (adjust list if needed)
GRANT SELECT ON TABLE INT.DIM_CUSTOMER            TO ROLE DATA_GOVERNOR;
GRANT SELECT ON TABLE INT.DIM_CUSTOMER            TO ROLE SALES_EAST;
GRANT SELECT ON TABLE INT.DIM_CUSTOMER            TO ROLE PII_PRIVILEGED;
GRANT SELECT ON TABLE INT.DIM_DEALER              TO ROLE DATA_GOVERNOR;
GRANT SELECT ON TABLE INT.DIM_DEALER              TO ROLE SALES_EAST;
GRANT SELECT ON TABLE INT.DIM_GEOGRAPHY           TO ROLE DATA_GOVERNOR;
GRANT SELECT ON TABLE INT.DIM_GEOGRAPHY           TO ROLE SALES_EAST;
GRANT SELECT ON TABLE INT.FCT_RETAIL_SALES        TO ROLE DATA_GOVERNOR;
GRANT SELECT ON TABLE INT.FCT_RETAIL_SALES        TO ROLE SALES_EAST;

-- RAP view
GRANT SELECT ON VIEW  INT.V_FCT_RETAIL_SALES_RAP  TO ROLE DATA_GOVERNOR;
GRANT SELECT ON VIEW  INT.V_FCT_RETAIL_SALES_RAP  TO ROLE SALES_EAST;

/* If you use a warehouse for testing: */
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE DATA_GOVERNOR;
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE SALES_EAST;
GRANT USAGE ON WAREHOUSE COMPUTE_WH TO ROLE PII_PRIVILEGED;

-- 1) RAP: region-restricted role should only see EAST rows
GRANT ROLE SALES_EAST TO ROLE ACCOUNTADMIN;
USE SECONDARY ROLES NONE;
USE ROLE SALES_EAST;
-- USE WAREHOUSE <YOUR_WH>;

SELECT REGION, DEALER_CODE, COUNT(*) AS ROWS_DATA, SUM(ONROAD_PRICE) AS TOTAL_REVENUE
FROM MARUTI_AUTO_DWH.INT.V_FCT_RETAIL_SALES_RAP
GROUP BY REGION, DEALER_CODE
ORDER BY REGION, DEALER_CODE;
-- Expect only REGION='EAST'

-- 2) RAP bypass: full visibility
GRANT ROLE DATA_GOVERNOR TO ROLE ACCOUNTADMIN;
USE SECONDARY ROLES NONE;
USE ROLE DATA_GOVERNOR;

SELECT REGION, DEALER_CODE, COUNT(*) AS ROWS_DATA, SUM(ONROAD_PRICE) AS TOTAL_REVENUE
FROM MARUTI_AUTO_DWH.INT.V_FCT_RETAIL_SALES_RAP
GROUP BY REGION, DEALER_CODE
ORDER BY REGION, DEALER_CODE;

GRANT ROLE PII_PRIVILEGED TO ROLE ACCOUNTADMIN;
USE SECONDARY ROLES NONE;
USE ROLE PII_PRIVILEGED;

SELECT CUSTOMER_KEY, CUSTOMER_NAME, EMAIL_ID, MOBILE_NUMBER
FROM MARUTI_AUTO_DWH.INT.DIM_CUSTOMER
ORDER BY CUSTOMER_KEY
LIMIT 10;

USE ROLE DATA_GOVERNOR;

SELECT CUSTOMER_KEY, CUSTOMER_NAME, EMAIL_ID, MOBILE_NUMBER
FROM MARUTI_AUTO_DWH.INT.DIM_CUSTOMER
ORDER BY CUSTOMER_KEY
LIMIT 10;
